fn send_computer_use_observer_subscriptions(
    backend_registry: &BackendRegistry,
    actor_message_sender: Option<&mut ActorMessageLane>,
) -> Result<u64> {
    let body = serde_json::to_vec(&ComputerUseObserverCommand::Subscribe {
        after_event_cursor: 0,
        after_observation_sequence: 0,
    })?;
    let backends = backend_registry.connected_backend_ids().collect::<Vec<_>>();
    if backends.is_empty() {
        return Ok(0);
    }
    let sender = actor_message_sender.context("presentation actor-message lane is unavailable")?;
    let mut admitted = 0_u64;
    for backend in backends {
        sender.send(&actor_runtime::BackendActorMessageRequest {
            backend,
            sender: COMPUTER_USE_OBSERVER_ACTOR.to_string(),
            realm: BackendActorRealm::Daemon,
            actor: COMPUTER_USE_SERVER_ACTOR.to_string(),
            body: body.clone(),
        })?;
        admitted = admitted.saturating_add(1);
    }
    Ok(admitted)
}

impl Application {
    fn service_plugin_render_scheduler(&mut self) -> Result<()> {
        if let (Some(runtime), Some(renderer)) = (&self.wasm_runtime, &self.renderer) {
            runtime.reconcile_facet_resize_epochs(
                &renderer.staged_layouts.keys().copied().collect(),
            )?;
        }
        let actions = self
            .wasm_runtime
            .as_ref()
            .map(PresentationWasmRuntime::service_facets)
            .unwrap_or_default();
        for (pane, requests) in actions {
            for request in requests {
                use brood_protocol::facets::HostRequest;
                match request {
                    HostRequest::Render => {} // Runtime records explicit render demand.
                    HostRequest::ReleaseCapture => {
                        if self
                            .pointer_grab
                            .as_ref()
                            .is_some_and(|grab| grab.target.pane() == pane)
                        {
                            self.pointer_grab = None;
                        }
                    }
                    HostRequest::Capture => {
                        if let (Some(renderer), Some((x, y))) =
                            (&self.renderer, self.cursor_position)
                            && let Some(target) =
                                renderer.pointer_target_for_pane_at_window_point(pane, x, y)
                            && self
                                .pointer_grab
                                .as_ref()
                                .is_none_or(|grab| grab.target.pane() == pane)
                        {
                            if let Some(grab) = &mut self.pointer_grab {
                                grab.target = target;
                            } else {
                                self.pointer_grab = Some(PointerGrab {
                                    target,
                                    buttons: Vec::new(),
                                });
                            }
                        }
                    }
                    HostRequest::Focus => {
                        if let Some(renderer) = &mut self.renderer
                            && let Some(target) = renderer.focus_target_for_visible_pane(pane)
                            && let Some(change) = renderer.set_focus(target)
                        {
                            dispatch_focus_change(
                                self.wasm_runtime.as_ref(),
                                self.input_sender.as_mut(),
                                change,
                                self.window_focused,
                            )?;
                        }
                    }
                }
            }
        }
        let (Some(graphics), Some(runtime)) =
            (self.plugin_graphics.as_ref(), self.wasm_runtime.as_ref())
        else {
            return self.synchronize_event_loop_deadline(false);
        };
        let service = graphics.service_render_scheduler(&mut self.render_predictor)?;
        for (actor, hint) in service.hints {
            if std::env::var_os("BROOD_TRACE_RESIZE").is_some()
                && let Some(active) = self.active_synchronized_resize.as_ref()
            {
                let cohort_panes = hint
                    .relevant_panes
                    .iter()
                    .copied()
                    .filter(|pane| {
                        active.wait_panes.contains(pane) || active.affected_panes.contains(pane)
                    })
                    .collect::<Vec<_>>();
                if !cohort_panes.is_empty() {
                    eprintln!(
                        "resize-plugin render-hint actor={} generation={} epoch={} token={} panes={cohort_panes:?} target_ns={} deadline_ns={} event_watermark={} dispatch_us={}",
                        actor.name,
                        actor.generation,
                        active.epoch.id,
                        hint.token.0,
                        hint.target_presentation_time_ns,
                        hint.submission_deadline_ns,
                        hint.event_watermark,
                        active.started.elapsed().as_micros(),
                    );
                }
            }
            let identity = ActorIdentity {
                name: actor.name,
                generation: actor.generation,
            };
            if let Some(targets) = runtime.facet_targets(&identity)? {
                let renderer = self
                    .renderer
                    .as_ref()
                    .context("facet render requires native renderer")?;
                let targets = targets
                    .into_iter()
                    .map(|(mut target, epoch)| {
                        let extent = match epoch {
                            Some(epoch) => {
                                renderer.staged_plugin_scene_extent(target.pane, epoch)?
                            }
                            None => renderer.plugin_scene_extent(target.pane),
                        };
                        target.physical_width = extent.0;
                        target.physical_height = extent.1;
                        target.scale = f64::from(extent.2);
                        target.logical_width = f64::from(extent.0) / target.scale;
                        target.logical_height = f64::from(extent.1) / target.scale;
                        target.clip = [0.0, 0.0, target.logical_width, target.logical_height];
                        target.visible = hint.relevant_panes.contains(&target.pane);
                        target.focused =
                            renderer.focused_pane == Some(FocusedPane::Plugin(target.pane));
                        Ok(target)
                    })
                    .collect::<Result<Vec<_>>>()?;
                runtime.send_facet_render_hint(&identity, &hint, targets, renderer.generation)?;
            } else {
                runtime
                    .send_render_hint(&identity, hint)
                    .context("dispatch scheduled render hint")?;
            }
        }
        for token in service.composition_tokens {
            if !self.pending_render_token_resize_epochs.contains_key(&token) {
                self.pending_render_tokens.insert(token);
            }
        }
        if let Some(target_ns) = service.request_redraw_target_ns
            && let Some(renderer) = self.renderer.as_ref()
        {
            if let Some((pending_target_ns, _requested_at)) =
                self.pending_composition_redraw_request.as_mut()
            {
                *pending_target_ns = (*pending_target_ns).max(target_ns);
            } else {
                self.pending_composition_redraw_request = Some((target_ns, Instant::now()));
            }
            renderer.window.request_redraw();
        }
        self.synchronize_event_loop_deadline(false)
    }

    fn synchronize_event_loop_deadline(&mut self, record_past_deadlines: bool) -> Result<()> {
        let render_deadline = self
            .plugin_graphics
            .as_ref()
            .map(PluginGraphicsBridge::next_render_deadline)
            .transpose()?
            .flatten();
        self.synchronize_event_loop_deadline_with_render(render_deadline, record_past_deadlines);
        Ok(())
    }

    fn synchronize_event_loop_deadline_with_render(
        &mut self,
        render_deadline: Option<Instant>,
        record_past_deadlines: bool,
    ) {
        let auto_scroll_benchmark =
            std::env::var("BROOD_TERMINAL_SCROLL_BENCH_AUTO").as_deref() == Ok("1");
        let scroll_benchmark_deadline = if auto_scroll_benchmark {
            self.plugin_scroll_benchmark
                .as_ref()
                .filter(|benchmark| benchmark.input_events == 0)
                .and_then(|benchmark| benchmark.last_scene)
                .map(|last| last + Duration::from_millis(80))
        } else {
            None
        };
        let synchronized_resize_deadline =
            self.active_synchronized_resize.as_ref().and_then(|active| {
                synchronized_resize_wait_deadline(&active.presentation, active.deadline)
            });
        let native_resize_deadline = self
            .pending_native_window_resize
            .as_ref()
            .and_then(|pending| pending.deadline);
        let resize_deadline = match (synchronized_resize_deadline, native_resize_deadline) {
            (Some(left), Some(right)) => Some(left.min(right)),
            (Some(deadline), None) | (None, Some(deadline)) => Some(deadline),
            (None, None) => None,
        };
        let actor_poll_deadline = if self
            .wasm_runtime
            .as_ref()
            .is_some_and(PresentationWasmRuntime::requires_periodic_event_poll)
        {
            Some(
                *self
                    .next_periodic_actor_poll
                    .get_or_insert_with(|| Instant::now() + Duration::from_millis(50)),
            )
        } else {
            self.next_periodic_actor_poll = None;
            None
        };
        let deadlines = [
            (
                "window_resize",
                self.window_resize.as_ref().map(|resize| resize.settle_at),
            ),
            ("resize", resize_deadline),
            ("actor_poll", actor_poll_deadline),
            ("scroll_benchmark", scroll_benchmark_deadline),
            ("render", render_deadline),
        ];
        if record_past_deadlines {
            let now = Instant::now();
            for (source, deadline) in deadlines {
                if deadline.is_some_and(|deadline| deadline <= now) {
                    let count = self.past_deadline_sources.entry(source).or_default();
                    *count = count.saturating_add(1);
                }
            }
        }
        let deadline = next_event_loop_deadline(deadlines.map(|(_source, deadline)| deadline));
        if let Some(waker) = self.event_loop_deadline_waker.as_ref() {
            waker.set_deadline(deadline);
        }
    }

    fn reset_render_predictor_for_surface(&mut self) {
        let refresh_interval_ns = self
            .renderer
            .as_ref()
            .and_then(|renderer| window_refresh_interval_ns(renderer.window.as_ref()));
        self.render_predictor.reset(refresh_interval_ns);
        self.render_refresh_interval_ns = refresh_interval_ns;
    }

    fn sync_render_predictor_refresh(&mut self) {
        let refresh_interval_ns = self
            .renderer
            .as_ref()
            .and_then(|renderer| window_refresh_interval_ns(renderer.window.as_ref()));
        if refresh_interval_ns.is_some() && refresh_interval_ns != self.render_refresh_interval_ns {
            self.render_predictor.reset(refresh_interval_ns);
            self.render_refresh_interval_ns = refresh_interval_ns;
        }
    }

    fn subscribe_computer_use_observer(&mut self) -> Result<u64> {
        send_computer_use_observer_subscriptions(
            &self.backend_registry,
            self.actor_message_sender.as_mut(),
        )
    }

    fn accept_computer_use_frame_chunk(
        &mut self,
        backend: BackendId,
        chunk: ComputerObservationFrameChunk,
    ) -> Result<()> {
        anyhow::ensure!(
            chunk.protocol_version == brood_computer_use::COMPUTER_USE_PROTOCOL_VERSION,
            "computer-use frame chunk uses an unsupported protocol version"
        );
        anyhow::ensure!(
            chunk.chunk_count > 0 && chunk.chunk_count <= MAX_OBSERVER_FRAME_CHUNKS,
            "computer-use frame chunk count is outside the bounded transport"
        );
        anyhow::ensure!(
            chunk.chunk_index < chunk.chunk_count
                && !chunk.bytes.is_empty()
                && chunk.bytes.len() <= OBSERVER_FRAME_CHUNK_BYTES,
            "computer-use frame chunk is malformed"
        );
        if chunk.chunk_index == 0 {
            self.computer_use_frame_assemblies.insert(
                backend,
                ComputerUseFrameAssembly {
                    task: chunk.task.clone(),
                    sequence: chunk.sequence,
                    chunk_count: chunk.chunk_count,
                    next_chunk: 1,
                    bytes: chunk.bytes,
                },
            );
        } else {
            let assembly = self
                .computer_use_frame_assemblies
                .get_mut(&backend)
                .context("computer-use frame chunk arrived without its first chunk")?;
            let same_frame = assembly.task == chunk.task
                && assembly.sequence == chunk.sequence
                && assembly.chunk_count == chunk.chunk_count;
            anyhow::ensure!(
                same_frame && assembly.next_chunk == chunk.chunk_index,
                "computer-use frame chunks are not one ordered frame"
            );
            assembly.bytes.extend_from_slice(&chunk.bytes);
            assembly.next_chunk = assembly.next_chunk.saturating_add(1);
        }
        let complete = self
            .computer_use_frame_assemblies
            .get(&backend)
            .is_some_and(|assembly| assembly.next_chunk == assembly.chunk_count);
        if !complete {
            return Ok(());
        }
        let assembly = self
            .computer_use_frame_assemblies
            .remove(&backend)
            .context("completed computer-use frame assembly disappeared")?;
        let frame = serde_json::from_slice::<ComputerObservationFrame>(&assembly.bytes)
            .context("decode reassembled computer-use observer frame")?;
        anyhow::ensure!(
            frame.task == assembly.task && frame.sequence == assembly.sequence,
            "reassembled computer-use frame identity changed"
        );
        let update = self
            .computer_use_observer_updates
            .get_mut(&backend)
            .context("computer-use frame arrived before observer metadata")?;
        if update
            .frame
            .as_ref()
            .is_none_or(|current| current.sequence < frame.sequence)
        {
            update.frame = Some(frame);
        }
        self.sync_computer_use_presentation()
    }

    fn sync_computer_use_presentation(&mut self) -> Result<()> {
        let Some(renderer) = self.renderer.as_ref() else {
            return Ok(());
        };
        let active_backend = renderer.active_backend;
        let mut owned_panes = renderer
            .available_windows
            .iter()
            .filter_map(|window| {
                (!self
                    .computer_use_observer_updates
                    .contains_key(&window.backend)
                    && matches!(
                        window.size_authority,
                        ManagedWindowSizeAuthority::ServerPreferred { .. }
                    ))
                .then_some(window.pane)
            })
            .collect::<BTreeSet<_>>();
        let mut active_updates = Vec::new();
        for (backend, update) in &self.computer_use_observer_updates {
            let Some(lease) = update.lease.as_ref() else {
                continue;
            };
            for window in &renderer.available_windows {
                if window.backend != *backend || window.session != lease.session {
                    continue;
                }
                let Some(qualified) = self.backend_registry.backend_pane(window.pane) else {
                    continue;
                };
                if qualified.backend == *backend
                    && (lease.windows.is_empty() || lease.windows.contains(&qualified.pane))
                {
                    owned_panes.insert(window.pane);
                }
            }
            active_updates.push((*backend, update, lease));
        }
        let selected = active_updates
            .iter()
            .find(|(backend, _, _)| Some(*backend) == active_backend)
            .or_else(|| active_updates.first());
        let active_task = selected.map(|(_, _, lease)| lease.task.0.as_str());
        let automation_presentation = selected.map(|(backend, _, lease)| {
            let locked = !renderer.available_windows.iter().any(|window| {
                window.backend == *backend
                    && owned_panes.contains(&window.pane)
                    && matches!(
                        &window.automation,
                        ManagedWindowAutomationState::Automated {
                            task,
                            interaction: AutomationInteractionState::Unlocked,
                            ..
                        } if task == &lease.task.0
                    )
            });
            AutomationPresentationState {
                backend: *backend,
                task: lease.task.0.clone(),
                locked,
            }
        });
        let frame = selected.and_then(|(_, update, lease)| {
            update
                .frame
                .as_ref()
                .filter(|frame| frame.task == lease.task)
        });
        let renderer = self
            .renderer
            .as_mut()
            .context("renderer disappeared while applying computer-use authority")?;
        renderer.update_automation_spectator(
            frame,
            active_task,
            automation_presentation,
            owned_panes,
        )?;
        flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
        Ok(())
    }

    fn drop_frontend_wayland_state(&mut self) {
        drop_frontend_wayland_state(
            &mut self.wayland_drop,
            &mut self.renderer,
            &mut self.clipboard,
        );
    }

    fn disconnect_remote_backend(
        &mut self,
        backend: BackendId,
        message: &str,
    ) -> Result<Option<FocusChange>> {
        let remaining = self
            .input_sender
            .as_ref()
            .map_or(0, InputLane::backend_count);
        anyhow::ensure!(
            remaining > 1,
            "the only connected backend stopped: {message}"
        );
        let abort_reason = format!(
            "backend {} disconnected during synchronized resize: {message}",
            backend.0
        );
        let unavailable_panes = self
            .active_synchronized_resize
            .as_ref()
            .and_then(|active| active.target_tree.compose().ok())
            .map(|target| named_layout_panes(&target.layout))
            .unwrap_or_default()
            .into_iter()
            .filter(|pane| {
                self.backend_registry
                    .backend_pane(*pane)
                    .is_some_and(|qualified| qualified.backend == backend)
            })
            .collect::<Vec<_>>();
        let mut focus_change = if self.active_synchronized_resize.is_some() {
            self.abort_synchronized_resize_for_inventory_authority_change(
                &abort_reason,
                &unavailable_panes,
            )?
        } else {
            None
        };
        if let Some(runtime) = self.wasm_runtime.as_mut() {
            runtime.disconnect_backend(backend)?;
            runtime.drain_events()?;
            runtime.discard_backend_requests(backend);
        }
        anyhow::ensure!(
            self.input_sender
                .as_mut()
                .is_some_and(|lane| lane.remove_backend(backend)),
            "disconnected backend has no input lane"
        );
        if let Some(lane) = self.actor_message_sender.as_mut() {
            let _removed = lane.remove_backend(backend);
        }
        if let Some(lane) = self.backend_commands.as_mut() {
            let _removed = lane.remove_backend(backend)?;
        }
        anyhow::ensure!(
            self.backend_registry.retire(backend),
            "disconnected backend is absent from the connection registry"
        );
        self.backend_sessions.remove(&backend);
        self.pending_frames.remove(&backend);
        self.pending_backend_snapshots.remove(&backend);
        self.gpu_scene_completions.retire_backend(backend);
        self.computer_use_observer_updates.remove(&backend);
        self.computer_use_frame_assemblies.remove(&backend);
        if let Some(sender) = self.input_sender.as_mut() {
            sender.set_pane_routes(self.backend_registry.all_view_routes());
        }
        focus_change = self
            .renderer
            .as_mut()
            .and_then(|renderer| renderer.disconnect_backend(backend))
            .or(focus_change);
        self.sync_computer_use_presentation()?;
        if let Some(position) = self
            .remote_connections
            .iter()
            .position(|connection| connection.backend == backend)
        {
            let mut connection = self.remote_connections.remove(position);
            if let Err(error) = connection.reap() {
                eprintln!("remote backend {backend:?} stopped: {error:#}");
            }
        }
        if let Some(position) = self
            .ssh_deployments
            .iter()
            .position(|deployment| deployment.backend == Some(backend))
        {
            let mut deployment = self.ssh_deployments.remove(position);
            if let Err(error) = deployment.shutdown() {
                eprintln!("SSH deployment for backend {backend:?} stopped: {error:#}");
            }
        }
        if let Some(position) = self
            .container_deployments
            .iter()
            .position(|deployment| deployment.backend == Some(backend))
        {
            let mut deployment = self.container_deployments.remove(position);
            if let Err(error) = deployment.shutdown() {
                eprintln!("container deployment for backend {backend:?} stopped: {error:#}");
            }
        }
        self.backend_connected = self
            .input_sender
            .as_ref()
            .is_some_and(|lane| lane.backend_count() != 0);
        self.publish_backend_sessions()?;
        self.notify_backend_connection_failed(message)?;
        eprintln!("detached failed remote backend={backend:?}: {message}");
        Ok(focus_change)
    }

    fn connect_local_backend(&mut self) -> Result<()> {
        anyhow::ensure!(
            self.local_backend.is_none(),
            "the local backend is already connected"
        );
        let local = self
            .local_backend_template
            .clone()
            .context("local backends are unavailable without a server configuration")?;
        let target = local.target;
        let handshake = connect_or_spawn(&target, &local.server)?;
        let fast_path = open_presentation_fast_path(&target, &[FrameTransportKind::SharedMemory])?;
        let backend = self.backend_registry.allocate(Some(fast_path.generation));
        let session_id = bound_session_for_active(backend, fast_path.active_session)
            .map(|(_backend, session)| session);
        let input =
            brood_ipc::CriticalProducer::map(fast_path.input_fd.as_fd(), fast_path.generation)?;
        let frames =
            brood_ipc::CriticalConsumer::map(fast_path.frame_fd.as_fd(), fast_path.generation)?;
        let catalog =
            brood_ipc::CriticalConsumer::map(fast_path.catalog_fd.as_fd(), fast_path.generation)?;
        spawn_frame_updates(
            target,
            frames,
            brood_ipc::EventNotifier::from_owned_fd(fast_path.frame_notify_fd),
            fast_path.generation,
            fast_path.profile,
            backend,
            self.event_proxy
                .clone()
                .context("event loop proxy is unavailable")?,
        )?;
        spawn_catalog_updates(
            catalog,
            brood_ipc::EventNotifier::from_owned_fd(fast_path.catalog_notify_fd),
            backend,
            self.event_proxy
                .clone()
                .context("event loop proxy is unavailable")?,
        )?;
        spawn_actor_message_updates(
            brood_ipc::ActorMessageConsumer::map(
                fast_path.presentation_message_fd.as_fd(),
                fast_path.generation,
            )?,
            brood_ipc::EventNotifier::from_owned_fd(fast_path.presentation_message_notify_fd),
            backend,
            self.event_proxy
                .clone()
                .context("event loop proxy is unavailable")?,
        )?;
        self.input_sender
            .as_mut()
            .context("presentation input lane is unavailable")?
            .insert_local(
                backend,
                LocalInputLane {
                    producer: input,
                    notifications: brood_ipc::EventNotifier::from_owned_fd(
                        fast_path.input_notify_fd,
                    ),
                    generation: fast_path.generation,
                    sequence: 0,
                    deferred: VecDeque::new(),
                    deferred_high_water: 0,
                    coalesced_motion: 0,
                    pane_routes: BTreeMap::new(),
                },
            )?;
        self.actor_message_sender
            .as_mut()
            .context("presentation actor lane is unavailable")?
            .insert_local(
                backend,
                LocalActorMessageLane {
                    producer: brood_ipc::ActorMessageProducer::map(
                        fast_path.actor_message_fd.as_fd(),
                        fast_path.generation,
                    )?,
                    notifications: brood_ipc::EventNotifier::from_owned_fd(
                        fast_path.actor_message_notify_fd,
                    ),
                    generation: fast_path.generation,
                    sequence: 0,
                    deferred: VecDeque::new(),
                },
            )?;
        self.backend_commands
            .as_mut()
            .context("presentation command lane is unavailable")?
            .insert_local(
                backend,
                LocalBackendCommandLane::start(
                    brood_ipc::BackendMessageProducer::map(
                        fast_path.backend_request_fd.as_fd(),
                        fast_path.generation,
                    )?,
                    brood_ipc::EventNotifier::from_owned_fd(fast_path.backend_request_notify_fd),
                    brood_ipc::BackendMessageConsumer::map(
                        fast_path.backend_response_fd.as_fd(),
                        fast_path.generation,
                    )?,
                    brood_ipc::EventNotifier::from_owned_fd(fast_path.backend_response_notify_fd),
                    self.event_proxy
                        .clone()
                        .context("event loop proxy is unavailable")?,
                )?,
            )?;
        self.backend_registry
            .observe(backend, Some(fast_path.generation));
        self.local_backend = Some(backend);
        if let Some(runtime) = self.wasm_runtime.as_mut() {
            runtime.connect_backend(backend);
        }
        self.notify_backend_connected(backend)?;
        eprintln!(
            "connected local backend={backend:?} server_pid={} session={session_id:?}",
            handshake.server_pid
        );
        Ok(())
    }

    fn connect_remote_backend(&mut self, address: String) -> Result<()> {
        let connect = address
            .to_socket_addrs()
            .with_context(|| format!("resolve remote backend address {address:?}"))?
            .next()
            .context("remote backend address resolved to no socket addresses")?;
        let mut config = self.remote_config_template.clone().context(
            "dynamic remote connections are unavailable without remote transport configuration",
        )?;
        config.connect = connect;
        self.queue_remote_backend_config(config, RemoteAttachOrigin::Direct { address })?;
        Ok(())
    }

    fn queue_remote_backend_config(
        &mut self,
        mut config: remote::RemoteConfig,
        origin: RemoteAttachOrigin,
    ) -> Result<BackendId> {
        let backend = self.backend_registry.allocate(None);
        config.backend = backend;
        let proxy = self
            .event_proxy
            .clone()
            .context("presentation event loop proxy is unavailable")?;
        let description = origin.description();
        thread::Builder::new()
            .name("brood-client-remote-attach".to_string())
            .spawn(move || {
                let mut origin = origin;
                match remote::RemoteConnection::start(config, &proxy) {
                    Ok(connection) => {
                        if let Err(winit::event_loop::EventLoopClosed(event)) =
                            proxy.send_event(ClientEvent::RemoteBackendReady(Box::new(
                                RemoteBackendReady { connection, origin },
                            )))
                            && let ClientEvent::RemoteBackendReady(ready) = event
                        {
                            let RemoteBackendReady {
                                mut connection,
                                mut origin,
                            } = *ready;
                            drop(connection.shutdown());
                            drop(origin.shutdown());
                        }
                    }
                    Err(error) => {
                        let mut message = format!("{error:#}");
                        if let Err(shutdown_error) = origin.shutdown() {
                            let _write_result =
                                write!(message, "; cleanup failed: {shutdown_error:#}");
                        }
                        drop(proxy.send_event(ClientEvent::RemoteBackendFailed {
                            backend,
                            description,
                            message,
                        }));
                    }
                }
            })
            .context("spawn dynamic remote backend attachment")?;
        Ok(backend)
    }

    fn accept_remote_backend(
        &mut self,
        mut connection: remote::RemoteConnection,
        mut origin: RemoteAttachOrigin,
    ) -> Result<()> {
        let backend = connection.backend;
        let attach_result = (|| {
            let (input, actor_messages, backend_commands) = connection.take_lanes()?;
            self.input_sender
                .as_mut()
                .context("presentation input lane is unavailable")?
                .insert_remote(backend, input)?;
            self.actor_message_sender
                .as_mut()
                .context("presentation actor lane is unavailable")?
                .insert_remote(backend, actor_messages)?;
            self.backend_commands
                .as_mut()
                .context("presentation command lane is unavailable")?
                .insert_remote(backend, backend_commands)?;
            self.backend_registry
                .observe(backend, Some(connection.generation));
            connection.activate_disconnect_notifications()?;
            if let Some(runtime) = self.wasm_runtime.as_mut() {
                runtime.connect_backend(backend);
            }
            self.notify_backend_connected(backend)
        })();
        if let Err(error) = attach_result {
            if let Some(input) = self.input_sender.as_mut() {
                let _removed = input.remove_backend(backend);
            }
            if let Some(actors) = self.actor_message_sender.as_mut() {
                let _removed = actors.remove_backend(backend);
            }
            if let Some(commands) = self.backend_commands.as_mut() {
                drop(commands.remove_backend(backend));
            }
            let _retired = self.backend_registry.retire(backend);
            if let Some(runtime) = self.wasm_runtime.as_mut() {
                drop(runtime.disconnect_backend(backend));
            }
            drop(connection.shutdown());
            drop(origin.shutdown());
            return Err(error);
        }
        match &mut origin {
            RemoteAttachOrigin::Direct { address } => {
                eprintln!("connected dynamic remote backend={backend:?} address={address}");
            }
            RemoteAttachOrigin::Ssh(deployment) => {
                deployment.backend = Some(backend);
                eprintln!(
                    "connected in-client SSH backend={backend:?} target={}",
                    deployment.target
                );
            }
            RemoteAttachOrigin::Container(deployment) => {
                deployment.backend = Some(backend);
                eprintln!(
                    "connected in-client container backend={backend:?} container={}",
                    deployment.description
                );
            }
        }
        self.remote_connections.push(connection);
        match origin {
            RemoteAttachOrigin::Direct { .. } => {}
            RemoteAttachOrigin::Ssh(deployment) => self.ssh_deployments.push(deployment),
            RemoteAttachOrigin::Container(deployment) => {
                self.container_deployments.push(deployment);
            }
        }
        Ok(())
    }

    fn connect_ssh_backend(&mut self, mut deployment: SshBackendDeployment) -> Result<()> {
        let config = (|| -> Result<remote::RemoteConfig> {
            let offer = format!(
                "{}={}",
                deployment.ready.session_package,
                deployment.ready.session_root.display()
            );
            Ok(remote::RemoteConfig {
                backend: BackendId(0),
                connect: deployment.ready.connect,
                server_name: deployment.ready.server_name.clone(),
                server_certificate: deployment.ready.server_certificate.clone(),
                client_certificate: deployment.ready.client_certificate.clone(),
                client_private_key: deployment.ready.client_private_key.clone(),
                artifact_offers: brood_transport::package_offers(&offer, ArtifactRealm::Session)?,
                allowed_client_artifacts: Vec::new(),
                artifact_cache: brood_transport::default_artifact_cache(),
            })
        })();
        match config {
            Ok(config) => self
                .queue_remote_backend_config(config, RemoteAttachOrigin::Ssh(deployment))
                .map(|_backend| ()),
            Err(error) => {
                if let Err(shutdown_error) = deployment.shutdown() {
                    eprintln!(
                        "could not stop failed SSH deployment {}: {shutdown_error:#}",
                        deployment.target
                    );
                }
                Err(error)
            }
        }
    }

    fn connect_container_backend(
        &mut self,
        mut deployment: ContainerBackendDeployment,
    ) -> Result<()> {
        let config = (|| -> Result<remote::RemoteConfig> {
            let offer = format!(
                "{}={}",
                deployment.ready.session_package,
                deployment.ready.session_root.display()
            );
            Ok(remote::RemoteConfig {
                backend: BackendId(0),
                connect: deployment.ready.connect,
                server_name: deployment.ready.server_name.clone(),
                server_certificate: deployment.ready.server_certificate.clone(),
                client_certificate: deployment.ready.client_certificate.clone(),
                client_private_key: deployment.ready.client_private_key.clone(),
                artifact_offers: brood_transport::package_offers(&offer, ArtifactRealm::Session)?,
                allowed_client_artifacts: Vec::new(),
                artifact_cache: brood_transport::default_artifact_cache(),
            })
        })();
        match config {
            Ok(config) => self
                .queue_remote_backend_config(config, RemoteAttachOrigin::Container(deployment))
                .map(|_backend| ()),
            Err(error) => {
                if let Err(shutdown_error) = deployment.shutdown() {
                    eprintln!(
                        "could not stop failed container deployment {}: {shutdown_error:#}",
                        deployment.description
                    );
                }
                Err(error)
            }
        }
    }

    fn start_ssh_backend(&self, target: String) -> Result<()> {
        let deployer = self
            .ssh_deployer
            .as_deref()
            .context("the brood-remote SSH deployer is unavailable")?;
        let proxy = self
            .event_proxy
            .clone()
            .context("presentation event loop proxy is unavailable")?;
        start_ssh_backend_deployment(deployer, target, proxy)
    }

    fn start_container_backend(&self, image: &str, connection: Option<&str>) -> Result<()> {
        let deployer = self
            .container_deployer
            .as_deref()
            .context("the brood-remote container deployer is unavailable")?;
        let proxy = self
            .event_proxy
            .clone()
            .context("presentation event loop proxy is unavailable")?;
        start_container_backend_deployment(deployer, image, connection, proxy)
    }

    fn notify_backend_connected(&self, backend: BackendId) -> Result<()> {
        let Some(runtime) = self.wasm_runtime.as_ref() else {
            return Ok(());
        };
        if runtime.actor_identity(BACKEND_CATALOGUE_ACTOR_ID).is_none() {
            return Ok(());
        }
        let message = BackendCatalogueMessage::connected(backend);
        message.validate()?;
        runtime.send_actor_message(
            BACKEND_CATALOGUE_ACTOR_ID,
            BACKEND_CATALOGUE_CLIENT_SENDER.to_string(),
            serde_json::to_vec(&message).context("encode backend connection notification")?,
        )
    }

    fn notify_backend_connection_failed(&self, message: &str) -> Result<()> {
        let Some(runtime) = self.wasm_runtime.as_ref() else {
            return Ok(());
        };
        if runtime.actor_identity(BACKEND_CATALOGUE_ACTOR_ID).is_none() {
            return Ok(());
        }
        let notification = BackendCatalogueMessage::connection_failed(message);
        notification.validate()?;
        runtime.send_actor_message(
            BACKEND_CATALOGUE_ACTOR_ID,
            BACKEND_CATALOGUE_CLIENT_SENDER.to_string(),
            serde_json::to_vec(&notification).context("encode backend connection failure")?,
        )
    }

    fn publish_backend_sessions(&self) -> Result<()> {
        let Some(runtime) = self.wasm_runtime.as_ref() else {
            return Ok(());
        };
        if runtime.actor_identity(BACKEND_CATALOGUE_ACTOR_ID).is_none() {
            return Ok(());
        }
        let message = BackendCatalogueMessage::sessions(
            self.local_backend_template.is_some() && self.local_backend.is_none(),
            self.ssh_deployer.is_some(),
            self.container_deployer.is_some(),
            self.backend_registry
                .connected_backend_ids()
                .map(|backend| BackendCatalogueEntry {
                    backend,
                    label: if self.local_backend == Some(backend) {
                        "Local".to_string()
                    } else {
                        format!("Backend {}", backend.0)
                    },
                    sessions: self
                        .backend_sessions
                        .get(&backend)
                        .into_iter()
                        .flat_map(|snapshot| &snapshot.sessions)
                        .map(|session| BackendSessionEntry {
                            id: session.id,
                            name: session.name.clone(),
                            active: session.active,
                            windows: session.windows,
                            working_directory: session.working_directory.clone(),
                            project_id: session.project_id.clone(),
                            project_name: session.project_name.clone(),
                            branch: session.branch.clone(),
                            worktree: session.worktree,
                            git: session.git,
                            isolation: session.isolation.clone(),
                        })
                        .collect(),
                })
                .collect(),
        );
        message.validate()?;
        if std::env::var_os("BROOD_TRACE_PLUGIN_INPUT").is_some()
            && let BackendCatalogueMessage::Sessions { backends, .. } = &message
        {
            for backend in backends {
                let active = backend.sessions.iter().find(|session| session.active);
                eprintln!(
                    "backend session catalogue backend={} sessions={} active={} name={:?}",
                    backend.backend.0,
                    backend.sessions.len(),
                    active.map_or(0, |session| session.id),
                    active.map_or("", |session| session.name.as_str())
                );
            }
        }
        runtime.send_actor_message(
            BACKEND_CATALOGUE_ACTOR_ID,
            BACKEND_CATALOGUE_CLIENT_SENDER.to_string(),
            serde_json::to_vec(&message).context("encode backend session catalogue")?,
        )
    }
}

struct PluginScrollBenchmark {
    pane: u64,
    started: Instant,
    first_input: Option<Instant>,
    last_input: Option<Instant>,
    input_intervals_us: Vec<u128>,
    first_scene: Option<Instant>,
    last_scene: Option<Instant>,
    scene_intervals_us: Vec<u128>,
    first_presented: Option<Instant>,
    last_presented: Option<Instant>,
    intervals_us: Vec<u128>,
    input_events: u64,
    text_events: u64,
    redraws: u64,
    skipped: u64,
    reconfigures: u64,
    acquire_us: u128,
    encode_us: u128,
    submit_us: u128,
    present_us: u128,
    frames: u64,
    pending_scene: bool,
}

impl PluginScrollBenchmark {
    fn new(pane: u64) -> Self {
        Self {
            pane,
            started: Instant::now(),
            first_input: None,
            last_input: None,
            input_intervals_us: Vec::with_capacity(256),
            first_scene: None,
            last_scene: None,
            scene_intervals_us: Vec::with_capacity(256),
            first_presented: None,
            last_presented: None,
            intervals_us: Vec::with_capacity(256),
            input_events: 0,
            text_events: 0,
            redraws: 0,
            skipped: 0,
            reconfigures: 0,
            acquire_us: 0,
            encode_us: 0,
            submit_us: 0,
            present_us: 0,
            frames: 0,
            pending_scene: false,
        }
    }

    fn record_input(&mut self, now: Instant) {
        record_cadence(
            now,
            &mut self.first_input,
            &mut self.last_input,
            &mut self.input_intervals_us,
        );
        self.input_events = self.input_events.saturating_add(1);
    }

    const fn record_text(&mut self) {
        self.text_events = self.text_events.saturating_add(1);
    }

    fn record_scene(&mut self, now: Instant) {
        record_cadence(
            now,
            &mut self.first_scene,
            &mut self.last_scene,
            &mut self.scene_intervals_us,
        );
        self.pending_scene = true;
    }

    fn record_present(&mut self, now: Instant, timings: RenderTimings) {
        if !self.pending_scene {
            return;
        }
        self.pending_scene = false;
        record_cadence(
            now,
            &mut self.first_presented,
            &mut self.last_presented,
            &mut self.intervals_us,
        );
        self.acquire_us = self.acquire_us.saturating_add(timings.acquire_us);
        self.encode_us = self.encode_us.saturating_add(timings.encode_us);
        self.submit_us = self.submit_us.saturating_add(timings.submit_us);
        self.present_us = self.present_us.saturating_add(timings.present_us);
        self.frames = self.frames.saturating_add(1);
    }

    const fn record_redraw(&mut self) {
        self.redraws = self.redraws.saturating_add(1);
    }

    const fn record_skipped(&mut self) {
        self.skipped = self.skipped.saturating_add(1);
    }

    const fn record_reconfigure(&mut self) {
        self.reconfigures = self.reconfigures.saturating_add(1);
    }

    fn diagnostics(mut self) -> String {
        let input = cadence_diagnostics(
            &mut self.input_intervals_us,
            self.first_input,
            self.last_input,
            self.input_events,
        );
        let scenes = u64::try_from(self.scene_intervals_us.len())
            .unwrap_or(u64::MAX)
            .saturating_add(u64::from(self.first_scene.is_some()));
        let scene = cadence_diagnostics(
            &mut self.scene_intervals_us,
            self.first_scene,
            self.last_scene,
            scenes,
        );
        let presented = cadence_diagnostics(
            &mut self.intervals_us,
            self.first_presented,
            self.last_presented,
            self.frames,
        );
        let within_budget = self
            .intervals_us
            .iter()
            .filter(|interval| **interval <= 16_667)
            .count();
        let within_180hz_budget = self
            .intervals_us
            .iter()
            .filter(|interval| **interval <= 5_556)
            .count();
        format!(
            "{{\"pane\":{},\"input_events\":{},\"text_events\":{},\"presentation_turns\":{},\"presentation_events\":{},\"presentation_batch_counts\":{:?},\"input_fps_milli\":{},\"input_mean_interval_us\":{},\"input_p95_interval_us\":{},\"scenes\":{},\"scene_fps_milli\":{},\"scene_mean_interval_us\":{},\"scene_p95_interval_us\":{},\"redraws\":{},\"skipped\":{},\"reconfigures\":{},\"frames\":{},\"acquire_mean_us\":{},\"encode_mean_us\":{},\"submit_mean_us\":{},\"present_mean_us\":{},\"elapsed_us\":{},\"span_us\":{},\"fps_milli\":{},\"mean_interval_us\":{},\"p95_interval_us\":{},\"p99_interval_us\":{},\"max_interval_us\":{},\"within_5_556_us\":{},\"within_16_667_us\":{},\"intervals\":{}}}",
            self.pane,
            self.input_events,
            self.text_events,
            PLUGIN_SCROLL_PRESENTATION_TURNS.load(Ordering::Relaxed),
            PLUGIN_SCROLL_PRESENTATION_EVENTS.load(Ordering::Relaxed),
            PLUGIN_SCROLL_PRESENTATION_BATCH_COUNTS
                .each_ref()
                .map(|count| count.load(Ordering::Relaxed)),
            input.fps_milli,
            input.mean_interval_us,
            input.p95_interval_us,
            scenes,
            scene.fps_milli,
            scene.mean_interval_us,
            scene.p95_interval_us,
            self.redraws,
            self.skipped,
            self.reconfigures,
            self.frames,
            self.acquire_us / u128::from(self.frames.max(1)),
            self.encode_us / u128::from(self.frames.max(1)),
            self.submit_us / u128::from(self.frames.max(1)),
            self.present_us / u128::from(self.frames.max(1)),
            self.started.elapsed().as_micros(),
            presented.span_us,
            presented.fps_milli,
            presented.mean_interval_us,
            presented.p95_interval_us,
            presented.p99_interval_us,
            presented.max_interval_us,
            within_180hz_budget,
            within_budget,
            presented.intervals,
        )
    }

    fn scene_count(&self) -> u64 {
        u64::try_from(self.scene_intervals_us.len())
            .unwrap_or(u64::MAX)
            .saturating_add(u64::from(self.first_scene.is_some()))
    }
}

struct CadenceDiagnostics {
    span_us: u128,
    fps_milli: u128,
    mean_interval_us: u128,
    p95_interval_us: u128,
    p99_interval_us: u128,
    max_interval_us: u128,
    intervals: usize,
}

fn record_cadence(
    now: Instant,
    first: &mut Option<Instant>,
    last: &mut Option<Instant>,
    intervals_us: &mut Vec<u128>,
) {
    if let Some(previous) = *last {
        intervals_us.push(now.duration_since(previous).as_micros());
    } else {
        *first = Some(now);
    }
    *last = Some(now);
}

fn cadence_diagnostics(
    intervals_us: &mut [u128],
    first: Option<Instant>,
    last: Option<Instant>,
    events: u64,
) -> CadenceDiagnostics {
    intervals_us.sort_unstable();
    let intervals = intervals_us.len();
    let span_us = first
        .zip(last)
        .map_or(0, |(first, last)| last.duration_since(first).as_micros());
    let percentile = |percent: usize| {
        if intervals == 0 {
            return 0;
        }
        let rank = intervals.saturating_mul(percent).div_ceil(100);
        intervals_us
            .get(rank.saturating_sub(1).min(intervals - 1))
            .copied()
            .unwrap_or_default()
    };
    CadenceDiagnostics {
        span_us,
        fps_milli: if events <= 1 || span_us == 0 {
            0
        } else {
            u128::from(events - 1).saturating_mul(1_000_000_000) / span_us
        },
        mean_interval_us: if intervals == 0 {
            0
        } else {
            intervals_us.iter().sum::<u128>() / intervals as u128
        },
        p95_interval_us: percentile(95),
        p99_interval_us: percentile(99),
        max_interval_us: intervals_us.last().copied().unwrap_or(0),
        intervals,
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ProofManagedFrameAuthority {
    backend: BackendId,
    connection_generation: u64,
    backend_panes: BTreeSet<u64>,
    epoch: u64,
}

fn proof_managed_frame_authority(
    epoch: u64,
    routes: &[ManagedPaneRoute],
) -> Option<ProofManagedFrameAuthority> {
    let first = routes.first()?;
    let backend_panes = routes
        .iter()
        .filter(|route| {
            route.backend == first.backend
                && route.connection_generation == first.connection_generation
        })
        .map(|route| route.backend_pane)
        .collect::<BTreeSet<_>>();
    (epoch > 0 && routes.len() == 2 && backend_panes.len() == 2).then_some(
        ProofManagedFrameAuthority {
            backend: first.backend,
            connection_generation: first.connection_generation,
            backend_panes,
            epoch,
        },
    )
}

fn complete_tagged_managed_scene(
    event: &ClientEvent,
    authority: &ProofManagedFrameAuthority,
) -> bool {
    let ClientEvent::SceneFrame {
        backend,
        connection_generation,
        windows,
        ..
    } = event
    else {
        return false;
    };
    if *backend != authority.backend || *connection_generation != authority.connection_generation {
        return false;
    }
    let tagged = windows
        .iter()
        .filter_map(|window| {
            window
                .resize_epoch
                .map(|epoch| (window.backend_window_id, epoch))
        })
        .collect::<Vec<_>>();
    tagged.len() == authority.backend_panes.len()
        && tagged
            .iter()
            .all(|(_pane, epoch)| *epoch == authority.epoch)
        && tagged
            .iter()
            .map(|(pane, _epoch)| *pane)
            .collect::<BTreeSet<_>>()
            == authority.backend_panes
}

fn take_superseded_proof_frame<T>(
    held: &mut Option<(u64, T)>,
    active_epoch: Option<u64>,
) -> Option<(u64, T)> {
    held.as_ref()
        .is_some_and(|(held_epoch, _event)| {
            active_epoch.is_some_and(|active_epoch| active_epoch > *held_epoch)
        })
        .then(|| held.take())
        .flatten()
}

fn take_terminal_proof_frame<T>(
    authority: &mut Option<ProofManagedFrameAuthority>,
    held: &mut Option<(u64, T)>,
    terminal_epoch: u64,
) -> Option<(u64, T)> {
    let matches = authority
        .as_ref()
        .is_some_and(|authority| authority.epoch == terminal_epoch);
    if !matches {
        return None;
    }
    *authority = None;
    held.take()
}

impl Application {
    fn flush_managed_resource_releases(&mut self) {
        let releases = self
            .renderer
            .as_mut()
            .map_or_else(BTreeSet::new, Renderer::take_managed_resource_releases);
        let mut retained = Vec::new();
        for (backend, resource) in releases {
            let released_local = self
                .input_sender
                .as_mut()
                .is_some_and(|lane| lane.release_local_resource_to(backend, resource));
            if released_local {
                continue;
            }
            let result = self
                .backend_commands
                .as_ref()
                .context("backend command lane is unavailable")
                .and_then(|commands| commands.release_resource_to(backend, resource));
            if let Err(error) = result {
                retained.push((backend, resource));
                eprintln!(
                    "could not release retired managed resize resource backend={} resource={resource}: {error:#}",
                    backend.0
                );
            }
        }
        if let Some(renderer) = self.renderer.as_mut() {
            for (backend, resource) in retained {
                renderer.retain_managed_resource_release(backend, resource);
            }
        }
    }

    fn accept_frame(&mut self, event: ClientEvent) -> Result<()> {
        if let Some(authority) = self.proof_managed_frame_authority.as_ref()
            && self.proof_managed_frame_gate_enabled
            && self.proof_held_managed_frame.is_none()
            && complete_tagged_managed_scene(&event, authority)
        {
            eprintln!(
                "proof held complete tagged managed scene backend={} connection_generation={} epoch={} tagged_windows={} backend_panes={:?}",
                authority.backend.0,
                authority.connection_generation,
                authority.epoch,
                authority.backend_panes.len(),
                authority.backend_panes,
            );
            self.proof_held_managed_frame = Some((authority.epoch, event));
            return Ok(());
        }
        let (backend, connection_generation, sequence, width, height, windows) = match event {
            ClientEvent::SceneFrame {
                backend,
                connection_generation,
                sequence,
                width,
                height,
                windows,
            } => {
                if self.backend_registry.connection_generation(backend)
                    != Some(connection_generation)
                {
                    eprintln!(
                        "dropped scene from stale connection backend={} connection_generation={connection_generation}",
                        backend.0
                    );
                    return Ok(());
                }
                let mut windows = windows;
                for window in &mut windows {
                    window.window_id = self.backend_registry.view_pane(QualifiedPane {
                        backend,
                        pane: window.window_id,
                    });
                }
                if let Some(sender) = self.input_sender.as_mut() {
                    sender.set_pane_routes(self.backend_registry.all_view_routes());
                }
                (
                    backend,
                    connection_generation,
                    sequence,
                    width,
                    height,
                    windows,
                )
            }
            ClientEvent::TransportError(message) => return Err(anyhow!(message)),
            ClientEvent::ManagedResizeStatus { .. } => {
                return Err(anyhow!(
                    "managed resize status reached scene transport path"
                ));
            }
            ClientEvent::BackendDisconnected { .. } => {
                return Err(anyhow!("backend disconnect reached scene transport path"));
            }
            ClientEvent::RemoteArtifactInstalled { .. } => {
                return Err(anyhow!(
                    "remote artifact event reached scene transport path"
                ));
            }
            ClientEvent::FocusPresentation => {
                return Err(anyhow!(
                    "presentation focus event reached scene transport path"
                ));
            }
            ClientEvent::ClosePresentation => {
                return Err(anyhow!(
                    "presentation close event reached scene transport path"
                ));
            }
            ClientEvent::PluginGraphicsChanged { .. } | ClientEvent::PluginContentReused { .. } => {
                return Err(anyhow!(
                    "plugin graphics event reached scene transport path"
                ));
            }
            ClientEvent::PluginActorFrameChanged { .. } => {
                return Err(anyhow!("plugin actor frame reached scene transport path"));
            }
            ClientEvent::PluginRendererReplayRequested { .. } => {
                return Err(anyhow!(
                    "plugin renderer replay reached scene transport path"
                ));
            }
            ClientEvent::RenderSchedulingChanged => {
                return Err(anyhow!(
                    "render scheduling event reached scene transport path"
                ));
            }
            ClientEvent::EventLoopDeadlineReached { .. } => {
                return Err(anyhow!("deadline wake reached scene transport path"));
            }
            ClientEvent::GraphicsPreparationCapacityAvailable => {
                return Err(anyhow!(
                    "graphics-preparation capacity event reached scene transport path"
                ));
            }
            ClientEvent::GraphicsPreparationCompleted(_) => {
                return Err(anyhow!(
                    "graphics-preparation completion reached scene transport path"
                ));
            }
            ClientEvent::GpuSubmissionCapacityAvailable { .. } => {
                return Err(anyhow!(
                    "GPU-submission capacity event reached scene transport path"
                ));
            }
            ClientEvent::GpuSubmissionCompleted(_) => {
                return Err(anyhow!(
                    "GPU-submission completion reached scene transport path"
                ));
            }
            ClientEvent::RendererFailed { .. } => {
                return Err(anyhow!(
                    "renderer failure event reached scene transport path"
                ));
            }
            ClientEvent::BackendCommandCompleted { .. } => {
                return Err(anyhow!(
                    "backend command completion reached scene transport path"
                ));
            }
            ClientEvent::BackendSnapshot { .. } | ClientEvent::SessionCommandCompleted { .. } => {
                return Err(anyhow!("backend event reached scene transport path"));
            }
            ClientEvent::SshBackendReady(_) | ClientEvent::SshBackendFailed(_) => {
                return Err(anyhow!(
                    "SSH backend deployment event reached scene transport path"
                ));
            }
            ClientEvent::ContainerBackendReady(_) | ClientEvent::ContainerBackendFailed(_) => {
                return Err(anyhow!(
                    "container backend deployment event reached scene transport path"
                ));
            }
            ClientEvent::RemoteBackendReady(_) | ClientEvent::RemoteBackendFailed { .. } => {
                return Err(anyhow!(
                    "remote backend attachment event reached scene transport path"
                ));
            }
            ClientEvent::RemoteTerminalInputSent { .. } => {
                return Err(anyhow!(
                    "remote terminal timing event reached scene transport path"
                ));
            }
            ClientEvent::WaylandDroppedFile(_) => {
                return Err(anyhow!("Wayland file drop reached scene transport path"));
            }
            ClientEvent::ActorHostMessagesReady => {
                return Err(anyhow!("actor host message reached scene transport path"));
            }
            ClientEvent::ActorLifecycleReady => {
                return Err(anyhow!(
                    "actor lifecycle event reached scene transport path"
                ));
            }
            ClientEvent::BackendActorMessage { .. } => {
                return Err(anyhow!(
                    "session actor message reached scene transport path"
                ));
            }
        };
        if self.renderer.is_none() {
            self.pending_frames.insert(
                backend,
                ClientEvent::SceneFrame {
                    backend,
                    connection_generation,
                    sequence,
                    width,
                    height,
                    windows,
                },
            );
            return Ok(());
        }
        let (focus_change, released_resources, ready_managed) = self
            .renderer
            .as_mut()
            .context("renderer disappeared before scene selection")?
            .select_scene(
                backend,
                connection_generation,
                sequence,
                width,
                height,
                windows,
            )?;
        if self
            .renderer
            .as_ref()
            .and_then(|renderer| renderer.current_sequences.get(&backend))
            == Some(&sequence)
        {
            self.gpu_scene_completions.accept(CompletedFrameSequence {
                backend,
                connection_generation,
                sequence,
            });
        }
        for resource in released_resources {
            let released_local = self
                .input_sender
                .as_mut()
                .is_some_and(|lane| lane.release_local_resource_to(backend, resource));
            if !released_local {
                self.backend_commands
                    .as_ref()
                    .context("backend command lane is unavailable")?
                    .release_resource_to(backend, resource)?;
            }
        }
        for (pane, epoch) in ready_managed {
            if let Some(change) = self.note_synchronized_pane_ready(pane, epoch)? {
                dispatch_focus_change(
                    self.wasm_runtime.as_ref(),
                    self.input_sender.as_mut(),
                    change,
                    self.window_focused,
                )?;
            }
        }
        let renderer = self
            .renderer
            .as_mut()
            .context("renderer disappeared after managed frame readiness")?;
        renderer.sync_plugin_graphics_extents()?;
        if self
            .pointer_grab
            .as_ref()
            .is_some_and(|grab| renderer.focus_target_for_pane(grab.target.pane()).is_none())
        {
            // The grabbed pane may close before Winit reports the physical
            // release. End the client-side grab now; the backend deliberately
            // accepts this release even after removing the pane inventory.
            cancel_pointer_grab(
                self.wasm_runtime.as_ref(),
                self.input_sender.as_mut(),
                &mut self.pointer_routing,
                &mut self.pointer_grab,
                modifier_bits(self.modifiers),
            );
            route_pointer_motion(
                renderer,
                self.cursor_position,
                &mut self.pointer_grab,
                self.wasm_runtime.as_ref(),
                self.input_sender.as_mut(),
                &mut self.pointer_routing,
            );
        }
        if let Some(change) = focus_change {
            dispatch_focus_change(
                self.wasm_runtime.as_ref(),
                self.input_sender.as_mut(),
                change,
                self.window_focused,
            )?;
        }
        flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
        flush_renderer_plugin_resize_events_best_effort(
            self.wasm_runtime.as_ref(),
            renderer,
            "managed frame readiness",
        );
        self.flush_managed_resource_releases();
        Ok(())
    }

    fn release_superseded_proof_managed_frame(&mut self) -> Result<()> {
        let active_epoch = self
            .active_synchronized_resize
            .as_ref()
            .map(|active| active.epoch.id);
        let Some((held_epoch, held)) =
            take_superseded_proof_frame(&mut self.proof_held_managed_frame, active_epoch)
        else {
            return Ok(());
        };
        self.proof_managed_frame_gate_enabled = false;
        self.proof_managed_frame_authority = None;
        eprintln!(
            "proof released complete tagged managed scene held_epoch={held_epoch} active_epoch={}",
            active_epoch.unwrap_or(0),
        );
        self.accept_frame(held)
    }

    fn cleanup_proof_managed_frame_for_epoch(&mut self, epoch: u64, reason: &str) -> Result<()> {
        if self
            .proof_managed_frame_authority
            .as_ref()
            .is_none_or(|authority| authority.epoch != epoch)
        {
            return Ok(());
        }
        self.proof_managed_frame_gate_enabled = false;
        let Some((held_epoch, held)) = take_terminal_proof_frame(
            &mut self.proof_managed_frame_authority,
            &mut self.proof_held_managed_frame,
            epoch,
        ) else {
            eprintln!("proof disarmed tagged managed scene epoch={epoch} reason={reason}");
            return Ok(());
        };
        eprintln!("proof cleaned tagged managed scene held_epoch={held_epoch} reason={reason}");
        self.accept_frame(held)
    }

    fn publish_layout_state(&mut self) -> Result<()> {
        if self.window_resize.is_some() {
            return Ok(());
        }
        if !native_resize_allows_layout_publication(self.pending_native_window_resize.as_ref()) {
            // The root must never receive a nonce for geometry which has not
            // reached queue.present. A timed-out fallback is likewise kept
            // private until its projected old-content frame is presented.
            return Ok(());
        }
        let synchronized_inventory_changed = self
            .active_synchronized_resize
            .as_ref()
            .zip(self.renderer.as_ref())
            .is_some_and(|(active, renderer)| {
                !synchronized_resize_inventory_matches(active, &renderer.pane_inventory())
            });
        if synchronized_inventory_changed
            && let Some(change) = self.abort_synchronized_resize_for_inventory_change()?
        {
            dispatch_focus_change(
                self.wasm_runtime.as_ref(),
                self.input_sender.as_mut(),
                change,
                self.window_focused,
            )?;
        }
        if synchronized_inventory_changed
            && !self.pending_synchronized_layout_notifications.is_empty()
        {
            // Preserve actor mailbox order: the rejection belongs to the old
            // inventory and must precede the replacement layout publication.
            return Ok(());
        }
        if layout_state_publication_is_deferred(
            self.active_synchronized_resize.is_some(),
            self.renderer
                .as_ref()
                .is_some_and(|renderer| renderer.layout_state_dirty),
        ) {
            // A compatible inventory or focus publication is not evidence
            // that the active transaction may expose a partial wait set.
            // Keep it queued until exact readiness or the bounded global
            // deadline handled by settle_synchronized_resize. Incompatible
            // inventory was explicitly aborted above.
            return Ok(());
        }
        let live_actors = self
            .wasm_runtime
            .as_ref()
            .map_or_else(Vec::new, PresentationWasmRuntime::actor_identities);
        let failed_authority = self.layout_leases.lease_tokens().into_iter().any(|lease| {
            self.layout_holders
                .get(&lease.id)
                .is_some_and(|holder| !live_actors.contains(holder))
        });
        let candidates = self
            .wasm_runtime
            .as_ref()
            .map_or_else(Vec::new, PresentationWasmRuntime::layout_actor_identities);
        let selected = self
            .root_layout_actor
            .as_ref()
            .filter(|holder| {
                self.wasm_runtime
                    .as_ref()
                    .and_then(|runtime| runtime.actor_identity(&holder.name))
                    .as_ref()
                    == Some(holder)
            })
            .cloned()
            .or_else(|| candidates.first().cloned());
        if (failed_authority || selected != self.root_layout_actor)
            && let Some(change) =
                self.abort_layout_authority_state("layout authority changed before publication")?
        {
            dispatch_focus_change(
                self.wasm_runtime.as_ref(),
                self.input_sender.as_mut(),
                change,
                self.window_focused,
            )?;
        }
        let Some(renderer) = self.renderer.as_mut() else {
            return Ok(());
        };
        loop {
            let failed = self.layout_leases.lease_tokens().into_iter().find(|lease| {
                self.layout_holders
                    .get(&lease.id)
                    .is_some_and(|holder| !live_actors.contains(holder))
            });
            let Some(failed) = failed else {
                break;
            };
            let was_root = failed.id == self.layout_leases.root_token().id;
            let promoted = self.layout_leases.rest_token(failed).and_then(|child| {
                self.layout_holders
                    .get(&child.id)
                    .cloned()
                    .map(|holder| (child, holder))
            });
            if let Some((child, holder)) = promoted {
                let promoted = self.layout_leases.collapse_wrapper(failed)?;
                self.layout_holders.remove(&failed.id);
                self.layout_holders.insert(promoted.id, holder.clone());
                if was_root {
                    self.root_layout_actor = Some(holder.clone());
                }
                self.layout_publications.clear();
                renderer.layout_state_dirty = true;
                eprintln!(
                    "collapsed failed layout wrapper lease={} and promoted lease={} actor={}",
                    failed.id.0, child.id.0, holder.name
                );
                continue;
            }

            eprintln!(
                "revoked layout tree after leaf actor failure lease={}",
                failed.id.0
            );
            self.root_layout_actor = None;
            self.layout_holders.clear();
            self.layout_publications.clear();
            self.layout_leases = LayoutLeaseTree::default();
            renderer.layout_state_dirty = true;
            break;
        }
        let selected = self
            .root_layout_actor
            .as_ref()
            .filter(|holder| {
                self.wasm_runtime
                    .as_ref()
                    .and_then(|runtime| runtime.actor_identity(&holder.name))
                    .as_ref()
                    == Some(holder)
            })
            .cloned()
            .or_else(|| candidates.first().cloned());
        if selected != self.root_layout_actor {
            self.root_layout_actor = selected;
            self.layout_leases = LayoutLeaseTree::default();
            self.layout_holders.clear();
            self.layout_publications.clear();
            if let Some(holder) = &self.root_layout_actor {
                self.layout_holders
                    .insert(self.layout_leases.root_token().id, holder.clone());
                renderer.layout_state_dirty = true;
                eprintln!(
                    "granted root layout lease actor={} actor_generation={} lease_generation={}",
                    holder.name,
                    holder.generation,
                    self.layout_leases.root_token().generation
                );
            }
        }
        let Some(holder) = self.root_layout_actor.clone() else {
            return Ok(());
        };
        if candidates.len() > 1 {
            let ignored = candidates
                .iter()
                .filter(|candidate| **candidate != holder)
                .map(|candidate| candidate.name.as_str())
                .collect::<Vec<_>>();
            eprintln!(
                "root layout lease is exclusive holder={} ignored={ignored:?}",
                holder.name
            );
        }

        if renderer.layout_state_dirty {
            if renderer.layout_source == LayoutSource::NativeFallback
                && renderer.accepted_layout_differs_from_presented()
                && self.pending_presented_layout_revision.is_none()
            {
                self.pending_presented_layout_revision = Some(
                    next_presented_layout_revision(self.presented_layout_revision)
                        .context("presented fallback layout revision limit exceeded")?,
                );
            }
            let panes = renderer.pane_inventory();
            if layout_inventory_requires_update(&self.layout_leases, &panes) {
                self.layout_revision = self
                    .layout_revision
                    .checked_add(1)
                    .context("layout inventory revision limit exceeded")?;
                let previously_owned = self
                    .layout_leases
                    .lease_tokens()
                    .into_iter()
                    .flat_map(|token| self.layout_leases.owned_panes(token).unwrap_or_default())
                    .collect::<HashSet<_>>();
                let new_global_panes = newly_declared_global_plugin_panes(
                    &previously_owned,
                    &panes,
                    &renderer.plugin_pane_realms,
                );
                self.layout_leases
                    .update_inventory(self.layout_revision, &panes)?;
                if !new_global_panes.is_empty() {
                    self.layout_leases
                        .assign_panes(self.layout_leases.root_token(), &new_global_panes)?;
                }
                if let Some(runtime) = self.wasm_runtime.as_ref() {
                    for token in self.layout_leases.lease_tokens() {
                        let Some(holder) = self.layout_holders.get(&token.id) else {
                            continue;
                        };
                        let Some(pane) = runtime.pane_for_actor(holder) else {
                            continue;
                        };
                        if panes.contains(&pane) {
                            self.layout_leases.assign_panes(token, &[pane])?;
                        }
                    }
                }
            }
            if self
                .pending_native_window_resize
                .as_ref()
                .and_then(PendingNativeWindowResize::published_revision)
                .is_some()
            {
                self.layout_publications
                    .remove(&self.layout_leases.root_token().id);
            } else {
                self.layout_publications.clear();
            }
            renderer.layout_state_dirty = false;
        }
        let inventory_revision = self.layout_leases.inventory_revision();
        if inventory_revision == 0 {
            return Ok(());
        }

        let tokens = self.layout_leases.lease_tokens();
        if let Some(policy) = self.pointer_policy.as_mut() {
            policy.retain_current(&tokens, &self.layout_holders);
        }
        let root_lease = self.layout_leases.root_token().id;
        let native_resize_revision = self
            .pending_native_window_resize
            .as_ref()
            .and_then(PendingNativeWindowResize::published_revision);
        for lease in tokens {
            if !lease_receives_layout_publication(lease.id, root_lease, native_resize_revision) {
                continue;
            }
            if self.layout_publications.get(&lease.id) == Some(&inventory_revision) {
                continue;
            }
            let Some(viewport) = self.layout_leases.viewport_transform(lease) else {
                continue;
            };
            let Some(holder) = self.layout_holders.get(&lease.id).cloned() else {
                continue;
            };
            let owned_panes = self
                .layout_leases
                .owned_panes(lease)
                .context("layout lease is unavailable during state publication")?;
            let waitable_panes = self
                .layout_leases
                .waitable_panes(lease)
                .context("layout lease wait set is unavailable during state publication")?;
            let focused_pane = renderer
                .focused_pane_id()
                .filter(|pane| self.layout_leases.subtree_contains(lease, *pane));
            let viewport = viewport.pixel_rect(renderer.layout_extent());
            let message = renderer.layout_state_message(
                inventory_revision,
                self.presented_layout_revision,
                lease,
                &owned_panes,
                &waitable_panes,
                if lease.id == root_lease {
                    native_resize_revision
                } else {
                    None
                },
                focused_pane,
                LayoutSize {
                    w: viewport.w,
                    h: viewport.h,
                },
                self.layout_leases.has_rest(lease).unwrap_or(false),
            );
            if std::env::var_os("BROOD_TRACE_PLUGIN_INPUT").is_some() {
                let mut backends = message
                    .pane_realms
                    .iter()
                    .map(|realm| realm.backend.0)
                    .collect::<Vec<_>>();
                backends.sort_unstable();
                backends.dedup();
                eprintln!(
                    "layout-state backend groups lease={} actor={} backends={backends:?}",
                    lease.id.0, holder.name
                );
            }
            let payload =
                serde_json::to_vec(&message).context("encode client layout-state message")?;
            let result = self.wasm_runtime.as_ref().map_or(Ok(()), |runtime| {
                runtime.send_layout_state_to(&holder, payload)
            });
            if let Err(error) = result {
                eprintln!(
                    "deferred layout-state revision={} lease={} actor={} after mailbox error: {error:#}",
                    inventory_revision, lease.id.0, holder.name
                );
                continue;
            }
            self.layout_publications
                .insert(lease.id, inventory_revision);
            eprintln!(
                "queued layout-state revision={} lease={} actor={}",
                inventory_revision, lease.id.0, holder.name
            );
        }
        Ok(())
    }

    fn emit_setup_layout_quiescence_if_ready(&mut self) {
        if self.presented_layout_revision <= self.last_setup_quiescent_presented_layout_revision {
            return;
        }
        let inventory_revision = self.layout_leases.inventory_revision();
        let lease_tokens = self.layout_leases.lease_tokens();
        let layout_publications_current = !lease_tokens.is_empty()
            && lease_tokens
                .iter()
                .all(|lease| self.layout_publications.get(&lease.id) == Some(&inventory_revision));
        let state = SetupLayoutQuiescence {
            presented_layout_revision: self.presented_layout_revision,
            inventory_revision,
            native_resize_pending: self.pending_native_window_resize.is_some(),
            window_resize_pending: self.window_resize.is_some(),
            synchronized_layout_active: self.active_synchronized_resize.is_some(),
            staged_layouts: self
                .renderer
                .as_ref()
                .map_or(0, Renderer::staged_layout_count),
            pending_presented_layout_revision: self.pending_presented_layout_revision.is_some(),
            layout_state_dirty: self
                .renderer
                .as_ref()
                .is_none_or(|renderer| renderer.layout_state_dirty),
            pending_terminal_notifications: self.pending_synchronized_layout_notifications.len(),
            deferred_actor_host_messages: self.deferred_actor_host_messages.len(),
            runtime_outbound_host_messages: self
                .wasm_runtime
                .as_ref()
                .map_or(0, PresentationWasmRuntime::pending_outbound_host_messages),
            runtime_pending_actor_inputs: self
                .wasm_runtime
                .as_ref()
                .map_or(0, PresentationWasmRuntime::pending_actor_input_messages),
            runtime_observer_output_backlog: self
                .wasm_runtime
                .as_ref()
                .is_some_and(PresentationWasmRuntime::observer_output_backlog_pending),
            layout_publications_current,
        };
        if !state.is_ready() {
            return;
        }
        self.last_setup_quiescent_presented_layout_revision = self.presented_layout_revision;
        eprintln!("{}", trace_setup_layout_quiescence(state));
    }

    #[allow(
        clippy::needless_pass_by_value,
        reason = "notifications are constructed for one mailbox delivery and ownership makes that boundary explicit"
    )]
    fn send_synchronized_layout_notification(
        &self,
        actor: &ActorIdentity,
        notification: brood_wasm::SynchronizedLayoutNotification,
    ) -> Result<()> {
        let payload = serde_json::to_vec(&notification)
            .context("encode synchronized-layout actor notification")?;
        let runtime = self
            .wasm_runtime
            .as_ref()
            .context("layout actor runtime is unavailable")?;
        anyhow::ensure!(
            runtime.actor_identity(&actor.name).as_ref() == Some(actor),
            "layout actor {:?} generation {} is no longer current",
            actor.name,
            actor.generation,
        );
        runtime.send_actor_message(&actor.name, "layout-host".to_string(), payload)
    }

    fn queue_synchronized_layout_terminal_notification(
        &mut self,
        actor: &ActorIdentity,
        notification: brood_wasm::SynchronizedLayoutNotification,
    ) -> Result<()> {
        self.queue_synchronized_layout_terminal_notification_for_claim(actor, notification, None)
    }

    fn queue_synchronized_layout_terminal_notification_for_claim(
        &mut self,
        actor: &ActorIdentity,
        notification: brood_wasm::SynchronizedLayoutNotification,
        interaction_claim: Option<PointerInteractionClaimKey>,
    ) -> Result<()> {
        anyhow::ensure!(
            !matches!(
                notification,
                brood_wasm::SynchronizedLayoutNotification::Accepted(_)
            ),
            "Accepted is not a terminal synchronized-layout notification"
        );
        let request_id = synchronized_layout_notification_request_id(&notification);
        if self
            .pending_synchronized_layout_notifications
            .iter()
            .any(|pending| {
                pending.actor == *actor
                    && pending.request_id == request_id
                    && pending.interaction_claim == interaction_claim
            })
        {
            eprintln!(
                "coalesced duplicate synchronized layout terminal actor={} actor_generation={} request={request_id}",
                actor.name, actor.generation
            );
            return Ok(());
        }
        if self.pending_synchronized_layout_notifications.len()
            >= MAX_PENDING_SYNCHRONIZED_LAYOUT_NOTIFICATIONS
        {
            // Actor ingress stops as soon as one terminal backpressures, so
            // reaching this branch would require a caller to bypass that
            // boundary. Treat that as an internal invariant violation rather
            // than falsely reporting success after dropping a terminal.
            anyhow::bail!(
                "synchronized layout terminal backlog exceeded its bounded capacity actor={} actor_generation={} request={request_id}",
                actor.name,
                actor.generation
            );
        }
        self.pending_synchronized_layout_notifications.push_back(
            PendingSynchronizedLayoutNotification {
                actor: actor.clone(),
                request_id,
                notification,
                interaction_claim,
                attempts: 0,
            },
        );
        self.flush_synchronized_layout_terminal_notifications();
        Ok(())
    }

    fn flush_synchronized_layout_terminal_notifications(&mut self) {
        loop {
            let Some(pending) = self.pending_synchronized_layout_notifications.front() else {
                return;
            };
            let actor = pending.actor.clone();
            let request_id = pending.request_id;
            let notification = pending.notification.clone();
            let interaction_claim = pending.interaction_claim;
            let actor_generation_ended = self.wasm_runtime.as_ref().is_some_and(|runtime| {
                runtime.actor_identity(&actor.name).as_ref() != Some(&actor)
            });
            let actor_mailbox_closed = self
                .wasm_runtime
                .as_ref()
                .is_some_and(|runtime| runtime.actor_mailbox_is_closed(&actor));
            if actor_generation_ended || actor_mailbox_closed {
                eprintln!(
                    "discarded synchronized layout terminal after actor teardown actor={} actor_generation={} request={request_id} mailbox_closed={actor_mailbox_closed}",
                    actor.name, actor.generation,
                );
                self.pending_synchronized_layout_notifications.pop_front();
                self.pointer_interactions
                    .remove_actor_generation(&actor, "terminal-recipient-ended");
                continue;
            }
            match self.send_synchronized_layout_notification(&actor, notification) {
                Ok(()) => {
                    let attempts = self
                        .pending_synchronized_layout_notifications
                        .front()
                        .map_or(0, |pending| pending.attempts);
                    self.pending_synchronized_layout_notifications.pop_front();
                    if let Some(interaction_claim) = interaction_claim {
                        eprintln!(
                            "accepted synchronized layout terminal mailbox actor={} actor_generation={} request={request_id} interaction={} event_sequence={}",
                            actor.name,
                            actor.generation,
                            interaction_claim.interaction.0,
                            interaction_claim.event_sequence,
                        );
                        self.pointer_interactions
                            .terminal_notification_delivered(interaction_claim);
                    }
                    if attempts > 0 {
                        eprintln!(
                            "delivered deferred synchronized layout terminal actor={} actor_generation={} request={request_id} attempts={}",
                            actor.name,
                            actor.generation,
                            attempts.saturating_add(1),
                        );
                    }
                }
                Err(error) => {
                    let attempts = self
                        .pending_synchronized_layout_notifications
                        .front_mut()
                        .map_or(0, |pending| {
                            pending.attempts = pending.attempts.saturating_add(1);
                            pending.attempts
                        });
                    if attempts == 1 || attempts.is_power_of_two() {
                        eprintln!(
                            "deferred synchronized layout terminal actor={} actor_generation={} request={request_id} attempts={attempts}: {error:#}",
                            actor.name, actor.generation
                        );
                    }
                    return;
                }
            }
        }
    }

    fn clear_synchronized_layout_terminal_notifications(&mut self, reason: &str) {
        let cleared = self.pending_synchronized_layout_notifications.len();
        self.pending_synchronized_layout_notifications.clear();
        if cleared > 0 {
            eprintln!(
                "cleared synchronized layout terminal notifications count={cleared} reason={reason}"
            );
        }
    }

    fn schedule_presented_layout_revision(&mut self) -> Result<u64> {
        if let Some(revision) = self.pending_presented_layout_revision {
            return Ok(revision);
        }
        let revision = next_presented_layout_revision(self.presented_layout_revision)
            .context("presented layout revision limit exceeded")?;
        self.pending_presented_layout_revision = Some(revision);
        Ok(revision)
    }

    fn complete_presented_layout_revision(&mut self) -> Result<()> {
        let Some(revision) = self.pending_presented_layout_revision.take() else {
            return Ok(());
        };
        self.presented_layout_revision = revision;
        let publishes_native_resize =
            self.pending_native_window_resize
                .as_ref()
                .is_some_and(|pending| {
                    pending.stage == NativeWindowResizeStage::AwaitingBasePresentation
                        && pending.base_presented_layout_revision == revision
                });
        if publishes_native_resize {
            self.layout_publications
                .remove(&self.layout_leases.root_token().id);
        } else {
            self.layout_publications.clear();
        }
        if let Some(renderer) = self.renderer.as_mut() {
            renderer.settle_promoted_layout();
        }
        if publishes_native_resize {
            let native_resize_revision = self
                .next_native_resize_revision
                .checked_add(1)
                .context("native resize revision limit exceeded")?;
            self.next_native_resize_revision = native_resize_revision;
            let pending = self
                .pending_native_window_resize
                .as_mut()
                .context("native resize settlement disappeared after its base presentation")?;
            pending.publish(
                native_resize_revision,
                Instant::now(),
                SYNCHRONIZED_RESIZE_TIMEOUT,
            );
            self.native_resize_presentation_trace = NativeResizePresentationTrace {
                native_resize_revision,
                configure_sequence: pending.configure_sequence,
                width: pending.size.0,
                height: pending.size.1,
                phase: "awaiting-layout",
                pending_emit: true,
                ..NativeResizePresentationTrace::default()
            };
            eprintln!(
                "published settled native window resize native_resize_revision={native_resize_revision} configure_sequence={} base_presented_layout_revision={} size={}x{}",
                pending.configure_sequence,
                pending.base_presented_layout_revision,
                pending.size.0,
                pending.size.1,
            );
        }
        eprintln!("presented committed layout revision={revision}");
        Ok(())
    }

    fn settle_native_window_resize_timeout(&mut self) {
        let now = Instant::now();
        let matching_transaction_active = self
            .active_synchronized_resize
            .as_ref()
            .is_some_and(|active| active.native_resize_revision.is_some());
        let Some(pending) = self.pending_native_window_resize.as_mut() else {
            return;
        };
        if matching_transaction_active || !pending.ready_for_fallback(now) {
            return;
        }
        pending.stage = NativeWindowResizeStage::FallbackReady;
        pending.deadline = None;
        if let Some(renderer) = self.renderer.as_ref() {
            renderer.window.request_redraw();
        }
        eprintln!(
            "native window resize timed out awaiting root layout native_resize_revision={} configure_sequence={} size={}x{} elapsed_ms={}; scheduling projected fallback",
            pending.native_resize_revision.unwrap_or(0),
            pending.configure_sequence,
            pending.size.0,
            pending.size.1,
            pending.started.elapsed().as_millis(),
        );
    }

    fn finalize_native_window_resize_renderer(&mut self) -> Result<Option<FocusChange>> {
        let Some(renderer) = self.renderer.as_mut() else {
            return Ok(None);
        };
        let focus_change = renderer.complete_window_resize()?;
        if let Some(sender) = self.input_sender.as_mut() {
            send_presentation_configuration(sender, renderer);
        }
        flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
        flush_renderer_plugin_resize_events_best_effort(
            self.wasm_runtime.as_ref(),
            renderer,
            "native window resize finalization",
        );
        Ok(focus_change)
    }

    fn complete_presented_native_window_resize_fallback(&mut self) -> Result<Option<FocusChange>> {
        let fallback_ready = self
            .pending_native_window_resize
            .as_ref()
            .is_some_and(|pending| pending.stage == NativeWindowResizeStage::FallbackReady);
        if !fallback_ready {
            return Ok(None);
        }
        let pending = self
            .pending_native_window_resize
            .take()
            .context("native window resize fallback disappeared after presentation")?;
        let focus_change = self.finalize_native_window_resize_renderer()?;
        self.native_resize_presentation_trace = NativeResizePresentationTrace {
            native_resize_revision: pending.native_resize_revision.unwrap_or(0),
            configure_sequence: pending.configure_sequence,
            width: pending.size.0,
            height: pending.size.1,
            phase: "degraded",
            degraded: true,
            pending_emit: true,
            ..NativeResizePresentationTrace::default()
        };
        self.layout_publications.clear();
        eprintln!(
            "degraded native window resize after root-layout timeout native_resize_revision={} configure_sequence={} size={}x{} elapsed_ms={}",
            pending.native_resize_revision.unwrap_or(0),
            pending.configure_sequence,
            pending.size.0,
            pending.size.1,
            pending.started.elapsed().as_millis(),
        );
        Ok(focus_change)
    }

    fn complete_native_window_resize_after_synchronized_present(
        &mut self,
        native_resize_revision: u64,
        epoch: u64,
        wait_ready: usize,
        wait_total: usize,
        degraded: bool,
    ) -> Result<Option<FocusChange>> {
        let matches = self
            .pending_native_window_resize
            .as_ref()
            .is_some_and(|pending| {
                pending.stage == NativeWindowResizeStage::AwaitingRootLayout
                    && pending.native_resize_revision == Some(native_resize_revision)
            });
        anyhow::ensure!(
            matches,
            "presented native synchronized layout has no matching window resize"
        );
        let pending = self
            .pending_native_window_resize
            .take()
            .context("native window resize disappeared after synchronized presentation")?;
        let focus_change = self.finalize_native_window_resize_renderer()?;
        self.native_resize_presentation_trace = NativeResizePresentationTrace {
            native_resize_revision,
            configure_sequence: pending.configure_sequence,
            width: pending.size.0,
            height: pending.size.1,
            epoch,
            phase: if degraded { "degraded" } else { "promoted" },
            wait_ready,
            wait_total,
            degraded,
            pending_emit: true,
        };
        eprintln!(
            "finalized native window resize native_resize_revision={native_resize_revision} configure_sequence={} epoch={epoch} size={}x{} ready={wait_ready}/{wait_total} degraded={degraded} elapsed_ms={}",
            pending.configure_sequence,
            pending.size.0,
            pending.size.1,
            pending.started.elapsed().as_millis(),
        );
        Ok(focus_change)
    }

    fn emit_native_window_resize_trace(&mut self) {
        if !self.native_resize_presentation_trace.pending_emit {
            return;
        }
        let trace = self.native_resize_presentation_trace;
        if std::env::var_os("BROOD_TRACE_RESIZE").is_some() {
            let staged_count = self
                .renderer
                .as_ref()
                .map_or(0, Renderer::staged_layout_count);
            let (managed_expectations, managed_staged_resources) = self
                .renderer
                .as_ref()
                .map_or((0, 0), Renderer::managed_resize_counts);
            eprintln!(
                "window-resize-present native_resize_revision={} configure_sequence={} width={} height={} epoch={} phase={} wait_ready={}/{} staged_count={} managed_expectations={} managed_staged_resources={} degraded={}",
                trace.native_resize_revision,
                trace.configure_sequence,
                trace.width,
                trace.height,
                trace.epoch,
                trace.phase,
                trace.wait_ready,
                trace.wait_total,
                staged_count,
                managed_expectations,
                managed_staged_resources,
                trace.degraded,
            );
        }
        self.native_resize_presentation_trace.pending_emit = false;
    }

    fn restore_native_resize_awaiting_layout_trace(&mut self) {
        let Some(pending) = self.pending_native_window_resize.as_ref() else {
            return;
        };
        let Some(native_resize_revision) = pending.published_revision() else {
            return;
        };
        self.native_resize_presentation_trace = NativeResizePresentationTrace {
            native_resize_revision,
            configure_sequence: pending.configure_sequence,
            width: pending.size.0,
            height: pending.size.1,
            phase: "awaiting-layout",
            pending_emit: true,
            ..NativeResizePresentationTrace::default()
        };
    }

    fn cancel_active_layout_capture(&mut self, reason: &str) {
        let base_layout_revision = self.current_target_layout_revision();
        let Some(renderer) = self.renderer.as_mut() else {
            if let Some(capture) = self.policy_pointer_capture.take() {
                self.pointer_interactions
                    .remove(capture.interaction, "renderer-unavailable-during-cancel");
            }
            return;
        };
        cancel_policy_pointer_capture(
            renderer,
            self.wasm_runtime.as_ref(),
            &self.layout_holders,
            self.layout_revision,
            base_layout_revision,
            &mut self.policy_pointer_capture,
            &mut self.pointer_interactions,
            &mut self.pointer_event_sequence,
            modifier_bits(self.modifiers),
            reason,
        );
    }

    fn mark_deferred_plugin_scenes_ready(&mut self, deferred: &[DeferredPluginScene]) {
        let ready_at = Instant::now();
        for (pane, _sequence, terminal_input_sequence) in deferred {
            for input in &mut self.pending_plugin_inputs {
                if input.pane == *pane
                    && input.snapshot_dispatched.is_some()
                    && input.trace_sequence.is_some()
                    && input.trace_sequence <= *terminal_input_sequence
                {
                    input.graphics_ready = Some(ready_at);
                    input.ready = true;
                }
            }
        }
    }

    fn cancel_resize_render_tokens(&mut self, resize_epoch: u64) {
        let cancelled = take_resize_render_tokens_for_epoch(
            &mut self.pending_render_token_resize_epochs,
            resize_epoch,
        );
        for token in &cancelled {
            self.pending_render_tokens.remove(token);
        }
        if let Some(graphics) = self.plugin_graphics.as_ref() {
            graphics.cancel_accepted_tokens(cancelled);
        }
    }

    fn abort_layout_authority_state(&mut self, reason: &str) -> Result<Option<FocusChange>> {
        self.clear_synchronized_layout_terminal_notifications(reason);
        self.cancel_active_layout_capture(reason);
        self.pointer_interactions.clear(reason);
        if let Some(policy) = self.pointer_policy.as_mut() {
            policy.revoke_all();
        }
        if let Some(renderer) = self.renderer.as_mut() {
            renderer.projected_plugin_scenes.clear();
        }
        let mut focus_change = None;
        if let Some(active) = self.active_synchronized_resize.take() {
            let aborted_native_resize = active.native_resize_revision.is_some();
            if let Some(renderer) = self.renderer.as_mut() {
                let (change, deferred) = renderer.abort_staged_layout(active.epoch.id)?;
                focus_change = change;
                self.mark_deferred_plugin_scenes_ready(&deferred);
            } else if let Some(graphics) = self.plugin_graphics.as_ref() {
                graphics.abort_resize_epoch(active.epoch.id)?;
            }
            self.cancel_resize_render_tokens(active.epoch.id);
            if let Some(renderer) = self.renderer.as_mut() {
                flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
            }
            let notification = brood_wasm::SynchronizedLayoutNotification::Aborted(
                brood_wasm::SynchronizedLayoutAborted {
                    request_id: active.request_id,
                    resize_epoch: active.epoch,
                    reason: brood_wasm::SynchronizedLayoutRejectionReason::StaleLease,
                    message: reason.to_string(),
                    unavailable_panes: Vec::new(),
                },
            );
            self.queue_synchronized_layout_terminal_notification_for_claim(
                &active.requester,
                notification,
                active.interaction_claim,
            )?;
            eprintln!(
                "aborted synchronized layout actor={} request={} epoch={} reason={reason}",
                active.requester.name, active.request_id, active.epoch.id
            );
            self.cleanup_proof_managed_frame_for_epoch(active.epoch.id, "layout authority abort")?;
            self.resize_presentation_trace = ResizePresentationTrace::default();
            if aborted_native_resize {
                self.restore_native_resize_awaiting_layout_trace();
            }
        }
        if self.pending_presented_layout_revision.is_some()
            && self.pending_native_window_resize.is_none()
            && self
                .renderer
                .as_ref()
                .is_some_and(|renderer| renderer.layout_source == LayoutSource::Actor)
        {
            self.pending_presented_layout_revision = None;
            if let Some(renderer) = self.renderer.as_mut() {
                focus_change = renderer.reset_accepted_to_presented().or(focus_change);
            }
        }
        Ok(focus_change)
    }

    fn abort_synchronized_resize_for_inventory_change(&mut self) -> Result<Option<FocusChange>> {
        let Some(active) = self.active_synchronized_resize.as_ref() else {
            return Ok(None);
        };
        let expected_inventory = active
            .target_tree
            .compose()
            .map(|target| named_layout_panes(&target.layout))
            .unwrap_or_default();
        let current_inventory = self
            .renderer
            .as_ref()
            .map_or_else(Vec::new, Renderer::pane_inventory);
        let reason = format!(
            "a named target pane became unavailable during synchronized resize (target {expected_inventory:?}, current {current_inventory:?})"
        );
        self.abort_synchronized_resize_for_inventory_authority_change(&reason, &[])
    }

    fn abort_synchronized_resize_for_inventory_authority_change(
        &mut self,
        reason: &str,
        explicitly_unavailable_panes: &[u64],
    ) -> Result<Option<FocusChange>> {
        let Some(active) = self.active_synchronized_resize.as_ref() else {
            return Ok(None);
        };
        let current = self
            .renderer
            .as_ref()
            .map_or_else(BTreeSet::new, |renderer| {
                renderer.pane_inventory().into_iter().collect()
            });
        let managed_panes = self
            .renderer
            .as_ref()
            .map_or_else(BTreeSet::new, |renderer| {
                renderer
                    .available_windows
                    .iter()
                    .map(|window| window.pane)
                    .collect()
            });
        let target_panes = active.target_tree.compose().map(|target| {
            named_layout_panes(&target.layout)
                .into_iter()
                .collect::<Vec<_>>()
        })?;
        let unavailable_panes = unavailable_synchronized_target_panes(
            &target_panes,
            &current,
            &managed_panes,
            &self.backend_registry,
            explicitly_unavailable_panes,
        );
        self.cancel_active_layout_capture(reason);
        let active = self
            .active_synchronized_resize
            .take()
            .context("active synchronized resize disappeared during inventory abort")?;
        let aborted_native_resize = active.native_resize_revision.is_some();
        let mut focus_change = None;
        let mut deferred = Vec::new();
        if let Some(renderer) = self.renderer.as_mut() {
            let (change, released) = renderer.abort_staged_layout(active.epoch.id)?;
            focus_change = change;
            deferred = released;
        } else if let Some(graphics) = self.plugin_graphics.as_ref() {
            deferred = graphics.abort_resize_epoch(active.epoch.id)?;
        }
        self.cancel_resize_render_tokens(active.epoch.id);
        if let Some(renderer) = self.renderer.as_mut() {
            flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
        }
        self.mark_deferred_plugin_scenes_ready(&deferred);
        self.resize_presentation_trace = ResizePresentationTrace::default();
        if aborted_native_resize {
            self.restore_native_resize_awaiting_layout_trace();
        }
        self.abort_synchronized_layout_for_claim(
            &active.requester,
            active.request_id,
            active.epoch,
            brood_wasm::SynchronizedLayoutRejectionReason::StaleInventoryRevision,
            reason,
            unavailable_panes.clone(),
            active.interaction_claim,
        )?;
        eprintln!(
            "aborted synchronized layout actor={} request={} epoch={} unavailable_panes={unavailable_panes:?} reason={reason}",
            active.requester.name, active.request_id, active.epoch.id,
        );
        self.cleanup_proof_managed_frame_for_epoch(active.epoch.id, "inventory abort")?;
        Ok(focus_change)
    }

    fn abort_synchronized_resize_for_native_window_resize(
        &mut self,
        reason: &str,
    ) -> Result<Option<FocusChange>> {
        self.cancel_active_layout_capture(reason);
        let Some(active) = self.active_synchronized_resize.take() else {
            return Ok(None);
        };
        let mut focus_change = None;
        let deferred = if let Some(renderer) = self.renderer.as_mut() {
            let (change, deferred) = renderer.abort_staged_layout(active.epoch.id)?;
            focus_change = change;
            deferred
        } else if let Some(graphics) = self.plugin_graphics.as_ref() {
            graphics.abort_resize_epoch(active.epoch.id)?
        } else {
            Vec::new()
        };
        self.cancel_resize_render_tokens(active.epoch.id);
        if let Some(renderer) = self.renderer.as_mut() {
            flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
        }
        self.mark_deferred_plugin_scenes_ready(&deferred);
        self.resize_presentation_trace = ResizePresentationTrace::default();
        if !active.host_owned {
            self.abort_synchronized_layout_for_claim(
                &active.requester,
                active.request_id,
                active.epoch,
                brood_wasm::SynchronizedLayoutRejectionReason::Busy,
                reason,
                Vec::new(),
                active.interaction_claim,
            )?;
        }
        eprintln!(
            "aborted synchronized layout for native window resize actor={} request={} epoch={} reason={reason}",
            active.requester.name, active.request_id, active.epoch.id,
        );
        self.cleanup_proof_managed_frame_for_epoch(active.epoch.id, "native resize abort")?;
        Ok(focus_change)
    }

    fn abort_synchronized_interaction_preview_timeout(&mut self) -> Result<Option<FocusChange>> {
        self.abort_synchronized_resize_for_native_window_resize(
            "interaction preview timed out before exact pure pane content was ready",
        )
    }

    fn rollback_unannounced_synchronized_resize(
        &mut self,
        reason: &str,
    ) -> Result<Option<FocusChange>> {
        let Some(active) = self.active_synchronized_resize.take() else {
            return Ok(None);
        };
        let aborted_native_resize = active.native_resize_revision.is_some();
        let cancel_matching_capture = active.interaction.is_some_and(|interaction| {
            self.policy_pointer_capture
                .as_ref()
                .is_some_and(|capture| capture.interaction == interaction)
        });
        let mut focus_change = None;
        let mut deferred = Vec::new();
        if let Some(renderer) = self.renderer.as_mut() {
            match renderer.abort_staged_layout(active.epoch.id) {
                Ok((change, released)) => {
                    focus_change = change;
                    deferred = released;
                }
                Err(error) => {
                    eprintln!(
                        "could not fully roll back undelivered synchronized resize epoch={}: {error:#}",
                        active.epoch.id
                    );
                    focus_change = renderer.reset_accepted_to_presented();
                    match renderer.plugin_graphics.abort_resize_epoch(active.epoch.id) {
                        Ok(released) => {
                            for (pane, sequence, _terminal_input_sequence) in &released {
                                if let Err(refresh_error) =
                                    renderer.refresh_plugin_graphics(*pane, *sequence)
                                {
                                    eprintln!(
                                        "could not refresh deferred plugin scene pane={pane} sequence={sequence} after undelivered epoch={}: {refresh_error:#}",
                                        active.epoch.id
                                    );
                                }
                            }
                            deferred = released;
                        }
                        Err(abort_error) => {
                            eprintln!(
                                "could not abort undelivered graphics epoch={}: {abort_error:#}",
                                active.epoch.id
                            );
                        }
                    }
                }
            }
        } else if let Some(graphics) = self.plugin_graphics.as_ref()
            && let Err(error) = graphics.abort_resize_epoch(active.epoch.id)
        {
            eprintln!(
                "could not abort undelivered graphics epoch={}: {error:#}",
                active.epoch.id
            );
        }
        self.cancel_resize_render_tokens(active.epoch.id);
        if let Some(renderer) = self.renderer.as_mut() {
            flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
        }
        self.mark_deferred_plugin_scenes_ready(&deferred);
        if cancel_matching_capture {
            self.cancel_active_layout_capture(reason);
        }
        self.resize_presentation_trace = ResizePresentationTrace::default();
        if aborted_native_resize {
            self.restore_native_resize_awaiting_layout_trace();
        }
        self.reject_synchronized_layout_for_claim(
            &active.requester,
            active.request_id,
            brood_wasm::SynchronizedLayoutRejectionReason::Busy,
            reason,
            active.interaction_claim,
        )?;
        eprintln!(
            "rolled back unannounced synchronized layout actor={} request={} epoch={} reason={reason}",
            active.requester.name, active.request_id, active.epoch.id
        );
        self.cleanup_proof_managed_frame_for_epoch(active.epoch.id, "unannounced rollback")?;
        Ok(focus_change)
    }

    fn reject_synchronized_layout(
        &mut self,
        actor: &ActorIdentity,
        request_id: u64,
        reason: brood_wasm::SynchronizedLayoutRejectionReason,
        message: impl Into<String>,
    ) -> Result<()> {
        let message = message.into();
        eprintln!(
            "rejected synchronized layout actor={} request={} reason={reason:?}: {message}",
            actor.name, request_id
        );
        self.queue_synchronized_layout_terminal_notification(
            actor,
            brood_wasm::SynchronizedLayoutNotification::Rejected(
                brood_wasm::SynchronizedLayoutRejected {
                    request_id,
                    reason,
                    message,
                },
            ),
        )
    }

    fn reject_synchronized_layout_for_claim(
        &mut self,
        actor: &ActorIdentity,
        request_id: u64,
        reason: brood_wasm::SynchronizedLayoutRejectionReason,
        message: impl Into<String>,
        interaction_claim: Option<PointerInteractionClaimKey>,
    ) -> Result<()> {
        let message = message.into();
        eprintln!(
            "rejected synchronized layout actor={} request={} reason={reason:?}: {message}",
            actor.name, request_id
        );
        self.queue_synchronized_layout_terminal_notification_for_claim(
            actor,
            brood_wasm::SynchronizedLayoutNotification::Rejected(
                brood_wasm::SynchronizedLayoutRejected {
                    request_id,
                    reason,
                    message,
                },
            ),
            interaction_claim,
        )
    }

    #[allow(
        clippy::too_many_arguments,
        reason = "the terminal notification carries the complete synchronized-layout protocol context"
    )]
    fn abort_synchronized_layout_for_claim(
        &mut self,
        actor: &ActorIdentity,
        request_id: u64,
        resize_epoch: brood_wasm::ResizeEpoch,
        reason: brood_wasm::SynchronizedLayoutRejectionReason,
        message: impl Into<String>,
        unavailable_panes: Vec<u64>,
        interaction_claim: Option<PointerInteractionClaimKey>,
    ) -> Result<()> {
        let message = message.into();
        eprintln!(
            "aborted synchronized layout actor={} request={} epoch={} reason={reason:?}: {message}",
            actor.name, request_id, resize_epoch.id
        );
        self.queue_synchronized_layout_terminal_notification_for_claim(
            actor,
            brood_wasm::SynchronizedLayoutNotification::Aborted(
                brood_wasm::SynchronizedLayoutAborted {
                    request_id,
                    resize_epoch,
                    reason,
                    message,
                    unavailable_panes,
                },
            ),
            interaction_claim,
        )
    }

    fn current_target_layout_revision(&self) -> u64 {
        self.active_synchronized_resize
            .as_ref()
            .map_or(self.presented_layout_revision, |active| {
                active.epoch.target_layout_revision
            })
    }

    fn synchronized_target_tree_for_request(
        &self,
        submitted_lease: LayoutLeaseToken,
        inventory_revision: u64,
        fragment: brood_layout::LayoutFragment,
        focus: Option<u64>,
    ) -> Result<LayoutLeaseTree> {
        let mut target = self.layout_leases.clone();
        target.submit(submitted_lease, inventory_revision, fragment, focus)?;
        Ok(target)
    }

    fn submit_synchronized_layout(
        &mut self,
        sender: &ActorIdentity,
        request: brood_wasm::SubmitSynchronizedLayout,
    ) -> Result<Option<FocusChange>> {
        self.submit_synchronized_layout_with_ownership(sender, request, false)
    }

    fn submit_synchronized_layout_with_ownership(
        &mut self,
        sender: &ActorIdentity,
        request: brood_wasm::SubmitSynchronizedLayout,
        host_owned: bool,
    ) -> Result<Option<FocusChange>> {
        let request_id = request.request_id;
        let interaction_event = match (request.interaction, request.event_sequence) {
            (Some(interaction), Some(event_sequence)) if event_sequence > 0 => {
                Some((interaction, event_sequence))
            }
            (None, None) => None,
            _ => {
                self.reject_synchronized_layout(
                    sender,
                    request_id,
                    brood_wasm::SynchronizedLayoutRejectionReason::InvalidRequest,
                    "interaction and event_sequence must be present together, and the sequence must be non-zero",
                )?;
                return Ok(None);
            }
        };
        let submitted_lease = convert_actor_layout_lease(request.lease);
        if self.layout_holders.get(&submitted_lease.id) != Some(sender) {
            self.reject_synchronized_layout(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::StaleLease,
                format!("actor does not hold layout lease {}", submitted_lease.id.0),
            )?;
            return Ok(None);
        }
        let current_lease = self
            .layout_leases
            .lease_tokens()
            .into_iter()
            .find(|token| token.id == submitted_lease.id);
        if current_lease != Some(submitted_lease) {
            self.reject_synchronized_layout(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::StaleLease,
                "layout lease generation is no longer current",
            )?;
            return Ok(None);
        }
        self.pointer_interactions
            .retain_current_authority(&self.layout_holders, &self.layout_leases);
        let interaction_claim = if let Some((interaction, event_sequence)) = interaction_event {
            match self.pointer_interactions.claim(
                interaction,
                event_sequence,
                sender,
                submitted_lease,
                request_id,
            ) {
                Ok(claim) => Some(claim),
                Err(error) => {
                    self.reject_synchronized_layout(
                        sender,
                        request_id,
                        brood_wasm::SynchronizedLayoutRejectionReason::StaleInteraction,
                        error.to_string(),
                    )?;
                    return Ok(None);
                }
            }
        } else {
            None
        };
        let interaction_claim_key = interaction_claim.map(|claim| claim.key);
        let interaction_preview = interaction_claim.is_some_and(|claim| !claim.terminal);
        if !host_owned && !self.pending_synchronized_layout_notifications.is_empty() {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::Busy,
                "a previous synchronized layout terminal is waiting for delivery",
                interaction_claim_key,
            )?;
            return Ok(None);
        }
        let native_disposition = native_resize_request_disposition(
            self.pending_native_window_resize.as_ref(),
            request.native_resize_revision,
            self.active_synchronized_resize
                .as_ref()
                .is_some_and(|active| active.native_resize_revision.is_some()),
            self.window_resize.is_some(),
        );
        match native_disposition {
            NativeResizeRequestDisposition::Busy => {
                self.reject_synchronized_layout_for_claim(
                    sender,
                    request_id,
                    brood_wasm::SynchronizedLayoutRejectionReason::Busy,
                    "native window geometry is awaiting its root layout transaction",
                    interaction_claim_key,
                )?;
                return Ok(None);
            }
            NativeResizeRequestDisposition::Stale => {
                self.reject_synchronized_layout_for_claim(
                    sender,
                    request_id,
                    brood_wasm::SynchronizedLayoutRejectionReason::StaleBaseLayoutRevision,
                    "native resize revision is no longer current",
                    interaction_claim_key,
                )?;
                return Ok(None);
            }
            NativeResizeRequestDisposition::Ordinary | NativeResizeRequestDisposition::Matching => {
            }
        }
        let native_resize_request = native_disposition == NativeResizeRequestDisposition::Matching;
        if self.pending_presented_layout_revision.is_some() {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::Busy,
                "an ordinary layout commit is waiting for presentation",
                interaction_claim_key,
            )?;
            return Ok(None);
        }
        if request.presentation != brood_wasm::PresentationMode::ScaleThenAtomic {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::InvalidRequest,
                "the initial synchronized-resize lane supports ScaleThenAtomic presentation",
                interaction_claim_key,
            )?;
            return Ok(None);
        }
        if native_resize_request {
            let root_lease = self.layout_leases.root_token();
            let authenticated_root = submitted_lease == root_lease
                && self.root_layout_actor.as_ref() == Some(sender)
                && self.layout_holders.get(&root_lease.id) == Some(sender);
            if !authenticated_root || request.interaction.is_some() {
                self.reject_synchronized_layout_for_claim(
                    sender,
                    request_id,
                    brood_wasm::SynchronizedLayoutRejectionReason::InvalidRequest,
                    "native window resize must be submitted without a pointer interaction by the authenticated root layout holder",
                    interaction_claim_key,
                )?;
                return Ok(None);
            }
            let base_presented_layout_revision = self
                .pending_native_window_resize
                .as_ref()
                .map(|pending| pending.base_presented_layout_revision)
                .context("matching native window resize disappeared during validation")?;
            if request.base_layout_revision != base_presented_layout_revision {
                self.reject_synchronized_layout_for_claim(
                    sender,
                    request_id,
                    brood_wasm::SynchronizedLayoutRejectionReason::StaleBaseLayoutRevision,
                    format!(
                        "native window resize base {} does not match presented base {base_presented_layout_revision}",
                        request.base_layout_revision
                    ),
                    interaction_claim_key,
                )?;
                return Ok(None);
            }
        }
        let inventory_revision = self.layout_leases.inventory_revision();
        if request.inventory_revision != inventory_revision {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::StaleInventoryRevision,
                format!(
                    "inventory revision {} is not current after {}",
                    request.inventory_revision, inventory_revision
                ),
                interaction_claim_key,
            )?;
            return Ok(None);
        }
        let event_sequence = request.event_sequence.unwrap_or(0);
        let interaction_chain_base =
            interaction_claim.and_then(|claim| claim.chain_base_layout_revision);
        if let Some(active) = self.active_synchronized_resize.as_ref() {
            let same_requester = &active.requester == sender;
            let same_lease = active.epoch.lease == submitted_lease.id.0
                && active.epoch.lease_generation == submitted_lease.generation;
            if active.interaction != request.interaction || !same_requester || !same_lease {
                self.reject_synchronized_layout_for_claim(
                    sender,
                    request_id,
                    brood_wasm::SynchronizedLayoutRejectionReason::Busy,
                    "another pointer interaction owns the active workspace transaction",
                    interaction_claim_key,
                )?;
                return Ok(None);
            }
        }
        let current_base = self.current_target_layout_revision();
        if !synchronized_base_is_applicable(
            request.base_layout_revision,
            current_base,
            interaction_chain_base,
        ) {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::StaleBaseLayoutRevision,
                format!(
                    "base layout revision {} is not applicable to interaction chain {interaction_chain_base:?} after {current_base}",
                    request.base_layout_revision
                ),
                interaction_claim_key,
            )?;
            return Ok(None);
        }

        let mut unique_wait = request
            .wait_for_panes
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        if unique_wait.len() != request.wait_for_panes.len() {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::DuplicateWaitPane,
                "wait set contains a duplicate pane",
                interaction_claim_key,
            )?;
            return Ok(None);
        }
        let base_tree = self.layout_leases.clone();
        let wait_scope = if host_owned {
            base_tree.root_token()
        } else {
            submitted_lease
        };
        let waitable = base_tree
            .waitable_panes(wait_scope)
            .unwrap_or_default()
            .into_iter()
            .collect::<BTreeSet<_>>();
        if let Some(pane) = unique_wait.iter().find(|pane| !waitable.contains(pane)) {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::WaitPaneOutsideSubtree,
                format!("pane {pane} is outside the requesting lease subtree"),
                interaction_claim_key,
            )?;
            return Ok(None);
        }

        // Each epoch starts from the durable lease tree. The interaction
        // revision chain can authorize supersession, but it cannot authorize
        // carrying an unpromoted descendant response into the new epoch.
        let target_tree = match self.synchronized_target_tree_for_request(
            submitted_lease,
            request.inventory_revision,
            convert_actor_layout_fragment(request.fragment.layout, request.fragment.rest),
            request.focus,
        ) {
            Ok(target) => target,
            Err(error) => {
                self.reject_synchronized_layout_for_claim(
                    sender,
                    request_id,
                    brood_wasm::SynchronizedLayoutRejectionReason::InvalidRequest,
                    error.to_string(),
                    interaction_claim_key,
                )?;
                return Ok(None);
            }
        };
        let composed = match target_tree.compose() {
            Ok(composed) => composed,
            Err(error) => {
                self.reject_synchronized_layout_for_claim(
                    sender,
                    request_id,
                    brood_wasm::SynchronizedLayoutRejectionReason::InvalidRequest,
                    error.to_string(),
                    interaction_claim_key,
                )?;
                return Ok(None);
            }
        };
        let Some(renderer) = self.renderer.as_ref() else {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::InvalidRequest,
                "presentation renderer is unavailable",
                interaction_claim_key,
            )?;
            return Ok(None);
        };
        let target_extent = renderer.layout_extent();
        if native_resize_request {
            let waitable_target_panes = target_tree
                .waitable_panes(submitted_lease)
                .unwrap_or_default()
                .into_iter()
                .collect::<BTreeSet<_>>();
            unique_wait.extend(target_present_waitable_panes(
                &composed.layout,
                &waitable_target_panes,
            ));
        }
        let mut affected_panes = changed_layout_panes(
            &renderer.presented_layout,
            &composed.layout,
            renderer.layout_extent(),
        );
        if native_resize_request {
            affected_panes.extend(unique_wait.iter().copied());
        }
        if interaction_preview || host_owned {
            // Pure panes cannot be projected from their previous immutable
            // snapshot: even a one-pixel target change would stretch stale
            // content. Enroll changed facet and managed panes in this
            // preview's bounded cohort.
            let facet_panes = self
                .wasm_runtime
                .as_ref()
                .map_or_else(BTreeSet::new, |runtime| {
                    runtime.facet_pane_ids().collect::<BTreeSet<_>>()
                });
            let mut geometry_sensitive_panes = facet_panes;
            geometry_sensitive_panes
                .extend(renderer.available_windows.iter().map(|window| window.pane));
            unique_wait =
                interaction_preview_pure_cohort(&affected_panes, &geometry_sensitive_panes);
            // A pane removed by the candidate has no target geometry to
            // render. Its old surface disappears atomically with promotion;
            // only facets present in the target can join the ready cohort.
            unique_wait = target_present_pane_cohort(unique_wait, &composed.layout);
            affected_panes.clone_from(&unique_wait);
        }
        // Validate after host-driven enrollment so automatically selected
        // pure panes meet the same bounds, inventory, geometry and transport
        // requirements as panes named by the actor.
        if let Some(pane) = unique_wait.iter().find(|pane| !waitable.contains(pane)) {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::WaitPaneOutsideSubtree,
                format!("pane {pane} is outside the requesting lease subtree"),
                interaction_claim_key,
            )?;
            return Ok(None);
        }
        if unique_wait.len() > MAX_SYNCHRONIZED_WAIT_PANES {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::InvalidRequest,
                format!(
                    "wait set has {} panes; the limit is {MAX_SYNCHRONIZED_WAIT_PANES}",
                    unique_wait.len()
                ),
                interaction_claim_key,
            )?;
            return Ok(None);
        }
        if let Some(pane) = unique_wait.iter().find(|pane| {
            !renderer.pane_inventory().contains(pane) || composed.layout.pane_item(**pane).is_none()
        }) {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::IneligibleWaitPane,
                format!("pane {pane} cannot provide epoch-correlated content"),
                interaction_claim_key,
            )?;
            return Ok(None);
        }
        let plugin_panes = renderer
            .plugin_pane_realms
            .keys()
            .copied()
            .collect::<BTreeSet<_>>();
        if let Some(pane) = unique_wait.iter().find(|pane| {
            !wait_pane_has_current_managed_route(**pane, &plugin_panes, &self.backend_registry)
        }) {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::IneligibleWaitPane,
                format!("managed wait pane {pane} has no current transport route"),
                interaction_claim_key,
            )?;
            return Ok(None);
        }
        let Some(epoch_id) = allocate_resize_epoch(&mut self.next_resize_epoch) else {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::InvalidRequest,
                "managed resize epoch limit is exhausted",
                interaction_claim_key,
            )?;
            return Ok(None);
        };
        let Some(target_layout_revision) = next_presented_layout_revision(current_base) else {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::InvalidRequest,
                "presented layout revision limit is exhausted",
                interaction_claim_key,
            )?;
            return Ok(None);
        };
        let epoch = brood_wasm::ResizeEpoch {
            id: epoch_id,
            lease: submitted_lease.id.0,
            lease_generation: submitted_lease.generation,
            base_layout_revision: current_base,
            target_layout_revision,
        };

        let wait_pane_owners = unique_wait
            .iter()
            .filter_map(|pane| target_tree.pane_owner(*pane).map(|owner| (*pane, owner)))
            .collect::<BTreeMap<_, _>>();
        if wait_pane_owners.len() != unique_wait.len() {
            self.reject_synchronized_layout_for_claim(
                sender,
                request_id,
                brood_wasm::SynchronizedLayoutRejectionReason::IneligibleWaitPane,
                "a fixed wait pane has no layout lease owner",
                interaction_claim_key,
            )?;
            return Ok(None);
        }

        let mut regions = BTreeMap::new();
        // Preview promotion requires the same exact child-region chain as
        // release. Omitting its request leaves a ready pane cohort waiting
        // for a region response that can never arrive.
        if let Some((child, source_viewport, target_viewport)) = changed_rest_child(
            &base_tree,
            &target_tree,
            submitted_lease,
            renderer.layout_extent(),
        ) {
            let Some(holder) = self.layout_holders.get(&child.id).cloned() else {
                self.reject_synchronized_layout_for_claim(
                    sender,
                    request_id,
                    brood_wasm::SynchronizedLayoutRejectionReason::StaleLease,
                    format!("changed child lease {} has no current holder", child.id.0),
                    interaction_claim_key,
                )?;
                return Ok(None);
            };
            regions.insert(
                child.id,
                LayoutRegionDependency {
                    lease: child,
                    holder,
                    source_viewport,
                    target_viewport,
                    issued_at: Instant::now(),
                    delivered: false,
                    state: LayoutRegionResolutionState::Pending,
                },
            );
        }

        if let Some(previous) = self.active_synchronized_resize.take() {
            let superseded_epochs = request.interaction.map_or(0, |interaction| {
                self.pointer_interactions.note_superseded(interaction)
            });
            let mut aborted_focus_change = None;
            let deferred = if let Some(renderer) = self.renderer.as_mut() {
                let (change, released) = renderer.abort_staged_layout(previous.epoch.id)?;
                let successor_panes = affected_panes
                    .union(&unique_wait)
                    .copied()
                    .collect::<BTreeSet<_>>();
                renderer.hold_superseded_managed_recovery(epoch.id, &successor_panes);
                aborted_focus_change = change;
                released
            } else {
                Vec::new()
            };
            self.cancel_resize_render_tokens(previous.epoch.id);
            self.mark_deferred_plugin_scenes_ready(&deferred);
            let notification = brood_wasm::SynchronizedLayoutNotification::Superseded(
                brood_wasm::SynchronizedLayoutSuperseded {
                    request_id: previous.request_id,
                    resize_epoch: previous.epoch,
                    superseding_request_id: request_id,
                    superseding_resize_epoch: epoch,
                },
            );
            if !previous.host_owned {
                self.queue_synchronized_layout_terminal_notification_for_claim(
                    &previous.requester,
                    notification,
                    previous.interaction_claim,
                )?;
            }
            if !self.pending_synchronized_layout_notifications.is_empty() {
                let reason = "the superseded transaction terminal is waiting for mailbox delivery";
                self.cancel_active_layout_capture(reason);
                self.resize_presentation_trace = ResizePresentationTrace::default();
                if let Some(renderer) = self.renderer.as_mut() {
                    release_recovery_holds_for_epoch(
                        &mut renderer.pending_ordinary_managed_recovery,
                        epoch.id,
                    );
                }
                self.reject_synchronized_layout_for_claim(
                    sender,
                    request_id,
                    brood_wasm::SynchronizedLayoutRejectionReason::Busy,
                    reason,
                    interaction_claim_key,
                )?;
                return Ok(aborted_focus_change);
            }
            eprintln!(
                "synchronized interaction superseded interaction={} superseded_epochs={superseded_epochs}",
                request.interaction.map_or(0, |interaction| interaction.0)
            );
        }

        let now = Instant::now();
        let focus = composed.focus;
        let affected = affected_panes.iter().copied().collect::<Vec<_>>();
        let wait = unique_wait.iter().copied().collect::<Vec<_>>();
        let notification = brood_wasm::SynchronizedLayoutNotification::Accepted(
            brood_wasm::SynchronizedLayoutAccepted {
                request_id,
                resize_epoch: epoch,
                affected_panes: affected,
                wait_for_panes: wait,
            },
        );
        if let Some(interaction) = request.interaction {
            self.pointer_interactions
                .set_chain_base(interaction, request.base_layout_revision);
        }
        let superseded_epochs = request.interaction.map_or(0, |interaction| {
            self.pointer_interactions
                .records
                .get(&interaction)
                .map_or(0, |record| record.superseded_epochs)
        });
        self.active_synchronized_resize = Some(ActiveSynchronizedResize {
            request_id,
            interaction: request.interaction,
            event_sequence,
            interaction_claim: interaction_claim_key,
            native_resize_revision: request.native_resize_revision,
            interaction_preview,
            host_owned,
            superseded_epochs,
            epoch,
            requester: sender.clone(),
            base_tree,
            target_tree,
            target_extent,
            regions,
            wait_pane_owners,
            notified_panes: BTreeSet::new(),
            recovered_regions: BTreeSet::new(),
            recovered_managed_panes: BTreeSet::new(),
            recovered_managed_content: BTreeMap::new(),
            focus,
            wait_panes: unique_wait,
            ready_panes: BTreeSet::new(),
            affected_panes,
            started: now,
            deadline: now + SYNCHRONIZED_RESIZE_TIMEOUT,
            presentation: SynchronizedResizePresentation::Waiting,
        });
        self.resize_presentation_trace = ResizePresentationTrace {
            interaction: request.interaction.map_or(0, |interaction| interaction.0),
            event_sequence,
            epoch: epoch.id,
            phase: "projected",
            wait_ready: 0,
            wait_total: self
                .active_synchronized_resize
                .as_ref()
                .map_or(0, |active| active.wait_panes.len()),
            superseded_epochs,
            degraded: false,
        };
        if let Some(renderer) = self.renderer.as_mut() {
            let _focus_change = renderer.project_staged_layout(epoch.id, composed);
        }
        if let Some(native_resize_revision) = request.native_resize_revision
            && let Some(pending) = self.pending_native_window_resize.as_ref()
        {
            self.native_resize_presentation_trace = NativeResizePresentationTrace {
                native_resize_revision,
                configure_sequence: pending.configure_sequence,
                width: pending.size.0,
                height: pending.size.1,
                epoch: epoch.id,
                phase: "projected",
                wait_total: self
                    .active_synchronized_resize
                    .as_ref()
                    .map_or(0, |active| active.wait_panes.len()),
                pending_emit: true,
                ..NativeResizePresentationTrace::default()
            };
        }
        if !host_owned
            && let Err(error) = self.send_synchronized_layout_notification(sender, notification)
        {
            let reason =
                format!("host could not deliver synchronized layout acceptance: {error:#}");
            let focus_change = self.rollback_unannounced_synchronized_resize(&reason)?;
            return Ok(focus_change);
        }
        self.discover_and_dispatch_layout_regions()?;
        self.notify_synchronized_panes();
        let (accepted_focus, accepted_wait_panes) = self
            .active_synchronized_resize
            .as_ref()
            .map_or((0, String::new()), |active| {
                (
                    active.focus.unwrap_or(0),
                    trace_pane_ids(&active.wait_panes),
                )
            });
        let target_rects = self.renderer.as_ref().map_or_else(String::new, |renderer| {
            renderer
                .staged_layouts
                .get(&epoch.id)
                .map_or_else(String::new, |target| {
                    trace_layout_pane_rects(&target.layout, renderer.layout_extent())
                })
        });
        eprintln!(
            "accepted synchronized layout actor={} request={} interaction={} event_sequence={} native_resize_revision={} epoch={} base_revision={} target_revision={} region_final=0/{} pane_ready=0/{} wait={} affected={} mode={:?} actor_generation={} focus={} recovered_regions=[] wait_for_panes=[{}] target_rects=[{}]",
            sender.name,
            request_id,
            request.interaction.map_or(0, |interaction| interaction.0),
            event_sequence,
            request.native_resize_revision.unwrap_or(0),
            epoch.id,
            epoch.base_layout_revision,
            epoch.target_layout_revision,
            self.active_synchronized_resize
                .as_ref()
                .map_or(0, |active| active.regions.len()),
            self.active_synchronized_resize
                .as_ref()
                .map_or(0, |active| active.wait_panes.len()),
            self.active_synchronized_resize
                .as_ref()
                .map_or(0, |active| active.wait_panes.len()),
            self.active_synchronized_resize
                .as_ref()
                .map_or(0, |active| active.affected_panes.len()),
            request.presentation,
            sender.generation,
            accepted_focus,
            accepted_wait_panes,
            target_rects,
        );
        self.release_superseded_proof_managed_frame()?;
        if self
            .active_synchronized_resize
            .as_ref()
            .is_some_and(|active| active.wait_panes.is_empty())
        {
            return self.finish_synchronized_resize(false);
        }
        Ok(None)
    }

    fn discover_changed_rest_region(&mut self, parent: LayoutLeaseToken) -> Result<()> {
        let Some(active) = self.active_synchronized_resize.as_ref() else {
            return Ok(());
        };
        let extent = active.target_extent;
        let Some((child, source_viewport, target_viewport)) =
            changed_rest_child(&active.base_tree, &active.target_tree, parent, extent)
        else {
            return Ok(());
        };
        if active.regions.contains_key(&child.id) {
            return Ok(());
        }
        anyhow::ensure!(
            active.regions.len() < MAX_ACTIVE_RESIZE_REGIONS,
            "active resize region dependency limit is exhausted"
        );
        let holder = self
            .layout_holders
            .get(&child.id)
            .cloned()
            .with_context(|| format!("changed child lease {} has no holder", child.id.0))?;
        let active = self
            .active_synchronized_resize
            .as_mut()
            .context("active resize disappeared while adding child region")?;
        active.regions.insert(
            child.id,
            LayoutRegionDependency {
                lease: child,
                holder,
                source_viewport,
                target_viewport,
                issued_at: Instant::now(),
                delivered: false,
                state: LayoutRegionResolutionState::Pending,
            },
        );
        Ok(())
    }

    fn reproject_active_region_target(&mut self) -> Result<Option<FocusChange>> {
        let active = self
            .active_synchronized_resize
            .as_ref()
            .context("active resize disappeared while composing a region target")?;
        let epoch = active.epoch.id;
        let composed = active.target_tree.compose()?;
        let Some(renderer) = self.renderer.as_ref() else {
            return Ok(None);
        };
        let extent = renderer.layout_extent();
        let affected_panes =
            changed_layout_panes(&renderer.presented_layout, &composed.layout, extent);
        self.active_synchronized_resize
            .as_mut()
            .context("active resize disappeared while updating region allocations")?
            .affected_panes = affected_panes;
        Ok(self
            .renderer
            .as_mut()
            .and_then(|renderer| renderer.project_staged_layout(epoch, composed)))
    }

    fn reject_layout_region_response(
        &self,
        sender: &ActorIdentity,
        resize_epoch: brood_wasm::ResizeEpoch,
        lease: brood_wasm::LayoutLeaseToken,
        reason: brood_wasm::LayoutRegionRejectionReason,
        message: impl AsRef<str>,
    ) {
        let message = truncate_layout_region_text(message.as_ref());
        let (region_final, region_total, pane_ready, pane_total, recovered) = self
            .active_synchronized_resize
            .as_ref()
            .map_or((0, 0, 0, 0, String::new()), |active| {
                (
                    active
                        .regions
                        .values()
                        .filter(|region| region_state_is_final(&region.state))
                        .count(),
                    active.regions.len(),
                    active.ready_panes.len(),
                    active.wait_panes.len(),
                    trace_region_ids(&active.recovered_regions),
                )
            });
        eprintln!(
            "layout-region response-rejected epoch={} lease={} lease_generation={} actor={} actor_generation={} reason={reason:?} region_final={region_final}/{region_total} pane_ready={pane_ready}/{pane_total} recovered_regions=[{recovered}] message={message}",
            resize_epoch.id, lease.id, lease.generation, sender.name, sender.generation,
        );
        let Some(runtime) = self.wasm_runtime.as_ref() else {
            return;
        };
        if runtime.actor_identity(&sender.name).as_ref() != Some(sender) {
            eprintln!(
                "discarded layout-region rejection for stale actor generation actor={} actor_generation={}",
                sender.name, sender.generation
            );
            return;
        }
        let notification = brood_wasm::LayoutRegionResponseNotification::Rejected {
            resize_epoch,
            lease,
            reason,
            message,
        };
        let delivery = serde_json::to_vec(&notification)
            .context("encode layout region rejection")
            .and_then(|payload| {
                runtime.send_actor_message(&sender.name, "layout-host".to_string(), payload)
            });
        if let Err(error) = delivery {
            eprintln!(
                "could not deliver layout-region rejection actor={} actor_generation={}: {error:#}",
                sender.name, sender.generation
            );
        }
    }

    fn handle_layout_region_response(
        &mut self,
        sender: &ActorIdentity,
        resize_epoch: brood_wasm::ResizeEpoch,
        actor_lease: brood_wasm::LayoutLeaseToken,
        response: LayoutRegionActorResponse,
    ) -> Result<Option<FocusChange>> {
        let lease = convert_actor_layout_lease(actor_lease);
        let Some(active) = self.active_synchronized_resize.as_ref() else {
            self.reject_layout_region_response(
                sender,
                resize_epoch,
                actor_lease,
                brood_wasm::LayoutRegionRejectionReason::StaleEpoch,
                "the parent resize epoch is no longer active",
            );
            return Ok(None);
        };
        if active.epoch != resize_epoch {
            self.reject_layout_region_response(
                sender,
                resize_epoch,
                actor_lease,
                brood_wasm::LayoutRegionRejectionReason::StaleEpoch,
                "the region response does not match the active parent epoch",
            );
            return Ok(None);
        }
        if Instant::now() >= active.deadline {
            let retain_previous_composition = active.host_owned || active.interaction_preview;
            let recovery_extent = active.target_extent;
            self.reject_layout_region_response(
                sender,
                resize_epoch,
                actor_lease,
                brood_wasm::LayoutRegionRejectionReason::StaleEpoch,
                "the region response arrived after the synchronized resize deadline",
            );
            self.recover_pending_layout_regions_at(recovery_extent)?;
            return if retain_previous_composition {
                self.abort_synchronized_interaction_preview_timeout()
            } else if self.renderer.is_some() {
                self.finish_synchronized_resize(true)
            } else {
                Ok(None)
            };
        }
        let Some(region) = active.regions.get(&lease.id).cloned() else {
            self.reject_layout_region_response(
                sender,
                resize_epoch,
                actor_lease,
                brood_wasm::LayoutRegionRejectionReason::UnexpectedResponse,
                "the host did not issue this child region for the active epoch",
            );
            return Ok(None);
        };
        if region.lease != lease {
            self.reject_layout_region_response(
                sender,
                resize_epoch,
                actor_lease,
                brood_wasm::LayoutRegionRejectionReason::StaleLease,
                "the child lease generation is no longer current",
            );
            return Ok(None);
        }
        let durable_token_is_current = self.layout_leases.lease_tokens().contains(&lease);
        let target_token_is_current = active.target_tree.lease_tokens().contains(&lease);
        if !durable_token_is_current || !target_token_is_current {
            self.reject_layout_region_response(
                sender,
                resize_epoch,
                actor_lease,
                brood_wasm::LayoutRegionRejectionReason::StaleLease,
                "the full child lease token is no longer current",
            );
            return Ok(None);
        }
        let current_holder = self.layout_holders.get(&lease.id);
        if &region.holder != sender || current_holder != Some(sender) {
            self.reject_layout_region_response(
                sender,
                resize_epoch,
                actor_lease,
                brood_wasm::LayoutRegionRejectionReason::StaleActor,
                "the actor is not the exact child lease holder for this region",
            );
            return Ok(None);
        }
        if !matches!(region.state, LayoutRegionResolutionState::Pending) {
            self.reject_layout_region_response(
                sender,
                resize_epoch,
                actor_lease,
                brood_wasm::LayoutRegionRejectionReason::UnexpectedResponse,
                "the child region already has a final response",
            );
            return Ok(None);
        }

        let mut candidate = active.target_tree.clone();
        let wait_panes = active.wait_panes.clone();
        let inventory_revision = active.target_tree.inventory_revision();
        let next_state = match response {
            LayoutRegionActorResponse::Fragment {
                inventory_revision: response_revision,
                fragment,
                focus,
            } => {
                if response_revision != inventory_revision {
                    self.reject_layout_region_response(
                        sender,
                        resize_epoch,
                        actor_lease,
                        brood_wasm::LayoutRegionRejectionReason::StaleInventoryRevision,
                        "the child fragment inventory revision is no longer current",
                    );
                    return Ok(None);
                }
                if let Err(error) = candidate.submit(
                    lease,
                    response_revision,
                    convert_actor_layout_fragment(fragment.layout, fragment.rest),
                    focus,
                ) {
                    self.reject_layout_region_response(
                        sender,
                        resize_epoch,
                        actor_lease,
                        brood_wasm::LayoutRegionRejectionReason::InvalidFragment,
                        error.to_string(),
                    );
                    return Ok(None);
                }
                LayoutRegionResolutionState::Fragment
            }
            LayoutRegionActorResponse::Reuse => {
                if let Err(error) = candidate.reuse_accepted_fragment_from(&active.base_tree, lease)
                {
                    self.reject_layout_region_response(
                        sender,
                        resize_epoch,
                        actor_lease,
                        brood_wasm::LayoutRegionRejectionReason::InvalidFragment,
                        error.to_string(),
                    );
                    return Ok(None);
                }
                LayoutRegionResolutionState::Reuse
            }
            LayoutRegionActorResponse::Failure(message) => {
                if let Err(error) = candidate.reuse_accepted_fragment_from(&active.base_tree, lease)
                {
                    self.reject_layout_region_response(
                        sender,
                        resize_epoch,
                        actor_lease,
                        brood_wasm::LayoutRegionRejectionReason::InvalidFragment,
                        error.to_string(),
                    );
                    return Ok(None);
                }
                LayoutRegionResolutionState::RecoveredFailure {
                    reason: truncate_layout_region_text(&message),
                }
            }
        };
        let composed = match candidate.compose() {
            Ok(composed) => composed,
            Err(error) => {
                self.reject_layout_region_response(
                    sender,
                    resize_epoch,
                    actor_lease,
                    brood_wasm::LayoutRegionRejectionReason::InvalidFragment,
                    error.to_string(),
                );
                return Ok(None);
            }
        };
        if let Some(pane) = removed_fixed_wait_pane(&composed.layout, &wait_panes) {
            self.reject_layout_region_response(
                sender,
                resize_epoch,
                actor_lease,
                brood_wasm::LayoutRegionRejectionReason::InvalidFragment,
                format!("child fragment removed fixed wait pane {pane}"),
            );
            return Ok(None);
        }

        let elapsed_us = region.issued_at.elapsed().as_micros();
        let response_kind = match &next_state {
            LayoutRegionResolutionState::Fragment => "fragment",
            LayoutRegionResolutionState::Reuse => "reuse",
            LayoutRegionResolutionState::RecoveredFailure { .. } => "failure",
            LayoutRegionResolutionState::Pending => "pending",
        };
        if let Some(active) = self.active_synchronized_resize.as_mut() {
            active.target_tree = candidate;
            if let Some(current) = active.regions.get_mut(&lease.id) {
                current.state = next_state.clone();
            }
            if matches!(
                next_state,
                LayoutRegionResolutionState::RecoveredFailure { .. }
            ) {
                active.recovered_regions.insert(lease.id);
            }
        }
        let focus_change = self.reproject_active_region_target()?;
        eprintln!(
            "layout-region response-accepted epoch={} lease={} lease_generation={} actor={} actor_generation={} kind={response_kind} response_us={elapsed_us}",
            resize_epoch.id, lease.id.0, lease.generation, sender.name, sender.generation,
        );
        self.discover_changed_rest_region(lease)?;
        self.discover_and_dispatch_layout_regions()?;
        self.notify_synchronized_panes();
        let ready = self
            .active_synchronized_resize
            .as_ref()
            .is_some_and(synchronized_resize_wait_set_is_ready);
        if ready {
            return self.finish_synchronized_resize(false);
        }
        Ok(focus_change)
    }

    fn discover_and_dispatch_layout_regions(&mut self) -> Result<()> {
        loop {
            let next = self.active_synchronized_resize.as_ref().and_then(|active| {
                active
                    .regions
                    .values()
                    .find(|region| {
                        matches!(region.state, LayoutRegionResolutionState::Pending)
                            && !region.delivered
                    })
                    .cloned()
            });
            let Some(region) = next else {
                return Ok(());
            };
            let epoch = self
                .active_synchronized_resize
                .as_ref()
                .context("active resize disappeared before region delivery")?
                .epoch;
            let scale = self
                .renderer
                .as_ref()
                .map_or(1.0, |renderer| renderer.window.scale_factor())
                .max(f64::EPSILON);
            let message = layout_region_notification(epoch, &region, scale as f32);
            let payload = serde_json::to_vec(&message).context("encode layout region resize")?;
            let delivery = self
                .wasm_runtime
                .as_ref()
                .context("layout actor runtime is unavailable")
                .and_then(|runtime| {
                    anyhow::ensure!(
                        runtime.actor_identity(&region.holder.name).as_ref()
                            == Some(&region.holder),
                        "layout region holder generation is no longer current"
                    );
                    runtime.send_actor_message(
                        &region.holder.name,
                        "layout-host".to_string(),
                        payload,
                    )
                });
            if let Some(active) = self.active_synchronized_resize.as_mut()
                && let Some(current) = active.regions.get_mut(&region.lease.id)
            {
                current.delivered = true;
            }
            match delivery {
                Ok(()) => {
                    eprintln!(
                        "layout-region issued epoch={} lease={} lease_generation={} holder={} holder_generation={} source={}:{}:{}:{} target={}:{}:{}:{} accepted_us={}",
                        epoch.id,
                        region.lease.id.0,
                        region.lease.generation,
                        region.holder.name,
                        region.holder.generation,
                        region.source_viewport.x,
                        region.source_viewport.y,
                        region.source_viewport.w,
                        region.source_viewport.h,
                        region.target_viewport.x,
                        region.target_viewport.y,
                        region.target_viewport.w,
                        region.target_viewport.h,
                        self.active_synchronized_resize
                            .as_ref()
                            .map_or(0, |active| active.started.elapsed().as_micros()),
                    );
                }
                Err(error) => {
                    let reason = truncate_layout_region_text(&format!(
                        "region mailbox delivery failed: {error:#}"
                    ));
                    if let Some(active) = self.active_synchronized_resize.as_mut() {
                        active
                            .target_tree
                            .reuse_accepted_fragment_from(&active.base_tree, region.lease)?;
                        if let Some(current) = active.regions.get_mut(&region.lease.id) {
                            current.state = LayoutRegionResolutionState::RecoveredFailure {
                                reason: reason.clone(),
                            };
                        }
                        active.recovered_regions.insert(region.lease.id);
                    }
                    let _focus_change = self.reproject_active_region_target()?;
                    eprintln!(
                        "layout-region recovered epoch={} lease={} lease_generation={} reason={reason}",
                        epoch.id, region.lease.id.0, region.lease.generation,
                    );
                    self.discover_changed_rest_region(region.lease)?;
                    self.notify_synchronized_panes();
                }
            }
        }
    }

    fn notify_synchronized_panes(&mut self) {
        let Some(active) = self.active_synchronized_resize.as_ref() else {
            return;
        };
        let epoch = active.epoch.id;
        let (affected_panes, wait_panes) = pending_synchronized_notification_panes(active);
        if affected_panes.is_empty() && wait_panes.is_empty() {
            return;
        }
        let notification_panes = affected_panes
            .union(&wait_panes)
            .copied()
            .collect::<BTreeSet<_>>();
        let Some(renderer) = self.renderer.as_ref() else {
            return;
        };
        let plugin_panes = renderer
            .plugin_pane_realms
            .keys()
            .copied()
            .collect::<BTreeSet<_>>();
        let managed_panes = renderer
            .available_windows
            .iter()
            .map(|window| window.pane)
            .collect::<BTreeSet<_>>();
        let managed_routes = notification_panes
            .iter()
            .filter(|pane| managed_panes.contains(pane))
            .filter_map(|pane| {
                let qualified = self.backend_registry.routable_backend_pane(*pane)?;
                let generation = self
                    .backend_registry
                    .connection_generation(qualified.backend)?;
                Some(ManagedPaneRoute {
                    backend: qualified.backend,
                    connection_generation: generation,
                    backend_pane: qualified.pane,
                    view_pane: *pane,
                })
            })
            .collect::<Vec<_>>();
        let routed_managed = managed_routes
            .iter()
            .map(|route| route.view_pane)
            .collect::<BTreeSet<_>>();
        let unavailable_managed = notification_panes
            .iter()
            .filter(|pane| managed_panes.contains(pane) && !routed_managed.contains(pane))
            .copied()
            .collect::<Vec<_>>();
        if !unavailable_managed.is_empty() {
            let reason = format!(
                "managed pane routes disappeared after synchronized acceptance: {unavailable_managed:?}"
            );
            match self.abort_synchronized_resize_for_inventory_authority_change(
                &reason,
                &unavailable_managed,
            ) {
                Ok(Some(change)) => {
                    if let Err(error) = dispatch_focus_change(
                        self.wasm_runtime.as_ref(),
                        self.input_sender.as_mut(),
                        change,
                        self.window_focused,
                    ) {
                        eprintln!(
                            "could not dispatch focus change after synchronized route loss: {error:#}"
                        );
                    }
                }
                Ok(None) => {}
                Err(error) => {
                    eprintln!("could not abort synchronized resize after route loss: {error:#}");
                }
            }
            return;
        }
        if self.proof_managed_frame_gate_enabled
            && self.proof_managed_frame_authority.is_none()
            && self.proof_held_managed_frame.is_none()
            && self
                .active_synchronized_resize
                .as_ref()
                .is_some_and(|active| active.interaction.is_some())
            && let Some(authority) = proof_managed_frame_authority(epoch, &managed_routes)
        {
            eprintln!(
                "proof armed complete tagged managed scene backend={} connection_generation={} epoch={} backend_panes={:?}",
                authority.backend.0,
                authority.connection_generation,
                authority.epoch,
                authority.backend_panes,
            );
            self.proof_managed_frame_authority = Some(authority);
        }
        let (tagged, ordinary) =
            synchronized_plugin_notification_sets(&affected_panes, &wait_panes, &plugin_panes);
        let Some(renderer) = self.renderer.as_mut() else {
            return;
        };
        if let Some(graphics) = self.plugin_graphics.as_ref() {
            if let Err(error) = graphics.admit_resize_epoch_panes(epoch, &tagged) {
                eprintln!(
                    "could not admit synchronized graphics epoch={epoch}; waiting for degraded recovery: {error:#}"
                );
            }
        } else {
            eprintln!(
                "plugin graphics bridge disappeared for synchronized epoch={epoch}; waiting for degraded recovery"
            );
        }
        send_plugin_pane_resize_events_best_effort(
            self.wasm_runtime.as_ref(),
            renderer,
            &tagged,
            Some(epoch),
            Some(epoch),
            "synchronized barrier",
        );
        send_plugin_pane_resize_events_best_effort(
            self.wasm_runtime.as_ref(),
            renderer,
            &ordinary,
            None,
            Some(epoch),
            "synchronized non-wait pane",
        );
        let mut failed_managed = Vec::new();
        for route in managed_routes {
            let wait = wait_panes.contains(&route.view_pane);
            if let Err(error) = renderer.admit_managed_resize_expectation(route, epoch, wait) {
                release_recovery_hold(
                    &mut renderer.pending_ordinary_managed_recovery,
                    route.view_pane,
                    epoch,
                );
                failed_managed.push(route.view_pane);
                eprintln!(
                    "could not admit managed resize expectation pane={} epoch={epoch}; selected explicit recovery: {error:#}",
                    route.view_pane
                );
            }
        }
        flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
        if let Some(active) = self.active_synchronized_resize.as_mut() {
            for pane in failed_managed {
                active.recovered_managed_panes.insert(pane);
                let has_visible_resource = renderer
                    .current_windows
                    .iter()
                    .any(|window| window.window_id == pane);
                let content = managed_recovery_content(has_visible_resource);
                active.recovered_managed_content.insert(pane, content);
                if active.wait_panes.contains(&pane) {
                    active.ready_panes.insert(pane);
                }
                eprintln!(
                    "managed resize dependency recovered epoch={epoch} pane={pane} content={content} reason=expectation-admission-failed"
                );
            }
            active
                .notified_panes
                .extend(notification_panes.iter().copied());
            let accepted_us = active.started.elapsed().as_micros();
            for pane in notification_panes {
                let owner = active
                    .wait_pane_owners
                    .get(&pane)
                    .map_or(0, |lease| lease.id.0);
                eprintln!(
                    "layout-region pane-notified epoch={epoch} pane={pane} owner_lease={owner} wait={} accepted_us={accepted_us}",
                    active.wait_panes.contains(&pane),
                );
            }
        }
    }

    fn note_synchronized_pane_ready(
        &mut self,
        pane: u64,
        resize_epoch: u64,
    ) -> Result<Option<FocusChange>> {
        let Some(active) = self.active_synchronized_resize.as_mut() else {
            return Ok(None);
        };
        if active.epoch.id != resize_epoch || !active.wait_panes.contains(&pane) {
            return Ok(None);
        }
        if !active.notified_panes.contains(&pane) || !pane_branch_is_final(active, pane) {
            eprintln!(
                "ignored early synchronized pane readiness epoch={resize_epoch} pane={pane} branch_final={} admitted={}",
                pane_branch_is_final(active, pane),
                active.notified_panes.contains(&pane),
            );
            return Ok(None);
        }
        if !matches!(active.presentation, SynchronizedResizePresentation::Waiting) {
            return Ok(None);
        }
        let newly_ready = active.ready_panes.insert(pane);
        self.resize_presentation_trace.wait_ready = active.ready_panes.len();
        if newly_ready && std::env::var_os("BROOD_TRACE_RESIZE").is_some() {
            eprintln!(
                "resize-host pane-ready epoch={resize_epoch} pane={pane} ready={}/{} ready_us={}",
                active.ready_panes.len(),
                active.wait_panes.len(),
                active.started.elapsed().as_micros(),
            );
        }
        if active.native_resize_revision.is_some() {
            self.native_resize_presentation_trace.wait_ready = active.ready_panes.len();
            self.native_resize_presentation_trace.pending_emit = true;
        }
        if synchronized_resize_wait_set_is_ready(active) {
            return self.finish_synchronized_resize(false);
        }
        Ok(None)
    }

    fn note_deferred_actor_frame_tagged_ready(
        &mut self,
        tagged_ready: impl IntoIterator<Item = (u64, u64)>,
    ) -> Result<Option<FocusChange>> {
        let mut focus_change = None;
        for (pane, epoch) in tagged_ready {
            if let Some(change) = self.note_synchronized_pane_ready(pane, epoch)? {
                focus_change = Some(change);
            }
        }
        Ok(focus_change)
    }

    fn finish_synchronized_resize(&mut self, degraded: bool) -> Result<Option<FocusChange>> {
        if self.active_synchronized_resize.is_none() {
            return Ok(None);
        }
        let Some(active) = self.active_synchronized_resize.as_mut() else {
            return Ok(None);
        };
        let Some((degraded, missing)) = prepare_synchronized_resize_presentation(active, degraded)
        else {
            return Ok(None);
        };
        self.resize_presentation_trace.phase = if degraded { "degraded-ready" } else { "ready" };
        self.resize_presentation_trace.degraded = degraded;
        self.renderer
            .as_ref()
            .context("renderer disappeared while scheduling synchronized presentation")?
            .window
            .request_redraw();
        eprintln!(
            "synchronized layout ready actor={} request={} interaction={} event_sequence={} epoch={} target_revision={} region_final={}/{} pane_ready={}/{} recovered_regions=[{}] recovered_count={} recovered_managed={:?} recovered_managed_content={:?} missing={missing:?} degraded={degraded} duration_us={}",
            active.requester.name,
            active.request_id,
            active.interaction.map_or(0, |interaction| interaction.0),
            active.event_sequence,
            active.epoch.id,
            active.epoch.target_layout_revision,
            active
                .regions
                .values()
                .filter(|region| region_state_is_final(&region.state))
                .count(),
            active.regions.len(),
            active.ready_panes.len(),
            active.wait_panes.len(),
            trace_region_ids(&active.recovered_regions),
            active.recovered_regions.len(),
            active.recovered_managed_panes,
            active.recovered_managed_content,
            active.started.elapsed().as_micros(),
        );
        Ok(None)
    }

    fn complete_presented_synchronized_resize(&mut self) -> Result<Option<FocusChange>> {
        let promoted = self
            .active_synchronized_resize
            .as_ref()
            .is_some_and(|active| {
                matches!(
                    active.presentation,
                    SynchronizedResizePresentation::Promoted { .. }
                )
            });
        if !promoted {
            return Ok(None);
        }
        let active = self
            .active_synchronized_resize
            .take()
            .context("promoted synchronized resize disappeared after presentation")?;
        let (degraded, missing_panes) = match active.presentation {
            SynchronizedResizePresentation::Promoted {
                degraded,
                missing_panes,
            } => (degraded, missing_panes),
            SynchronizedResizePresentation::Waiting
            | SynchronizedResizePresentation::Ready { .. } => {
                return Err(anyhow!(
                    "synchronized resize lost its promoted state after presentation"
                ));
            }
        };
        let recovery_panes = synchronized_resize_recovery_panes(&active.wait_panes, degraded);
        let renderer = self
            .renderer
            .as_mut()
            .context("renderer disappeared after synchronized presentation")?;
        renderer.settle_promoted_layout();
        let deferred = renderer
            .plugin_graphics
            .complete_resize_epoch(active.epoch.id, !degraded)?;
        let mut focus_change = None;
        for (pane, sequence, terminal_input_sequence) in deferred {
            if let GraphicsRefresh::Applied(Some(change)) =
                renderer.refresh_plugin_graphics(pane, sequence)?
            {
                focus_change = Some(change);
            }
            let ready_at = Instant::now();
            for input in &mut self.pending_plugin_inputs {
                if input.pane == pane
                    && input.snapshot_dispatched.is_some()
                    && input.trace_sequence.is_some()
                    && input.trace_sequence <= terminal_input_sequence
                {
                    input.graphics_ready = Some(ready_at);
                    input.ready = true;
                }
            }
        }
        self.layout_leases = active.target_tree;
        self.presented_layout_revision = active.epoch.target_layout_revision;
        self.layout_publications.clear();
        if degraded {
            send_plugin_pane_resize_events_best_effort(
                self.wasm_runtime.as_ref(),
                renderer,
                &recovery_panes,
                None,
                None,
                "post-degraded recovery",
            );
        }
        flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
        self.resize_presentation_trace = ResizePresentationTrace {
            interaction: active.interaction.map_or(0, |interaction| interaction.0),
            event_sequence: active.event_sequence,
            epoch: active.epoch.id,
            phase: if degraded { "degraded" } else { "promoted" },
            wait_ready: active.ready_panes.len(),
            wait_total: active.wait_panes.len(),
            superseded_epochs: active.superseded_epochs,
            degraded,
        };
        let notification = if degraded {
            brood_wasm::SynchronizedLayoutNotification::Degraded(
                brood_wasm::SynchronizedLayoutDegraded {
                    request_id: active.request_id,
                    resize_epoch: active.epoch,
                    missing_panes: missing_panes.clone(),
                },
            )
        } else {
            brood_wasm::SynchronizedLayoutNotification::Completed(
                brood_wasm::SynchronizedLayoutCompleted {
                    request_id: active.request_id,
                    resize_epoch: active.epoch,
                },
            )
        };
        if !active.host_owned {
            self.queue_synchronized_layout_terminal_notification_for_claim(
                &active.requester,
                notification,
                active.interaction_claim,
            )?;
        }
        eprintln!(
            "{} synchronized layout actor={} request={} interaction={} event_sequence={} native_resize_revision={} epoch={} target_revision={} region_final={}/{} pane_ready={}/{} recovered_regions=[{}] recovered_count={} recovered_managed={:?} recovered_managed_content={:?} missing={missing_panes:?} duration_us={}",
            if degraded { "degraded" } else { "completed" },
            active.requester.name,
            active.request_id,
            active.interaction.map_or(0, |interaction| interaction.0),
            active.event_sequence,
            active.native_resize_revision.unwrap_or(0),
            active.epoch.id,
            active.epoch.target_layout_revision,
            active
                .regions
                .values()
                .filter(|region| region_state_is_final(&region.state))
                .count(),
            active.regions.len(),
            active.ready_panes.len(),
            active.wait_panes.len(),
            trace_region_ids(&active.recovered_regions),
            active.recovered_regions.len(),
            active.recovered_managed_panes,
            active.recovered_managed_content,
            active.started.elapsed().as_micros(),
        );
        if let Some(native_resize_revision) = active.native_resize_revision
            && let Some(change) = self.complete_native_window_resize_after_synchronized_present(
                native_resize_revision,
                active.epoch.id,
                active.ready_panes.len(),
                active.wait_panes.len(),
                degraded,
            )?
        {
            focus_change = Some(change);
        }
        self.cleanup_proof_managed_frame_for_epoch(
            active.epoch.id,
            if degraded {
                "synchronized timeout/degraded completion"
            } else {
                "synchronized completion"
            },
        )?;
        Ok(focus_change)
    }

    fn settle_synchronized_resize(&mut self) -> Result<Option<FocusChange>> {
        self.reconcile_managed_resize_recovery()?;
        let now = Instant::now();
        let timed_out_preview = self
            .active_synchronized_resize
            .as_ref()
            .is_some_and(|active| synchronized_resize_preview_timed_out(active, now));
        if timed_out_preview {
            // A degraded promotion would project the previous immutable facet
            // into the new pane bounds. Abort the preview and retain the last
            // complete composition instead.
            return self.abort_synchronized_interaction_preview_timeout();
        }
        if self
            .active_synchronized_resize
            .as_ref()
            .is_some_and(|active| {
                matches!(active.presentation, SynchronizedResizePresentation::Waiting)
                    && now >= active.deadline
            })
        {
            self.recover_pending_layout_regions_for_timeout()?;
            if let Some(epoch) = self
                .active_synchronized_resize
                .as_ref()
                .map(|active| active.epoch.id)
                && let Some(renderer) = self.renderer.as_mut()
            {
                renderer.recover_managed_resize_timeout(epoch);
            }
            self.reconcile_managed_resize_recovery()?;
            return self.finish_synchronized_resize(true);
        }
        Ok(None)
    }

    fn reconcile_managed_resize_recovery(&mut self) -> Result<()> {
        let Some(epoch) = self
            .active_synchronized_resize
            .as_ref()
            .map(|active| active.epoch.id)
        else {
            return Ok(());
        };
        let recovered = self
            .renderer
            .as_ref()
            .map_or_else(BTreeSet::new, |renderer| {
                renderer.recovered_managed_dependencies(epoch)
            });
        if recovered.is_empty() {
            return Ok(());
        }
        let recovery_content = recovered
            .iter()
            .map(|pane| {
                let has_visible_resource = self.renderer.as_ref().is_some_and(|renderer| {
                    renderer
                        .current_windows
                        .iter()
                        .any(|window| window.window_id == *pane)
                });
                let content = managed_recovery_content(has_visible_resource);
                (*pane, content)
            })
            .collect::<BTreeMap<_, _>>();
        if let Some(active) = self.active_synchronized_resize.as_mut() {
            for pane in recovered {
                if active.recovered_managed_panes.insert(pane) && active.wait_panes.contains(&pane)
                {
                    let content = recovery_content
                        .get(&pane)
                        .copied()
                        .context("managed recovery content disappeared")?;
                    active.recovered_managed_content.insert(pane, content);
                    active.ready_panes.insert(pane);
                    eprintln!(
                        "managed resize dependency recovered epoch={epoch} pane={pane} content={content} pane_ready={}/{}",
                        active.ready_panes.len(),
                        active.wait_panes.len()
                    );
                }
            }
            self.resize_presentation_trace.wait_ready = active.ready_panes.len();
        }
        let ready = self
            .active_synchronized_resize
            .as_ref()
            .is_some_and(synchronized_resize_wait_set_is_ready);
        if ready {
            let _focus_change = self.finish_synchronized_resize(false)?;
        }
        Ok(())
    }

    fn recover_pending_layout_regions_for_timeout(&mut self) -> Result<()> {
        let Some(active) = self.active_synchronized_resize.as_ref() else {
            return Ok(());
        };
        let current_extent = self.renderer.as_ref().map(Renderer::layout_extent);
        let (extent, renderer_extent_drifted) =
            synchronized_timeout_recovery_extent(active.target_extent, current_extent);
        if renderer_extent_drifted {
            eprintln!(
                "synchronized region timeout uses fixed epoch extent={}x{} current_renderer_extent={}x{}",
                extent.w,
                extent.h,
                current_extent.map_or(0, |current| current.w),
                current_extent.map_or(0, |current| current.h),
            );
        }
        self.recover_pending_layout_regions_at(extent)
    }

    fn recover_pending_layout_regions_at(&mut self, extent: LayoutSize) -> Result<()> {
        let Some(active) = self.active_synchronized_resize.as_ref() else {
            return Ok(());
        };
        let mut parent = LayoutLeaseToken {
            id: LayoutLeaseId(active.epoch.lease),
            generation: active.epoch.lease_generation,
        };
        let mut changed = Vec::new();
        let mut reached_leaf = false;
        for _ in 0..MAX_ACTIVE_RESIZE_REGIONS {
            let Some(child) = active.target_tree.rest_token(parent) else {
                reached_leaf = true;
                break;
            };
            let source = lease_viewport_rect(&active.base_tree, child, extent)
                .context("durable child viewport is unavailable during timeout recovery")?;
            let target = lease_viewport_rect(&active.target_tree, child, extent)
                .context("target child viewport is unavailable during timeout recovery")?;
            if source != target {
                changed.push((child, source, target));
            }
            parent = child;
        }
        anyhow::ensure!(
            reached_leaf || active.target_tree.rest_token(parent).is_none(),
            "resize region chain exceeds the active dependency bound"
        );
        let active = self
            .active_synchronized_resize
            .as_mut()
            .context("active resize disappeared during timeout recovery")?;
        let mut recovered = Vec::new();
        for (lease, source_viewport, target_viewport) in changed {
            let needs_recovery = active
                .regions
                .get(&lease.id)
                .is_none_or(|region| !region_state_is_final(&region.state));
            if !needs_recovery {
                continue;
            }
            active
                .target_tree
                .reuse_accepted_fragment_from(&active.base_tree, lease)?;
            let holder = self
                .layout_holders
                .get(&lease.id)
                .cloned()
                .unwrap_or_else(|| ActorIdentity {
                    name: "unavailable".to_string(),
                    generation: 0,
                });
            let reason = "global synchronized resize deadline expired".to_string();
            active
                .regions
                .entry(lease.id)
                .and_modify(|region| {
                    region.state = LayoutRegionResolutionState::RecoveredFailure {
                        reason: reason.clone(),
                    };
                })
                .or_insert_with(|| LayoutRegionDependency {
                    lease,
                    holder,
                    source_viewport,
                    target_viewport,
                    issued_at: active.started,
                    delivered: false,
                    state: LayoutRegionResolutionState::RecoveredFailure {
                        reason: reason.clone(),
                    },
                });
            active.recovered_regions.insert(lease.id);
            recovered.push(lease.id.0);
        }
        let composed = active.target_tree.compose()?;
        if let Some(renderer) = self.renderer.as_ref() {
            active.affected_panes =
                changed_layout_panes(&renderer.presented_layout, &composed.layout, extent);
        }
        if let Some(renderer) = self.renderer.as_mut() {
            renderer.project_staged_layout(active.epoch.id, composed);
        }
        eprintln!(
            "layout-region timeout-recovery epoch={} recovered_leases=[{}]",
            active.epoch.id,
            recovered
                .iter()
                .map(u64::to_string)
                .collect::<Vec<_>>()
                .join(",")
        );
        Ok(())
    }

    fn apply_actor_host_messages(&mut self) -> Result<()> {
        self.flush_synchronized_layout_terminal_notifications();
        if !self.pending_synchronized_layout_notifications.is_empty() {
            return Ok(());
        }
        let mut messages = if self.deferred_actor_host_messages.is_empty() {
            self.wasm_runtime
                .as_mut()
                .map_or(Ok(Vec::new()), PresentationWasmRuntime::drain_host_messages)?
                .into()
        } else {
            std::mem::take(&mut self.deferred_actor_host_messages)
        };
        while self.pending_synchronized_layout_notifications.is_empty() {
            let Some(actor_message) = messages.pop_front() else {
                break;
            };
            if let Some(sender) = actor_message.sender.as_ref() {
                let current = self
                    .wasm_runtime
                    .as_ref()
                    .and_then(|runtime| runtime.actor_identity(&sender.name));
                let mailbox_closed = self
                    .wasm_runtime
                    .as_ref()
                    .is_none_or(|runtime| runtime.actor_mailbox_is_closed(sender));
                if !deferred_actor_sender_is_current(Some(sender), current.as_ref(), mailbox_closed)
                {
                    eprintln!(
                        "discarded deferred host message from stale actor generation actor={} actor_generation={} current_generation={:?} mailbox_closed={mailbox_closed}",
                        sender.name,
                        sender.generation,
                        current.as_ref().map(|identity| identity.generation),
                    );
                    continue;
                }
            }
            let message: HostMessage = match serde_json::from_slice(&actor_message.payload) {
                Ok(message) => message,
                Err(error) => {
                    eprintln!("rejected malformed presentation actor host message: {error}");
                    continue;
                }
            };
            let host_owned_coalesce =
                self.active_synchronized_resize
                    .as_ref()
                    .is_some_and(|active| {
                        active.host_owned
                            && actor_message.sender.as_ref() == Some(&active.requester)
                            && matches!(
                                &message,
                                HostMessage::SetResolvedLayout { lease: Some(lease), .. }
                                    if lease.id == active.epoch.lease
                                        && lease.generation == active.epoch.lease_generation
                            )
                    });
            if ordinary_layout_message_conflicts_with_unsettled_resize(
                &message,
                self.active_synchronized_resize.is_some() && !host_owned_coalesce,
                self.window_resize.is_some(),
                self.pending_native_window_resize.is_some(),
            ) {
                eprintln!(
                    "rejected ordinary layout-tree mutation while synchronized or native resize geometry is unsettled: Busy"
                );
                continue;
            }
            let focus_change = match message {
                HostMessage::ClaimRootLayout => {
                    let Some(sender) = actor_message.sender.as_ref() else {
                        eprintln!("ignored root layout claim without authenticated actor identity");
                        continue;
                    };
                    let authorized = self
                        .wasm_runtime
                        .as_ref()
                        .is_some_and(|runtime| runtime.can_claim_root_layout(sender));
                    if !authorized {
                        eprintln!(
                            "ignored unauthorized root layout claim actor={} actor_generation={}",
                            sender.name, sender.generation
                        );
                        continue;
                    }
                    let mut authority_focus_change = None;
                    if self.root_layout_actor.as_ref() != Some(sender) {
                        authority_focus_change = self.abort_layout_authority_state(
                            "root layout holder was explicitly replaced",
                        )?;
                        self.layout_leases = LayoutLeaseTree::default();
                        self.layout_holders.clear();
                        self.layout_publications.clear();
                        self.root_layout_actor = Some(sender.clone());
                        let root = self.layout_leases.root_token();
                        self.layout_holders.insert(root.id, sender.clone());
                        if let Some(renderer) = self.renderer.as_mut() {
                            renderer.layout_state_dirty = true;
                        }
                        eprintln!(
                            "granted claimed root layout lease actor={} actor_generation={} lease_generation={}",
                            sender.name, sender.generation, root.generation
                        );
                    }
                    authority_focus_change
                }
                HostMessage::DelegateLayoutRest {
                    lease,
                    revision,
                    actor,
                    panes,
                } => {
                    let Some(sender) = actor_message.sender.as_ref() else {
                        eprintln!("ignored layout delegation without authenticated actor identity");
                        continue;
                    };
                    let lease = convert_actor_layout_lease(lease);
                    if self.layout_holders.get(&lease.id) != Some(sender) {
                        eprintln!(
                            "ignored layout delegation from non-holder actor={} lease={}",
                            sender.name, lease.id.0
                        );
                        continue;
                    }
                    if revision != self.layout_leases.inventory_revision() {
                        eprintln!(
                            "ignored stale layout delegation revision={revision}; current revision={}",
                            self.layout_leases.inventory_revision()
                        );
                        continue;
                    }
                    let Some(child_holder) = self
                        .wasm_runtime
                        .as_ref()
                        .and_then(|runtime| runtime.actor_identity(&actor))
                    else {
                        eprintln!("ignored layout delegation to unavailable actor={actor}");
                        continue;
                    };
                    match self.layout_leases.grant_rest(lease, &panes) {
                        Ok(child) => {
                            self.layout_holders.insert(child.id, child_holder.clone());
                            // Granting `rest` changes the parent's publication contract as
                            // well as creating the child. Republish the parent so it sees
                            // `rest=true`; if a native resize nonce is pending, this also
                            // gives the root holder a chance to answer it with the now-valid
                            // recursive fragment.
                            self.layout_publications.remove(&lease.id);
                            self.layout_publications.remove(&child.id);
                            eprintln!(
                                "{}",
                                trace_granted_rest_layout_lease(
                                    lease.id.0,
                                    child.id.0,
                                    &child_holder.name,
                                    &panes,
                                )
                            );
                        }
                        Err(error) => {
                            eprintln!("rejected rest layout delegation: {error}");
                        }
                    }
                    None
                }
                HostMessage::SetPointerPolicy { lease, provider } => {
                    let Some(sender) = actor_message.sender.as_ref() else {
                        eprintln!("ignored pointer-policy selection without actor identity");
                        continue;
                    };
                    let lease = convert_actor_layout_lease(lease);
                    let current_lease = self
                        .layout_leases
                        .lease_tokens()
                        .into_iter()
                        .find(|token| token.id == lease.id);
                    if current_lease != Some(lease)
                        || self.layout_holders.get(&lease.id) != Some(sender)
                    {
                        eprintln!(
                            "ignored stale or unauthorized pointer-policy selection actor={} actor_generation={} lease={} lease_generation={} provider={provider}",
                            sender.name, sender.generation, lease.id.0, lease.generation
                        );
                        continue;
                    }
                    let replaces_capture =
                        self.policy_pointer_capture.as_ref().is_some_and(|capture| {
                            capture.binding.lease == lease
                                && (capture.binding.holder_name != sender.name
                                    || capture.binding.holder_generation != sender.generation
                                    || capture.binding.provider != provider)
                        });
                    if replaces_capture {
                        self.cancel_active_layout_capture(
                            "pointer-policy selection replaced the captured provider binding",
                        );
                    }
                    let Some(policy) = self.pointer_policy.as_mut() else {
                        eprintln!(
                            "ignored pointer-policy selection because the catalogue is unavailable actor={} lease={} provider={provider}",
                            sender.name, lease.id.0
                        );
                        continue;
                    };
                    match policy.bind(lease, sender, &provider) {
                        Ok(binding) => eprintln!(
                            "bound pointer-policy provider={} lease={} lease_generation={} actor={} actor_generation={}",
                            binding.provider,
                            binding.lease.id.0,
                            binding.lease.generation,
                            binding.holder_name,
                            binding.holder_generation
                        ),
                        Err(error) => eprintln!(
                            "rejected pointer-policy selection actor={} actor_generation={} lease={} lease_generation={} provider={provider}: {error:#}",
                            sender.name, sender.generation, lease.id.0, lease.generation
                        ),
                    }
                    None
                }
                HostMessage::SetResolvedLayout {
                    lease,
                    revision,
                    layout,
                    rest,
                    focus,
                } => {
                    let Some(sender) = actor_message.sender.as_ref() else {
                        eprintln!("ignored layout result without authenticated actor identity");
                        continue;
                    };
                    let Some(lease) = lease else {
                        let Some(renderer) = self.renderer.as_mut() else {
                            continue;
                        };
                        renderer.reject_actor_layout(&"layout result is missing its lease token");
                        continue;
                    };
                    let actor_lease = lease;
                    let submitted_lease = convert_actor_layout_lease(actor_lease);
                    let Some(holder) = self.layout_holders.get(&submitted_lease.id) else {
                        eprintln!(
                            "ignored layout result because lease={} has no holder",
                            submitted_lease.id.0
                        );
                        continue;
                    };
                    if sender != holder {
                        eprintln!(
                            "ignored layout result from non-holder actor={} actor_generation={} lease={}",
                            sender.name, sender.generation, submitted_lease.id.0
                        );
                        continue;
                    }
                    let Some(revision) = revision else {
                        let Some(renderer) = self.renderer.as_mut() else {
                            continue;
                        };
                        renderer
                            .reject_actor_layout(&"layout result is missing its input revision");
                        continue;
                    };
                    let current_lease = self
                        .layout_leases
                        .lease_tokens()
                        .into_iter()
                        .find(|token| token.id == submitted_lease.id);
                    if current_lease != Some(submitted_lease) {
                        eprintln!(
                            "ignored stale layout result lease={} generation={}; current generation={}",
                            submitted_lease.id.0,
                            submitted_lease.generation,
                            current_lease.map_or(0, |lease| lease.generation)
                        );
                        continue;
                    }
                    if revision != self.layout_leases.inventory_revision() {
                        eprintln!(
                            "ignored stale layout result revision={revision}; current revision={}",
                            self.layout_leases.inventory_revision()
                        );
                        continue;
                    }
                    let actor_fragment = convert_actor_layout_fragment(layout.clone(), rest);
                    let host_cohort_required = self
                        .renderer
                        .as_ref()
                        .and_then(|renderer| {
                            let mut target = self.layout_leases.clone();
                            target
                                .submit(submitted_lease, revision, actor_fragment.clone(), focus)
                                .ok()?;
                            let composed = target.compose().ok()?;
                            let changed = changed_layout_panes(
                                &renderer.presented_layout,
                                &composed.layout,
                                renderer.layout_extent(),
                            );
                            let facet_panes = self
                                .wasm_runtime
                                .as_ref()?
                                .facet_pane_ids()
                                .collect::<BTreeSet<_>>();
                            let managed_panes = renderer
                                .available_windows
                                .iter()
                                .map(|window| window.pane)
                                .collect::<BTreeSet<_>>();
                            changed
                                .iter()
                                .any(|pane| {
                                    facet_panes.contains(pane) || managed_panes.contains(pane)
                                })
                                .then_some(())
                        })
                        .is_some();
                    if host_cohort_required {
                        let request = brood_wasm::SubmitSynchronizedLayout {
                            request_id: 0,
                            interaction: None,
                            event_sequence: None,
                            native_resize_revision: None,
                            lease: actor_lease,
                            inventory_revision: revision,
                            base_layout_revision: self.current_target_layout_revision(),
                            fragment: brood_wasm::SynchronizedLayoutFragment { layout, rest },
                            focus,
                            wait_for_panes: Vec::new(),
                            presentation: brood_wasm::PresentationMode::ScaleThenAtomic,
                        };
                        self.submit_synchronized_layout_with_ownership(sender, request, true)?
                    } else {
                        let result = (|| {
                            self.layout_leases.submit(
                                submitted_lease,
                                revision,
                                convert_actor_layout_fragment(layout, rest),
                                focus,
                            )?;
                            if self.layout_leases.is_complete() {
                                self.layout_leases
                                    .compose()
                                    .map(Some)
                                    .map_err(anyhow::Error::from)
                            } else {
                                Ok(None)
                            }
                        })();
                        let Some(renderer) = self.renderer.as_mut() else {
                            continue;
                        };
                        let (focus_change, accepted, layout_changed) = match result {
                            Ok(Some(composed)) => renderer.commit_actor_layout(composed),
                            Ok(None) => {
                                eprintln!(
                                    "accepted layout fragment lease={} revision={revision}; waiting for child",
                                    submitted_lease.id.0
                                );
                                (None, false, false)
                            }
                            Err(error) => renderer.reject_actor_layout(&error),
                        };
                        if accepted && layout_changed {
                            let accepted_items = renderer.accepted_layout.items.len();
                            let accepted_panes = renderer.accepted_layout.pane_count();
                            let accepted_pane_rects = trace_layout_pane_rects(
                                &renderer.accepted_layout,
                                renderer.layout_extent(),
                            );
                            let pending_revision = self.schedule_presented_layout_revision()?;
                            eprintln!(
                                "{}",
                                trace_accepted_leased_actor_layout(
                                    accepted_items,
                                    accepted_panes,
                                    self.layout_leases.inventory_revision(),
                                    pending_revision,
                                    &accepted_pane_rects,
                                )
                            );
                        } else if accepted {
                            self.pending_presented_layout_revision = None;
                            eprintln!(
                                "accepted unchanged leased actor layout revision={revision} presented_layout_revision={}",
                                self.presented_layout_revision,
                            );
                        }
                        focus_change
                    }
                }
                HostMessage::SubmitSynchronizedLayout(request) => {
                    let Some(sender) = actor_message.sender.as_ref() else {
                        eprintln!("ignored synchronized layout request without actor identity");
                        continue;
                    };
                    self.submit_synchronized_layout(sender, request)?
                }
                HostMessage::SubmitLayoutRegion(response) => {
                    let Some(sender) = actor_message.sender.as_ref() else {
                        eprintln!("ignored layout-region fragment without actor identity");
                        continue;
                    };
                    self.handle_layout_region_response(
                        sender,
                        response.resize_epoch,
                        response.lease,
                        LayoutRegionActorResponse::Fragment {
                            inventory_revision: response.inventory_revision,
                            fragment: response.fragment,
                            focus: response.focus,
                        },
                    )?
                }
                HostMessage::ReuseLayoutRegion(response) => {
                    let Some(sender) = actor_message.sender.as_ref() else {
                        eprintln!("ignored layout-region reuse without actor identity");
                        continue;
                    };
                    self.handle_layout_region_response(
                        sender,
                        response.resize_epoch,
                        response.lease,
                        LayoutRegionActorResponse::Reuse,
                    )?
                }
                HostMessage::FailLayoutRegion(response) => {
                    let Some(sender) = actor_message.sender.as_ref() else {
                        eprintln!("ignored layout-region failure without actor identity");
                        continue;
                    };
                    self.handle_layout_region_response(
                        sender,
                        response.resize_epoch,
                        response.lease,
                        LayoutRegionActorResponse::Failure(response.message),
                    )?
                }
                HostMessage::ReusePaneContent(reuse) => {
                    let Some(sender) = actor_message.sender.as_ref() else {
                        eprintln!("ignored pane reuse response without actor identity");
                        continue;
                    };
                    let owns_pane = self
                        .wasm_runtime
                        .as_ref()
                        .and_then(|runtime| runtime.pane_for_actor(sender))
                        == Some(reuse.pane);
                    if !owns_pane {
                        eprintln!(
                            "ignored pane reuse response actor={} pane={} because the actor does not own that pane",
                            sender.name, reuse.pane
                        );
                        continue;
                    }
                    let Some(plugin_graphics) = self.plugin_graphics.as_ref() else {
                        eprintln!(
                            "ignored pane reuse response actor={} pane={} because plugin graphics is unavailable",
                            sender.name, reuse.pane
                        );
                        continue;
                    };
                    if let Err(error) = plugin_graphics.validate_reuse_pane_content(
                        reuse.pane,
                        sender.generation,
                        reuse.resize_epoch,
                    ) {
                        eprintln!(
                            "ignored pane reuse response actor={} pane={} resize_epoch={} because it is not reusable: {error:?}",
                            sender.name, reuse.pane, reuse.resize_epoch
                        );
                        continue;
                    }
                    self.note_synchronized_pane_ready(reuse.pane, reuse.resize_epoch)?
                }
                HostMessage::BackendSession {
                    backend,
                    request,
                    operation,
                    session,
                    name,
                    directory,
                } => {
                    let operation = match operation.as_str() {
                        "refresh" => SessionOperation::Refresh,
                        "activate" => SessionOperation::Activate,
                        "create" => SessionOperation::Create,
                        "rename" => SessionOperation::Rename,
                        "close" => SessionOperation::Close,
                        other => {
                            eprintln!("rejected unknown backend session operation {other:?}");
                            continue;
                        }
                    };
                    let actor_id = actor_message.sender.as_ref().map_or_else(
                        || BACKEND_CATALOGUE_ACTOR_ID.to_string(),
                        |sender| sender.name.clone(),
                    );
                    let command = actor_runtime::SessionCommandEnvelope {
                        actor_id,
                        request: SessionCommandRequest {
                            backend_id: backend,
                            request,
                            operation,
                            session,
                            name,
                            directory,
                        },
                    };
                    self.backend_commands
                        .as_ref()
                        .context("backend session command requires a connected backend")?
                        .try_send_session_to(BackendId(backend), command)?;
                    None
                }
                HostMessage::ConnectRemoteBackend { address } => {
                    if let Err(error) = self.connect_remote_backend(address) {
                        eprintln!("could not connect dynamic remote backend: {error:#}");
                        if let Err(notify_error) =
                            self.notify_backend_connection_failed(&format!("{error:#}"))
                        {
                            eprintln!(
                                "could not notify session switcher about remote backend failure: \
                                 {notify_error:#}"
                            );
                        }
                    }
                    None
                }
                HostMessage::DeploySshBackend { target } => {
                    if let Err(error) = self.start_ssh_backend(target) {
                        eprintln!("could not start in-client SSH backend: {error:#}");
                        if let Err(notify_error) =
                            self.notify_backend_connection_failed(&format!("{error:#}"))
                        {
                            eprintln!(
                                "could not notify session switcher about SSH backend failure: \
                                 {notify_error:#}"
                            );
                        }
                    }
                    None
                }
                HostMessage::DeployContainerBackend { image, connection } => {
                    if let Err(error) = self.start_container_backend(&image, connection.as_deref())
                    {
                        eprintln!("could not start in-client container backend: {error:#}");
                        if let Err(notify_error) =
                            self.notify_backend_connection_failed(&format!("{error:#}"))
                        {
                            eprintln!(
                                "could not notify session switcher about container backend \
                                 failure: {notify_error:#}"
                            );
                        }
                    }
                    None
                }
                HostMessage::RequestBackendCatalogue => {
                    if let Err(error) = self.publish_backend_sessions() {
                        eprintln!("could not publish requested backend catalogue: {error:#}");
                    }
                    None
                }
                HostMessage::CreateLocalBackend => {
                    if let Err(error) = self.connect_local_backend() {
                        eprintln!("could not start dynamic local backend: {error:#}");
                        if let Err(notify_error) =
                            self.notify_backend_connection_failed(&format!("{error:#}"))
                        {
                            eprintln!(
                                "could not notify session switcher about local backend failure: \
                                 {notify_error:#}"
                            );
                        }
                    }
                    None
                }
                HostMessage::SetKeybinding {
                    action,
                    key_code,
                    modifiers,
                } => {
                    let Some(sender) = actor_message.sender.as_ref() else {
                        eprintln!("ignored keybinding update without authenticated actor identity");
                        continue;
                    };
                    if sender.name != "keybindings" {
                        eprintln!(
                            "ignored keybinding update from unauthorized actor={}",
                            sender.name
                        );
                        continue;
                    }
                    let result = self
                        .key_policy
                        .as_mut()
                        .context("presentation key policy is unavailable")
                        .and_then(|policy| {
                            policy.set_binding(
                                &action,
                                brood_keybindings::Binding::new(key_code, modifiers),
                            )
                        });
                    let (success, message) = match &result {
                        Ok(()) => (true, "Saved".to_string()),
                        Err(error) => (false, format!("{error:#}")),
                    };
                    if let Some(runtime) = self.wasm_runtime.as_ref() {
                        let response = serde_json::to_vec(&serde_json::json!({
                            "type": "keybinding-saved",
                            "action": action,
                            "key_code": key_code,
                            "modifiers": modifiers,
                            "success": success,
                            "message": message,
                        }))?;
                        if let Err(error) = runtime.send_key_policy_message("keybindings", response)
                        {
                            eprintln!("could not acknowledge keybinding update: {error:#}");
                        }
                    }
                    if let Err(error) = result {
                        eprintln!("could not persist keybinding update: {error:#}");
                    }
                    None
                }
                message => {
                    let Some(renderer) = self.renderer.as_mut() else {
                        continue;
                    };
                    if let Err(error) = apply_key_policy_host_message(
                        renderer,
                        &mut self.input_sender,
                        self.backend_commands.as_ref(),
                        self.wasm_runtime.as_mut(),
                        self.clipboard.as_ref(),
                        message,
                        self.window_focused,
                    ) {
                        eprintln!("rejected presentation actor host message: {error:#}");
                    }
                    None
                }
            };
            if let Some(change) = focus_change {
                dispatch_focus_change(
                    self.wasm_runtime.as_ref(),
                    self.input_sender.as_mut(),
                    change,
                    self.window_focused,
                )?;
            }
            let Some(renderer) = self.renderer.as_mut() else {
                continue;
            };
            renderer.sync_plugin_graphics_extents()?;
            flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
            flush_renderer_plugin_resize_events_best_effort(
                self.wasm_runtime.as_ref(),
                renderer,
                "actor host message",
            );
            renderer.window.request_redraw();
        }
        if !messages.is_empty() {
            self.deferred_actor_host_messages.append(&mut messages);
        }
        Ok(())
    }

    fn drain_wasm_events(&mut self, event_loop: &ActiveEventLoop) -> bool {
        // Do not admit more actor output while a synchronized terminal is
        // backpressured. In particular, draining `HostMessageRequested`
        // events here would fill the runtime's own bounded host-message queue
        // while `apply_actor_host_messages` is intentionally paused.
        self.flush_synchronized_layout_terminal_notifications();
        if !self.pending_synchronized_layout_notifications.is_empty() {
            return true;
        }
        // `Full` retains the record in the outbound lane. Pause actor output
        // admission until the consumer catches up; the actor observer remains
        // a lossless FIFO meanwhile.
        if self.actor_message_sender.as_mut().is_some_and(|lane| {
            lane.flush_deferred();
            lane.has_deferred()
        }) {
            return true;
        }
        if self.backend_commands.as_ref().is_some_and(|lane| {
            lane.flush_deferred();
            lane.has_deferred()
        }) {
            return true;
        }
        let result = (|| {
            let Some(runtime) = self.wasm_runtime.as_mut() else {
                return Ok(());
            };
            runtime.drain_events()?;
            let pane_sessions = runtime.pane_realms().collect::<Vec<_>>();
            if let Some(renderer) = self.renderer.as_mut() {
                renderer.set_plugin_pane_realms(&pane_sessions);
            }
            if let Some(renderer) = self.renderer.as_ref() {
                let (width, height, scale) = renderer.logical_extent();
                let panes = runtime.drain_pending_pane_creations().collect::<Vec<_>>();
                for pane in panes {
                    runtime.send_presentation_event(PresentationEvent::PaneCreated {
                        pane,
                        width,
                        height,
                        scale,
                    })?;
                }
            }
            let panes = runtime.drain_pending_pane_removals().collect::<Vec<_>>();
            if let Some(renderer) = self.renderer.as_mut() {
                let mut retired = Vec::with_capacity(panes.len());
                let mut hosts = Vec::new();
                for pane in panes {
                    let retired_host = runtime.take_retired_facet_host(pane);
                    let facet = retired_host.is_some();
                    if let Some(host) = retired_host {
                        hosts.push(host);
                    }
                    retired.push((pane, facet));
                }
                let mut detached = BTreeSet::new();
                for host in hosts {
                    let identity = Arc::as_ptr(&host) as usize;
                    if detached.insert(identity) {
                        host.detach_retired_state();
                    }
                }
                for (pane, facet) in retired {
                    let replay = if facet {
                        RetiredPluginReplay::Facet
                    } else {
                        RetiredPluginReplay::Legacy
                    };
                    let change = renderer.remove_plugin_pane(pane, replay)?;
                    if let Some(change) = change {
                        dispatch_focus_change(
                            Some(runtime),
                            self.input_sender.as_mut(),
                            change,
                            self.window_focused,
                        )?;
                    }
                }
                if self.pointer_grab.as_ref().is_some_and(|grab| {
                    renderer.focus_target_for_pane(grab.target.pane()).is_none()
                }) {
                    cancel_pointer_grab(
                        Some(&*runtime),
                        self.input_sender.as_mut(),
                        &mut self.pointer_routing,
                        &mut self.pointer_grab,
                        modifier_bits(self.modifiers),
                    );
                }
            }
            let messages = runtime.drain_backend_messages();
            let commands = runtime.drain_session_commands();
            if !commands.is_empty() {
                let lane = self
                    .backend_commands
                    .as_ref()
                    .context("presentation actor requested session control without a backend")?;
                for command in commands {
                    lane.try_send_session_to(BackendId(command.request.backend_id), command)?;
                }
            }
            if !messages.is_empty() {
                let actor_panes = runtime
                    .pane_actor_ids()
                    .map(|(pane, actor)| (actor.to_string(), pane))
                    .collect::<HashMap<_, _>>();
                let lane = self
                    .actor_message_sender
                    .as_mut()
                    .context("presentation actor requested a backend message without a backend")?;
                for message in &messages {
                    if let Some(trace_sequence) = terminal_input_sequence(&message.body)
                        && let Some(pane) = actor_panes.get(&message.sender).copied()
                        && let Some(input) = self.pending_plugin_inputs.iter_mut().find(|input| {
                            input.pane == pane
                                && input.backend == Some(message.backend)
                                && input.trace_sequence.is_none()
                        })
                    {
                        input.trace_sequence = Some(trace_sequence);
                    }
                    if std::env::var_os("BROOD_TRACE_PLUGIN_INPUT").is_some()
                        && !PLUGIN_SCROLL_BENCH_ACTIVE.load(Ordering::Relaxed)
                    {
                        eprintln!(
                            "presentation actor message realm={:?} sender={} recipient={} body={}",
                            message.realm,
                            message.sender,
                            message.actor,
                            String::from_utf8_lossy(&message.body)
                        );
                    }
                    lane.send(message)?;
                }
            }
            Ok(())
        })();
        if let Err(error) = result {
            self.error = Some(error);
            event_loop.exit();
            return false;
        }
        let synchronized_inventory_changed = self
            .active_synchronized_resize
            .as_ref()
            .zip(self.renderer.as_ref())
            .is_some_and(|(active, renderer)| {
                !synchronized_resize_inventory_matches(active, &renderer.pane_inventory())
            });
        if synchronized_inventory_changed {
            let focus_change = match self.abort_synchronized_resize_for_inventory_change() {
                Ok(change) => change,
                Err(error) => {
                    self.fail(event_loop, error);
                    return false;
                }
            };
            if let Some(change) = focus_change
                && let Err(error) = dispatch_focus_change(
                    self.wasm_runtime.as_ref(),
                    self.input_sender.as_mut(),
                    change,
                    self.window_focused,
                )
            {
                self.fail(event_loop, error);
                return false;
            }
        }
        true
    }

    fn fail(&mut self, event_loop: &ActiveEventLoop, error: anyhow::Error) {
        self.error = Some(error);
        event_loop.exit();
    }

    fn sync_default_backend_target(&mut self) {
        let Some(pane) = self.renderer.as_ref().and_then(Renderer::focused_pane_id) else {
            return;
        };
        let Some(qualified) = self.backend_registry.routable_backend_pane(pane) else {
            return;
        };
        if let Some(commands) = self.backend_commands.as_mut() {
            commands.set_default_backend(qualified.backend);
        }
        if let Some(input) = self.input_sender.as_mut() {
            input.set_default_backend(qualified.backend);
        }
        if let Some(messages) = self.actor_message_sender.as_mut() {
            messages.set_default_backend(qualified.backend);
        }
    }

    fn settle_window_resize(&mut self) -> Result<()> {
        let Some(transaction) = self.window_resize.as_ref() else {
            return Ok(());
        };
        if !transaction.ready(Instant::now()) {
            return Ok(());
        }
        let transaction = self
            .window_resize
            .take()
            .context("window resize transaction disappeared while settling")?;
        let Some(renderer) = self.renderer.as_mut() else {
            return Ok(());
        };
        let focus_change = renderer.settle_window_resize_projection();
        if let Some(change) = focus_change {
            dispatch_focus_change(
                self.wasm_runtime.as_ref(),
                self.input_sender.as_mut(),
                change,
                self.window_focused,
            )?;
        }
        if let Some(sender) = self.input_sender.as_mut() {
            send_presentation_configuration(sender, renderer);
        }
        if transaction.initial_size == transaction.latest_size {
            let focus_change = self.finalize_native_window_resize_renderer()?;
            if let Some(change) = focus_change {
                dispatch_focus_change(
                    self.wasm_runtime.as_ref(),
                    self.input_sender.as_mut(),
                    change,
                    self.window_focused,
                )?;
            }
            self.native_resize_presentation_trace = NativeResizePresentationTrace {
                configure_sequence: transaction.configure_sequence,
                width: transaction.latest_size.0,
                height: transaction.latest_size.1,
                phase: "settled",
                pending_emit: true,
                ..NativeResizePresentationTrace::default()
            };
        } else {
            let pending_revision = self.schedule_presented_layout_revision()?;
            self.pending_native_window_resize = Some(PendingNativeWindowResize::new(
                pending_revision,
                transaction.configure_sequence,
                transaction.latest_size,
                transaction.started,
            ));
            eprintln!(
                "scheduled settled native window base revision={pending_revision} configure_sequence={} size={}x{}",
                transaction.configure_sequence,
                transaction.latest_size.0,
                transaction.latest_size.1
            );
        }
        eprintln!(
            "settled presentation window resize events={} from={}x{} to={}x{} elapsed_ms={}",
            transaction.events,
            transaction.initial_size.0,
            transaction.initial_size.1,
            transaction.latest_size.0,
            transaction.latest_size.1,
            transaction.started.elapsed().as_millis(),
        );
        Ok(())
    }

    fn handle_window_resized(&mut self, event_loop: &ActiveEventLoop, size: PhysicalSize<u32>) {
        if size.width == 0 || size.height == 0 {
            return;
        }
        let Some(previous_size) = self
            .renderer
            .as_ref()
            .map(|renderer| (renderer.config.width, renderer.config.height))
        else {
            return;
        };
        if let Some(graphics) = self.plugin_graphics.as_ref()
            && let Some(renderer) = self.renderer.as_ref()
        {
            graphics.set_raster_scale(renderer.window.scale_factor() as f32);
        }
        if self.window_resize.is_none() && previous_size == (size.width, size.height) {
            return;
        }
        let Some(configure_sequence) = self.window_configure_sequence.checked_add(1) else {
            self.fail(
                event_loop,
                anyhow!("window configure sequence limit exceeded"),
            );
            return;
        };
        self.window_configure_sequence = configure_sequence;
        let reason = format!(
            "native window configure sequence {configure_sequence} changed the presentation extent"
        );
        let focus_change = match self.abort_synchronized_resize_for_native_window_resize(&reason) {
            Ok(change) => change,
            Err(error) => {
                self.fail(event_loop, error);
                return;
            }
        };
        if let Some(cancelled) = self.pending_native_window_resize.take() {
            eprintln!(
                "superseded native window settlement native_resize_revision={} configure_sequence={} with configure_sequence={configure_sequence}",
                cancelled.native_resize_revision.unwrap_or(0),
                cancelled.configure_sequence,
            );
        }
        let now = Instant::now();
        if let Some(transaction) = self.window_resize.as_mut() {
            transaction.observe(now, configure_sequence, (size.width, size.height));
        } else {
            self.window_resize = Some(WindowResizeTransaction::new(
                now,
                configure_sequence,
                previous_size,
                (size.width, size.height),
            ));
        }
        self.native_resize_presentation_trace = NativeResizePresentationTrace {
            configure_sequence,
            width: size.width,
            height: size.height,
            phase: "projected",
            pending_emit: true,
            ..NativeResizePresentationTrace::default()
        };
        let resize_focus_change = self
            .renderer
            .as_mut()
            .and_then(|renderer| renderer.resize_window_live(size.width, size.height));
        for change in focus_change.into_iter().chain(resize_focus_change) {
            if let Err(error) = dispatch_focus_change(
                self.wasm_runtime.as_ref(),
                self.input_sender.as_mut(),
                change,
                self.window_focused,
            ) {
                self.fail(event_loop, error);
                return;
            }
        }
    }

    fn handle_scale_factor_changed(&mut self, event_loop: &ActiveEventLoop, scale_factor: f64) {
        let result = (|| -> Result<()> {
            let renderer = self
                .renderer
                .as_mut()
                .context("renderer disappeared during output scale change")?;
            renderer
                .plugin_graphics
                .set_raster_scale(scale_factor as f32);
            renderer.sync_plugin_graphics_extents()?;
            if let Some(sender) = self.input_sender.as_mut() {
                send_presentation_configuration(sender, renderer);
            }
            flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
            flush_renderer_plugin_resize_events_best_effort(
                self.wasm_runtime.as_ref(),
                renderer,
                "output scale change",
            );
            renderer.window.request_redraw();
            Ok(())
        })();
        if let Err(error) = result {
            self.fail(event_loop, error);
        }
    }

    fn allocate_renderer_generation(&mut self) -> Result<u64> {
        self.next_renderer_generation = self
            .next_renderer_generation
            .checked_add(1)
            .context("renderer generation limit exceeded")?;
        Ok(self.next_renderer_generation)
    }

    fn recover_renderer(&mut self, failed_generation: u64, message: &str) -> Result<()> {
        let Some(current) = self.renderer.as_ref() else {
            return Ok(());
        };
        if current.generation != failed_generation {
            return Ok(());
        }
        self.renderer_recoveries = self.renderer_recoveries.saturating_add(1);
        self.renderer_recoveries_total = self.renderer_recoveries_total.saturating_add(1);
        if self.renderer_recoveries > 3 {
            return Err(anyhow!(
                "renderer recovery failed repeatedly after: {message}"
            ));
        }
        let window = Arc::clone(&current.window);
        let graphics = current.plugin_graphics.clone();
        let generation = self.allocate_renderer_generation()?;
        self.gpu_scene_completions
            .recover_renderer(failed_generation);
        let proxy = self
            .event_proxy
            .clone()
            .context("renderer recovery event proxy is unavailable")?;
        let graphics_preparation = self
            .graphics_preparation
            .clone()
            .context("graphics-preparation lane is unavailable during recovery")?;
        graphics_preparation
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .select_generation(generation);
        self.gpu_submission_completion
            .as_mut()
            .context("GPU-submission completion lane is unavailable during recovery")?
            .select_generation(generation);
        eprintln!(
            "recovering renderer generation={failed_generation} replacement={generation}: {message}"
        );
        // Wayland permits only one explicit-sync surface object for a wl_surface.
        // Extract durable CPU state and drop the old GPU/protocol resources
        // before creating the replacement surface for the same window.
        let mut recovery =
            take_for_renderer_recovery(&mut self.renderer, Renderer::into_recovery_state)?;
        let replay = recovery.visible_plugin_panes.clone();
        let mut staged_replay = recovery.staged_plugin_scenes.clone();

        // A failed present may have promoted CPU layout state without making
        // it compositor-visible. Re-arm that transaction at its last presented
        // baseline. Managed panes whose textures died are removed from the
        // ready set and their expectations have already returned to PendingSend.
        if let Some(active) = self.active_synchronized_resize.as_mut() {
            invalidate_synchronized_ready_panes(
                &mut active.ready_panes,
                &recovery.invalidated_staged_managed_panes,
            );
            if matches!(
                &active.presentation,
                SynchronizedResizePresentation::Promoted { .. }
            ) {
                recovery
                    .accepted_layout
                    .clone_from(&recovery.presented_layout);
                recovery
                    .accepted_zones
                    .clone_from(&recovery.presented_zones);
                recovery
                    .accepted_dividers
                    .clone_from(&recovery.presented_dividers);
                let composed = active
                    .target_tree
                    .compose()
                    .context("recompose synchronized layout during renderer recovery")?;
                let superseded_epochs = recovery
                    .staged_layouts
                    .keys()
                    .copied()
                    .filter(|epoch| *epoch != active.epoch.id)
                    .collect::<Vec<_>>();
                for epoch in superseded_epochs {
                    remember_retired_staged_layout_epoch(
                        &mut recovery.retired_staged_layout_epochs,
                        epoch,
                    );
                }
                recovery.staged_layouts.clear();
                recovery.staged_layouts.insert(active.epoch.id, composed);
                if let SynchronizedResizePresentation::Promoted {
                    degraded,
                    missing_panes,
                } = active.presentation.clone()
                {
                    active.presentation = if (active.host_owned || active.interaction_preview)
                        && !synchronized_resize_wait_set_is_ready(active)
                    {
                        SynchronizedResizePresentation::Waiting
                    } else {
                        SynchronizedResizePresentation::Ready {
                            degraded,
                            missing_panes,
                        }
                    };
                }
            }
            staged_replay = synchronized_plugin_replay_plan(
                staged_replay,
                active.epoch.id,
                &active.ready_panes,
                &recovery.plugin_pane_realms,
            );
            eprintln!(
                "re-armed synchronized resize request={} epoch={} ready={}/{} after renderer recovery",
                active.request_id,
                active.epoch.id,
                active.ready_panes.len(),
                active.wait_panes.len(),
            );
        }
        let mut replacement = Renderer::new(
            window,
            self.fast_path_enabled,
            graphics,
            graphics_preparation,
            generation,
            proxy,
        )?;
        let focused_pane = recovery.focused_pane.map(|focus| match focus {
            FocusedPane::Plugin(pane) | FocusedPane::Managed(pane) => pane,
        });
        replacement.restore_recovery_state(recovery);
        let _focus_change = replacement.project_accepted_layout(focused_pane);
        if let Some(capture) = self.policy_pointer_capture.as_ref() {
            let cursor = replacement
                .presented_zones
                .iter()
                .find(|zone| zone.id == capture.zone)
                .map_or(CursorRole::Default, |zone| zone.cursor);
            replacement.set_zone_pointer_state(None, Some(capture.zone), cursor);
        }
        self.renderer = Some(replacement);
        // Renderer-only recovery keeps the same Window and monitor cadence.
        // Preserve the trained predictor unless the monitor refresh changed;
        // the first recovery gap only re-anchors its presentation timeline.
        // A refresh change observed by sync resets the predictor and cancels
        // this one-shot re-anchor.
        self.render_predictor.reanchor_next_presentation();
        self.sync_render_predictor_refresh();
        if let Some(graphics) = self.plugin_graphics.as_ref() {
            graphics.renderer_recreated()?;
        }
        if let Some(runtime) = self.wasm_runtime.as_ref() {
            runtime.facet_renderer_recreated()?;
        }
        self.pending_composition_redraw_request = None;
        if let Some(renderer) = self.renderer.as_ref() {
            renderer.window.request_redraw();
        }
        // Publish the recovered ownership state before any replay operation
        // which can fail. This guarantees queued releases remain reachable.
        self.flush_managed_resource_releases();
        if let Some(renderer) = self.renderer.as_mut() {
            let replay_count = replay.len().saturating_add(staged_replay.len());
            renderer.refresh_recovered_plugin_graphics(&replay)?;
            for (pane, epoch) in staged_replay {
                renderer.refresh_staged_plugin_graphics(pane, epoch, 0)?;
            }
            flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
            flush_renderer_plugin_resize_events_best_effort(
                self.wasm_runtime.as_ref(),
                renderer,
                "renderer recovery",
            );
            self.renderer_plugin_panes_replayed = self
                .renderer_plugin_panes_replayed
                .saturating_add(u64::try_from(replay_count).unwrap_or(u64::MAX));
        }
        Ok(())
    }
}

impl ApplicationHandler<ClientEvent> for Application {
    fn resumed(&mut self, event_loop: &ActiveEventLoop) {
        if self.renderer.is_some() {
            return;
        }

        let title = if self.backend_connected {
            "Brood"
        } else {
            "Brood - No backend"
        };
        let generation = match self.allocate_renderer_generation() {
            Ok(generation) => generation,
            Err(error) => {
                self.fail(event_loop, error);
                return;
            }
        };
        let Some(proxy) = self.event_proxy.clone() else {
            self.fail(event_loop, anyhow!("renderer event proxy is unavailable"));
            return;
        };
        let graphics_preparation = match self.graphics_preparation.clone() {
            Some(lane) => lane,
            None => match GraphicsPreparationLane::start(proxy.clone()) {
                Ok(lane) => {
                    let lane = Arc::new(Mutex::new(lane));
                    self.graphics_preparation = Some(Arc::clone(&lane));
                    lane
                }
                Err(error) => {
                    self.fail(event_loop, error);
                    return;
                }
            },
        };
        graphics_preparation
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .select_generation(generation);
        let Some(gpu_submission_completion) = self.gpu_submission_completion.as_mut() else {
            self.fail(
                event_loop,
                anyhow!("GPU-submission completion lane is unavailable"),
            );
            return;
        };
        gpu_submission_completion.select_generation(generation);
        let result = event_loop
            .create_window(
                Window::default_attributes()
                    .with_title(title)
                    .with_resizable(true)
                    .with_inner_size(LogicalSize::new(
                        DEFAULT_WINDOW_WIDTH,
                        DEFAULT_WINDOW_HEIGHT,
                    ))
                    .with_min_inner_size(LogicalSize::new(480.0, 320.0)),
            )
            .context("create presentation window")
            .and_then(|window| {
                let graphics = self
                    .plugin_graphics
                    .clone()
                    .context("plugin graphics bridge is unavailable")?;
                Renderer::new(
                    Arc::new(window),
                    self.fast_path_enabled,
                    graphics,
                    Arc::clone(&graphics_preparation),
                    generation,
                    proxy.clone(),
                )
            });

        match result {
            Ok(renderer) => {
                match WaylandDropBridge::new(renderer.window.as_ref(), move |drop_event| {
                    drop(proxy.send_event(ClientEvent::WaylandDroppedFile(drop_event)));
                }) {
                    Ok(bridge) => self.wayland_drop = bridge,
                    Err(error) => {
                        self.fail(
                            event_loop,
                            error.context("initialize presentation file drop"),
                        );
                        return;
                    }
                }
                renderer.window.request_redraw();
                self.renderer = Some(renderer);
                self.reset_render_predictor_for_surface();
                if let Err(error) = self.subscribe_computer_use_observer() {
                    self.fail(
                        event_loop,
                        error.context("subscribe computer-use spectator after renderer startup"),
                    );
                    return;
                }
                if let (Some(runtime), Some(renderer)) =
                    (self.wasm_runtime.as_ref(), self.renderer.as_mut())
                {
                    let sessions = runtime.pane_realms().collect::<Vec<_>>();
                    renderer.set_plugin_pane_realms(&sessions);
                }
                if let Some(renderer) = self.renderer.as_mut() {
                    for (backend, (active_session, windows)) in
                        std::mem::take(&mut self.pending_backend_snapshots)
                    {
                        let _focus_change =
                            renderer.select_backend_snapshot(backend, active_session, windows);
                    }
                }
                if let Err(error) = self.sync_computer_use_presentation() {
                    self.fail(
                        event_loop,
                        error.context("restore computer-use presentation authority"),
                    );
                    return;
                }
                if let (Some(sender), Some(renderer)) =
                    (self.input_sender.as_mut(), self.renderer.as_ref())
                {
                    send_presentation_configuration(sender, renderer);
                }
                for frame in std::mem::take(&mut self.pending_frames).into_values() {
                    if let Err(error) = self.accept_frame(frame) {
                        self.error = Some(error);
                        event_loop.exit();
                        return;
                    }
                }
                if let Some(renderer) = self.renderer.as_ref() {
                    let (width, height, scale) = renderer.logical_extent();
                    if let Err(error) =
                        send_presentation_events(self.wasm_runtime.as_ref(), |pane| {
                            PresentationEvent::PaneCreated {
                                pane,
                                width,
                                height,
                                scale,
                            }
                        })
                    {
                        self.fail(event_loop, error);
                        return;
                    }
                    if let Err(error) =
                        send_presentation_events(self.wasm_runtime.as_ref(), |pane| {
                            PresentationEvent::PaneFocused {
                                pane,
                                focused: true,
                            }
                        })
                    {
                        self.fail(event_loop, error);
                        return;
                    }
                    if let Some(runtime) = self.wasm_runtime.as_mut() {
                        drop(runtime.drain_pending_pane_creations());
                    }
                }
            }
            Err(error) => {
                self.error = Some(error);
                event_loop.exit();
            }
        }
    }

    #[allow(
        clippy::match_same_arms,
        reason = "distinct wakeup events intentionally require no immediate action and are serviced in about_to_wait"
    )]
    fn user_event(&mut self, event_loop: &ActiveEventLoop, event: ClientEvent) {
        let mut callback_guard = WinitCallbackGuard::new(
            Arc::clone(&self.winit_hot_path_metrics),
            self.render_scheduling_warmup_complete,
            "user_event",
            None,
        );
        callback_guard.detail = client_event_callback_kind(&event);
        if !self.drain_wasm_events(event_loop) {
            return;
        }
        match event {
            ClientEvent::WaylandDroppedFile(drop) => {
                if let Some(renderer) = self.renderer.as_ref() {
                    deliver_dropped_image(
                        renderer,
                        self.wasm_runtime.as_ref(),
                        Some((f64::from(drop.position.0), f64::from(drop.position.1))),
                        &drop.path,
                    );
                }
            }
            ClientEvent::RemoteArtifactInstalled {
                manifest,
                path,
                completion,
            } => {
                let result = (|| {
                    anyhow::ensure!(
                        manifest.realm == ArtifactRealm::Client,
                        "remote artifact {:?} targets the wrong realm",
                        manifest.id
                    );
                    let pane = self
                        .wasm_runtime
                        .as_mut()
                        .context("client WASM runtime is unavailable")?
                        .install_artifact_actor(&manifest.id, &path)?;
                    eprintln!(
                        "installed remote client artifact id={} pane={} digest={}",
                        manifest.id,
                        pane,
                        brood_transport::digest_hex(manifest.digest)
                    );
                    Ok::<(), anyhow::Error>(())
                })();
                let completion_result = match &result {
                    Ok(()) => Ok(()),
                    Err(error) => Err(format!("{error:#}")),
                };
                drop(completion.send(completion_result));
                if let Err(error) = result {
                    eprintln!("rejected remote client artifact: {error:#}");
                }
            }
            ClientEvent::FocusPresentation => {
                if let Some(renderer) = self.renderer.as_ref() {
                    renderer
                        .window
                        .request_user_attention(Some(UserAttentionType::Critical));
                    renderer.window.focus_window();
                }
            }
            ClientEvent::ClosePresentation => event_loop.exit(),
            ClientEvent::BackendDisconnected { backend, message } => {
                match self.disconnect_remote_backend(backend, &message) {
                    Ok(focus_change) => {
                        if let Some(change) = focus_change
                            && let Err(error) = dispatch_focus_change(
                                self.wasm_runtime.as_ref(),
                                self.input_sender.as_mut(),
                                change,
                                self.window_focused,
                            )
                        {
                            self.fail(event_loop, error);
                            return;
                        }
                        if let Err(error) = self.publish_layout_state() {
                            self.fail(event_loop, error);
                        }
                    }
                    Err(error) => self.fail(event_loop, error),
                }
            }
            ClientEvent::RemoteBackendReady(ready) => {
                let RemoteBackendReady { connection, origin } = *ready;
                if let Err(error) = self.accept_remote_backend(connection, origin) {
                    eprintln!("could not attach remote backend: {error:#}");
                    if let Err(notify_error) =
                        self.notify_backend_connection_failed(&format!("{error:#}"))
                    {
                        eprintln!(
                            "could not notify session switcher about remote backend failure: \
                             {notify_error:#}"
                        );
                    }
                }
            }
            ClientEvent::RemoteBackendFailed {
                backend,
                description,
                message,
            } => {
                let _retired = self.backend_registry.retire(backend);
                eprintln!("{description} attachment failed: {message}");
                if let Err(error) = self.notify_backend_connection_failed(&message) {
                    eprintln!(
                        "could not notify session switcher about remote backend failure: {error:#}"
                    );
                }
            }
            ClientEvent::SshBackendReady(deployment) => {
                if let Err(error) = self.connect_ssh_backend(deployment) {
                    eprintln!("could not attach deployed SSH backend: {error:#}");
                    if let Err(notify_error) =
                        self.notify_backend_connection_failed(&format!("{error:#}"))
                    {
                        eprintln!(
                            "could not notify session switcher about SSH backend failure: \
                             {notify_error:#}"
                        );
                    }
                }
            }
            ClientEvent::SshBackendFailed(message) => {
                eprintln!("in-client SSH backend deployment failed: {message}");
                if let Err(error) = self.notify_backend_connection_failed(&message) {
                    eprintln!(
                        "could not notify session switcher about SSH backend failure: {error:#}"
                    );
                }
            }
            ClientEvent::ContainerBackendReady(deployment) => {
                if let Err(error) = self.connect_container_backend(deployment) {
                    eprintln!("could not attach deployed container backend: {error:#}");
                    if let Err(notify_error) =
                        self.notify_backend_connection_failed(&format!("{error:#}"))
                    {
                        eprintln!(
                            "could not notify session switcher about container backend failure: \
                             {notify_error:#}"
                        );
                    }
                }
            }
            ClientEvent::ContainerBackendFailed(message) => {
                eprintln!("in-client container backend deployment failed: {message}");
                if let Err(error) = self.notify_backend_connection_failed(&message) {
                    eprintln!(
                        "could not notify session switcher about container backend failure: \
                         {error:#}"
                    );
                }
            }
            ClientEvent::RemoteTerminalInputSent {
                backend,
                trace_sequence,
                queued_at,
                sent_at,
            } => {
                for input in &mut self.pending_plugin_inputs {
                    if input.backend == Some(backend)
                        && input.trace_sequence == Some(trace_sequence)
                        && input.transport_sent.is_none()
                    {
                        input.transport_queued = Some(queued_at);
                        input.transport_sent = Some(sent_at);
                    }
                }
            }
            ClientEvent::PluginGraphicsChanged {
                pane,
                sequence,
                resize_epoch,
                terminal_input_sequence,
                ready_at,
            } => {
                let mut failure = None;
                let mut applied = false;
                let defer_ordinary_refresh = should_defer_ordinary_plugin_refresh(
                    resize_epoch,
                    pane,
                    self.active_synchronized_resize
                        .as_ref()
                        .map(|active| &active.wait_panes),
                );
                if let Some(renderer) = self.renderer.as_mut() {
                    let refresh = if defer_ordinary_refresh {
                        Ok(GraphicsRefresh::Applied(None))
                    } else if let Some(epoch) = resize_epoch {
                        renderer.refresh_staged_plugin_graphics(pane, epoch, sequence)
                    } else {
                        renderer.refresh_plugin_graphics_event(
                            pane,
                            sequence,
                            terminal_input_sequence,
                            ready_at,
                        )
                    };
                    match refresh {
                        Ok(GraphicsRefresh::Stale) => {}
                        Ok(GraphicsRefresh::Deferred | GraphicsRefresh::StagedDeferred(_)) => {}
                        Ok(GraphicsRefresh::Applied(change)) => {
                            applied = true;
                            if !defer_ordinary_refresh {
                                for input in &mut self.pending_plugin_inputs {
                                    if input.pane == pane
                                        && input.snapshot_dispatched.is_some()
                                        && input.trace_sequence.is_some()
                                        && input.trace_sequence <= terminal_input_sequence
                                    {
                                        input.graphics_ready = Some(ready_at);
                                        input.ready = true;
                                    }
                                }
                                if let Some(benchmark) = self.plugin_scroll_benchmark.as_mut()
                                    && benchmark.pane == pane
                                {
                                    benchmark.record_scene(Instant::now());
                                } else if std::env::var("BROOD_TERMINAL_SCROLL_BENCH_AUTO")
                                    .as_deref()
                                    == Ok("1")
                                {
                                    let now = Instant::now();
                                    if let Some((previous_pane, previous)) =
                                        self.plugin_scroll_auto_last_scene
                                        && previous_pane == pane
                                        && now.duration_since(previous) <= Duration::from_millis(10)
                                    {
                                        let mut benchmark = PluginScrollBenchmark::new(pane);
                                        benchmark.record_scene(previous);
                                        benchmark.record_scene(now);
                                        self.plugin_scroll_benchmark = Some(benchmark);
                                        PLUGIN_SCROLL_BENCH_ACTIVE.store(true, Ordering::Relaxed);
                                    }
                                    self.plugin_scroll_auto_last_scene = Some((pane, now));
                                }
                            }
                            if let Some(change) = change
                                && let Err(error) = dispatch_focus_change(
                                    self.wasm_runtime.as_ref(),
                                    self.input_sender.as_mut(),
                                    change,
                                    self.window_focused,
                                )
                            {
                                failure = Some(error);
                            }
                        }
                        Err(error) => failure = Some(error),
                    }
                    flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
                    flush_renderer_plugin_resize_events_best_effort(
                        self.wasm_runtime.as_ref(),
                        renderer,
                        "plugin frame acceptance",
                    );
                }
                if failure.is_none()
                    && applied
                    && let Some(epoch) = resize_epoch
                {
                    match self.note_synchronized_pane_ready(pane, epoch) {
                        Ok(Some(change)) => {
                            if let Err(error) = dispatch_focus_change(
                                self.wasm_runtime.as_ref(),
                                self.input_sender.as_mut(),
                                change,
                                self.window_focused,
                            ) {
                                failure = Some(error);
                            }
                        }
                        Ok(None) => {}
                        Err(error) => failure = Some(error),
                    }
                }
                if let Some(error) = failure {
                    self.fail(event_loop, error);
                }
            }
            ClientEvent::PluginRendererReplayRequested { panes } => {
                let result = self
                    .renderer
                    .as_mut()
                    .context("renderer is unavailable for plugin replay")
                    .and_then(|renderer| renderer.refresh_recovered_plugin_graphics(&panes));
                match result {
                    Ok(
                        GraphicsRefresh::Stale
                        | GraphicsRefresh::Deferred
                        | GraphicsRefresh::StagedDeferred(_),
                    ) => {}
                    Ok(GraphicsRefresh::Applied(change)) => {
                        if let Some(change) = change
                            && let Err(error) = dispatch_focus_change(
                                self.wasm_runtime.as_ref(),
                                self.input_sender.as_mut(),
                                change,
                                self.window_focused,
                            )
                        {
                            self.fail(event_loop, error);
                            return;
                        }
                        if let Some(renderer) = self.renderer.as_mut() {
                            flush_renderer_plugin_resize_events_best_effort(
                                self.wasm_runtime.as_ref(),
                                renderer,
                                "renderer replay",
                            );
                        }
                    }
                    Err(error) => self.fail(event_loop, error),
                }
            }
            ClientEvent::PluginActorFrameChanged {
                token,
                actor_frame_revision,
                changes,
                ready_at,
            } => {
                let result = self
                    .renderer
                    .as_mut()
                    .context("renderer is unavailable for actor frame")
                    .and_then(|renderer| {
                        renderer.refresh_plugin_actor_frame(
                            token,
                            actor_frame_revision,
                            &changes,
                            ready_at,
                        )
                    });
                match result {
                    Ok(GraphicsRefresh::Stale) => {}
                    Ok(GraphicsRefresh::Deferred) => {}
                    Ok(GraphicsRefresh::StagedDeferred(tagged_ready)) => {
                        match self.note_deferred_actor_frame_tagged_ready(tagged_ready) {
                            Ok(Some(change)) => {
                                if let Err(error) = dispatch_focus_change(
                                    self.wasm_runtime.as_ref(),
                                    self.input_sender.as_mut(),
                                    change,
                                    self.window_focused,
                                ) {
                                    self.fail(event_loop, error);
                                }
                            }
                            Ok(None) => {}
                            Err(error) => {
                                self.fail(event_loop, error);
                            }
                        }
                    }
                    Ok(GraphicsRefresh::Applied(change)) => {
                        if std::env::var_os("BROOD_TRACE_PLUGIN_INPUT").is_some()
                            && !PLUGIN_SCROLL_BENCH_ACTIVE.load(Ordering::Relaxed)
                        {
                            eprintln!(
                                "terminal actor frame correlation token={token} revision={actor_frame_revision} terminal_input_sequence={}",
                                changes
                                    .iter()
                                    .filter_map(|change| change.terminal_input_sequence)
                                    .max()
                                    .unwrap_or(0)
                            );
                        }
                        let composition_release = self
                            .plugin_graphics
                            .as_ref()
                            .map(|graphics| {
                                graphics.mark_graphics_ready(
                                    token,
                                    changes.iter().map(|change| change.pane),
                                )
                            })
                            .unwrap_or_default();
                        let resize_epochs = changes
                            .iter()
                            .filter_map(|change| change.resize_epoch)
                            .collect::<BTreeSet<_>>();
                        if !resize_epochs.is_empty() {
                            self.pending_render_token_resize_epochs
                                .insert(token, resize_epochs);
                        }
                        for change in &changes {
                            for input in &mut self.pending_plugin_inputs {
                                if input.pane == change.pane
                                    && input.snapshot_dispatched.is_some()
                                    && input.trace_sequence.is_some()
                                    && input.trace_sequence <= change.terminal_input_sequence
                                {
                                    input.graphics_ready = Some(ready_at);
                                    input.ready = true;
                                }
                            }
                            if change.resize_epoch.is_none() {
                                if let Some(benchmark) = self.plugin_scroll_benchmark.as_mut()
                                    && benchmark.pane == change.pane
                                {
                                    benchmark.record_scene(Instant::now());
                                } else if std::env::var("BROOD_TERMINAL_SCROLL_BENCH_AUTO")
                                    .as_deref()
                                    == Ok("1")
                                {
                                    let now = Instant::now();
                                    if let Some((previous_pane, previous)) =
                                        self.plugin_scroll_auto_last_scene
                                        && previous_pane == change.pane
                                        && now.duration_since(previous) <= Duration::from_millis(10)
                                    {
                                        let mut benchmark = PluginScrollBenchmark::new(change.pane);
                                        benchmark.record_scene(previous);
                                        benchmark.record_scene(now);
                                        self.plugin_scroll_benchmark = Some(benchmark);
                                        PLUGIN_SCROLL_BENCH_ACTIVE.store(true, Ordering::Relaxed);
                                    }
                                    self.plugin_scroll_auto_last_scene = Some((change.pane, now));
                                }
                            }
                            if let Some(epoch) = change.resize_epoch
                                && let Err(error) =
                                    self.note_synchronized_pane_ready(change.pane, epoch)
                            {
                                self.fail(event_loop, error);
                                return;
                            }
                        }
                        if let Some(change) = change
                            && let Err(error) = dispatch_focus_change(
                                self.wasm_runtime.as_ref(),
                                self.input_sender.as_mut(),
                                change,
                                self.window_focused,
                            )
                        {
                            self.fail(event_loop, error);
                        }
                        for token in composition_release.tokens {
                            if !self.pending_render_token_resize_epochs.contains_key(&token) {
                                self.pending_render_tokens.insert(token);
                            }
                        }
                        if let Some(target_ns) = composition_release.request_redraw_target_ns
                            && let Some(renderer) = self.renderer.as_ref()
                        {
                            if let Some((pending_target_ns, _requested_at)) =
                                self.pending_composition_redraw_request.as_mut()
                            {
                                *pending_target_ns = (*pending_target_ns).max(target_ns);
                            } else {
                                self.pending_composition_redraw_request =
                                    Some((target_ns, Instant::now()));
                            }
                            renderer.window.request_redraw();
                        }
                    }
                    Err(error) => self.fail(event_loop, error),
                }
            }
            ClientEvent::GraphicsPreparationCompleted(completion) => {
                let GraphicsPreparationCompletion {
                    renderer_generation,
                    keys,
                    prepared,
                    resume,
                    queued_at,
                    started_at,
                    finished_at,
                } = completion;
                if std::env::var_os("BROOD_TRACE_RESIZE_PIPELINE").is_some() {
                    let handled_at = Instant::now();
                    for key in &keys {
                        eprintln!(
                            "resize-pipeline-prepare pane={} sequence={} width={} height={} queue_us={} run_us={} completion_hop_us={}",
                            key.pane,
                            key.sequence,
                            key.width,
                            key.height,
                            started_at.saturating_duration_since(queued_at).as_micros(),
                            finished_at
                                .saturating_duration_since(started_at)
                                .as_micros(),
                            handled_at
                                .saturating_duration_since(finished_at)
                                .as_micros(),
                        );
                    }
                }
                let Some(renderer) = self.renderer.as_mut() else {
                    return;
                };
                if renderer.generation != renderer_generation {
                    eprintln!(
                        "discarded stale graphics-preparation completion renderer_generation={renderer_generation} current_generation={}",
                        renderer.generation
                    );
                    return;
                }
                let result = prepared
                    .map_err(anyhow::Error::msg)
                    .and_then(|prepared| renderer.accept_prepared_scenes(keys, prepared));
                let accepted = match result {
                    Ok(accepted) => accepted,
                    Err(error) => {
                        self.fail(event_loop, error.context("accept prepared plugin scenes"));
                        return;
                    }
                };
                let resume_stale =
                    !accepted && stale_graphics_preparation_resume_is_causal(&resume);
                let graphics_preparation = Arc::clone(&renderer.graphics_preparation);
                let flush_result = graphics_preparation
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .flush_deferred();
                if let Err(error) = flush_result {
                    self.fail(event_loop, error);
                    return;
                }
                if (accepted || resume_stale)
                    && let Some(proxy) = self.event_proxy.as_ref()
                    && proxy.send_event(*resume).is_err()
                {
                    self.fail(
                        event_loop,
                        anyhow!("resume prepared plugin scene after event-loop close"),
                    );
                }
            }
            ClientEvent::RenderSchedulingChanged => {
                // Finishing one hint can arm the next opportunity while
                // window input is still continuously readable. Service that
                // causal completion immediately so its new deadline reaches
                // the deadline waker without waiting for input quiescence.
                if let Err(error) = self.service_plugin_render_scheduler() {
                    self.fail(event_loop, error);
                }
            }
            ClientEvent::EventLoopDeadlineReached { generation } => {
                let wake_was_current = self
                    .event_loop_deadline_waker
                    .as_ref()
                    .is_some_and(|waker| waker.accept_wake(generation));
                // The deadline callback itself is the scheduler's causal
                // cutoff. Service it before Winit can deliver later queued
                // input; waiting for `about_to_wait` lets a continuous input
                // stream postpone this opportunity indefinitely. A replaced
                // generation remains inert.
                if wake_was_current && let Err(error) = self.service_plugin_render_scheduler() {
                    self.fail(event_loop, error);
                }
            }
            ClientEvent::GraphicsPreparationCapacityAvailable => {
                // `about_to_wait` now has a causal turn in which to move
                // deferred preparation into the worker's newly freed slot.
            }
            ClientEvent::GpuSubmissionCapacityAvailable { completed_wait_ns } => {
                record_completed_gpu_submission_capacity(
                    &mut self.gpu_submission_wait_samples_ns,
                    &mut self.gpu_submission_wait_calls_lifetime,
                    completed_wait_ns,
                );
                let flush_result = self
                    .gpu_submission_completion
                    .as_mut()
                    .context("GPU-submission completion lane is unavailable")
                    .and_then(GpuSubmissionCompletionLane::flush_deferred);
                if let Err(error) = flush_result {
                    self.fail(event_loop, error);
                    return;
                }
                if self.gpu_submission_redraw_deferred
                    && self
                        .gpu_submission_completion
                        .as_ref()
                        .is_some_and(GpuSubmissionCompletionLane::can_accept_submission)
                {
                    self.gpu_submission_redraw_deferred = false;
                    if let Some(renderer) = self.renderer.as_ref() {
                        renderer.window.request_redraw();
                    }
                }
            }
            ClientEvent::GpuSubmissionCompleted(completion) => {
                let GpuSubmissionCompletion {
                    renderer_generation,
                    frame_sequences,
                    wait_ns,
                    result,
                } = completion;
                record_gpu_submission_wait(
                    &mut self.gpu_submission_wait_samples_ns,
                    &mut self.gpu_submission_wait_calls_lifetime,
                    wait_ns,
                );
                let current_generation = self.renderer.as_ref().map(|renderer| renderer.generation);
                if current_generation != Some(renderer_generation) {
                    return;
                }
                if let Err(message) = result {
                    if let Err(error) = self.recover_renderer(renderer_generation, &message) {
                        self.renderer_failures = self.renderer_failures.saturating_add(1);
                        self.fail(event_loop, error);
                    }
                    return;
                }
                let completed = self.gpu_scene_completions.complete_submission(
                    renderer_generation,
                    frame_sequences,
                    |completed| {
                        self.backend_registry
                            .connection_generation(completed.backend)
                            == Some(completed.connection_generation)
                    },
                );
                if !completed.is_empty() {
                    let Some(sender) = self.input_sender.as_mut() else {
                        self.fail(
                            event_loop,
                            anyhow!("presentation input lane is unavailable for frame completion"),
                        );
                        return;
                    };
                    for completed in completed {
                        if !sender.send_to(
                            completed.backend,
                            ClientMessage::Lifecycle(ClientLifecycle::FramePresented {
                                sequence: completed.sequence,
                            }),
                        ) {
                            self.fail(
                                event_loop,
                                anyhow!(
                                    "could not enqueue frame completion backend={} sequence={}",
                                    completed.backend.0,
                                    completed.sequence,
                                ),
                            );
                            return;
                        }
                        self.gpu_scene_completions.acknowledged(completed);
                    }
                }
                let flush_result = self
                    .gpu_submission_completion
                    .as_mut()
                    .context("GPU-submission completion lane is unavailable")
                    .and_then(GpuSubmissionCompletionLane::flush_deferred);
                if let Err(error) = flush_result {
                    self.fail(event_loop, error);
                    return;
                }
                if self.gpu_submission_redraw_deferred
                    && self
                        .gpu_submission_completion
                        .as_ref()
                        .is_some_and(GpuSubmissionCompletionLane::can_accept_submission)
                {
                    self.gpu_submission_redraw_deferred = false;
                    if let Some(renderer) = self.renderer.as_ref() {
                        renderer.window.request_redraw();
                    }
                }
            }
            ClientEvent::PluginContentReused {
                pane,
                resize_epoch,
                ready_at,
            } => {
                eprintln!(
                    "accepted plugin content reuse pane={pane} resize_epoch={resize_epoch} ready_us={}",
                    ready_at.elapsed().as_micros()
                );
                if let Err(error) = self
                    .note_synchronized_pane_ready(pane, resize_epoch)
                    .and_then(|change| {
                        if let Some(change) = change {
                            dispatch_focus_change(
                                self.wasm_runtime.as_ref(),
                                self.input_sender.as_mut(),
                                change,
                                self.window_focused,
                            )?;
                        }
                        Ok(())
                    })
                {
                    self.fail(event_loop, error);
                    return;
                }
                if let Some(renderer) = self.renderer.as_ref() {
                    renderer.window.request_redraw();
                }
            }
            ClientEvent::RendererFailed {
                generation,
                message,
            } => {
                if let Err(error) = self.recover_renderer(generation, &message) {
                    self.renderer_failures = self.renderer_failures.saturating_add(1);
                    self.fail(event_loop, error);
                }
            }
            ClientEvent::BackendCommandCompleted {
                description,
                result,
            } => match result {
                Ok(_response) if description.starts_with("render-scheduling-proof-status-") => {}
                Ok(response) => eprintln!(
                    "presentation backend command completed command={description} response={}",
                    response.trim()
                ),
                Err(error) => {
                    eprintln!("presentation backend command failed command={description}: {error}");
                }
            },
            ClientEvent::BackendSnapshot {
                backend,
                session,
                active_session,
                windows,
            } => {
                let local_panes = windows.iter().map(|window| window.pane).collect::<Vec<_>>();
                let first_local_pane = local_panes.first().copied();
                if !self
                    .backend_registry
                    .replace_panes(backend, None, local_panes)
                {
                    return;
                }
                let windows = windows
                    .into_iter()
                    .map(|mut window| {
                        window.pane = self.backend_registry.view_pane(QualifiedPane {
                            backend,
                            pane: window.pane,
                        });
                        window
                    })
                    .collect::<Vec<_>>();
                if let Some(sender) = self.input_sender.as_mut() {
                    sender.set_pane_routes(self.backend_registry.all_view_routes());
                }
                if let (Some(window), Some(first_local_pane)) = (windows.first(), first_local_pane)
                {
                    debug_assert_eq!(
                        self.backend_registry.backend_pane(window.pane),
                        Some(QualifiedPane {
                            backend,
                            pane: first_local_pane,
                        })
                    );
                }
                let _backend_count = self.backend_registry.backend_count();
                let mut focus_change = if let Some(renderer) = self.renderer.as_mut() {
                    renderer.select_backend_snapshot(backend, active_session, windows)
                } else {
                    self.pending_backend_snapshots
                        .insert(backend, (active_session, windows));
                    None
                };
                if let Err(error) = self.sync_computer_use_presentation() {
                    self.fail(
                        event_loop,
                        error.context("refresh computer-use presentation authority"),
                    );
                    return;
                }
                let synchronized_inventory_changed = self
                    .active_synchronized_resize
                    .as_ref()
                    .zip(self.renderer.as_ref())
                    .is_some_and(|(active, renderer)| {
                        !synchronized_resize_inventory_matches(active, &renderer.pane_inventory())
                    });
                if synchronized_inventory_changed {
                    match self.abort_synchronized_resize_for_inventory_change() {
                        Ok(change) => focus_change = change.or(focus_change),
                        Err(error) => {
                            self.fail(event_loop, error);
                            return;
                        }
                    }
                }
                if let Some(change) = focus_change
                    && let Err(error) = dispatch_focus_change(
                        self.wasm_runtime.as_ref(),
                        self.input_sender.as_mut(),
                        change,
                        self.window_focused,
                    )
                {
                    self.fail(event_loop, error);
                    return;
                }
                if let Some(snapshot) = session {
                    self.backend_sessions.insert(backend, snapshot.clone());
                    if let Some(runtime) = self.wasm_runtime.as_mut() {
                        runtime.bind_session_snapshot(&snapshot);
                        if let Err(error) = runtime
                            .broadcast_session_event(&SessionEvent::Snapshot(snapshot.clone()))
                        {
                            self.fail(event_loop, error);
                            return;
                        }
                        runtime.stop_actors_for_closed_sessions(&snapshot);
                    }
                }
                if let Err(error) = self.publish_backend_sessions() {
                    eprintln!("could not publish backend session catalogue: {error:#}");
                }
            }
            ClientEvent::SessionCommandCompleted {
                actor_id,
                completion,
            } => {
                eprintln!(
                    "presentation session command completed actor={} request={} operation={:?} success={} session={:?} message={}",
                    actor_id,
                    completion.request,
                    completion.operation,
                    completion.success,
                    completion.session,
                    completion.message,
                );
                let focus_change = completion
                    .success
                    .then_some(completion.operation)
                    .filter(|operation| {
                        matches!(
                            operation,
                            SessionOperation::Activate | SessionOperation::Create
                        )
                    })
                    .and(completion.session)
                    .and_then(|session| {
                        self.renderer.as_mut().and_then(|renderer| {
                            renderer
                                .select_active_session(BackendId(completion.backend_id), session)
                        })
                    });
                if let Some(change) = focus_change
                    && let Err(error) = dispatch_focus_change(
                        self.wasm_runtime.as_ref(),
                        self.input_sender.as_mut(),
                        change,
                        self.window_focused,
                    )
                {
                    self.fail(event_loop, error);
                    return;
                }
                if let Some(runtime) = self.wasm_runtime.as_ref()
                    && completion.success
                    && completion.operation == SessionOperation::Refresh
                    && let Some(snapshot) = self
                        .backend_sessions
                        .get(&BackendId(completion.backend_id))
                        .cloned()
                    && let Err(error) =
                        runtime.send_session_event(&actor_id, SessionEvent::Snapshot(snapshot))
                {
                    self.fail(event_loop, error);
                    return;
                }
                if let Some(runtime) = self.wasm_runtime.as_ref()
                    && let Err(error) = runtime
                        .send_session_event(&actor_id, SessionEvent::CommandCompleted(completion))
                {
                    self.fail(event_loop, error);
                }
            }
            ClientEvent::ActorHostMessagesReady => {
                if let Err(error) = self
                    .apply_actor_host_messages()
                    .and_then(|()| self.publish_layout_state())
                {
                    self.fail(event_loop, error);
                }
            }
            // Lifecycle completions are drained by the common pre-dispatch
            // pass at the top of `user_event`.
            ClientEvent::ActorLifecycleReady => {}
            ClientEvent::BackendActorMessage {
                backend,
                realm,
                sender,
                recipient,
                body,
                received_at,
            } => {
                if !self.backend_registry.observe(backend, None) {
                    return;
                }
                if sender == COMPUTER_USE_SERVER_ACTOR && recipient == COMPUTER_USE_OBSERVER_ACTOR {
                    if let Ok(chunk) =
                        serde_json::from_slice::<ComputerObservationFrameChunk>(&body)
                    {
                        if let Err(error) = self.accept_computer_use_frame_chunk(backend, chunk) {
                            self.computer_use_frame_assemblies.remove(&backend);
                            eprintln!(
                                "dropped invalid computer-use observer frame backend={} error={error:#}",
                                backend.0,
                            );
                        }
                        return;
                    }
                    match serde_json::from_slice::<ComputerUseObserverUpdate>(&body) {
                        Ok(update) => {
                            let tasks = update
                                .tasks
                                .iter()
                                .map(|task| {
                                    serde_json::json!({
                                        "id": task.id,
                                        "state": task.state,
                                        "next_sequence": task.next_sequence,
                                    })
                                })
                                .collect::<Vec<_>>();
                            eprintln!(
                                "computer-use observer update backend={} event_cursor={} tasks={} approvals={} observations={} task_states={}",
                                backend.0,
                                update.event_cursor,
                                update.tasks.len(),
                                update.approvals.len(),
                                update.observations.len(),
                                serde_json::to_string(&tasks).unwrap_or_else(|_| "[]".to_string()),
                            );
                            self.computer_use_observer_updates.insert(backend, update);
                            if let Err(error) = self.sync_computer_use_presentation() {
                                eprintln!(
                                    "dropped computer-use presentation update backend={} error={error:#}",
                                    backend.0,
                                );
                            }
                        }
                        Err(error) => {
                            eprintln!(
                                "dropped invalid computer-use observer update backend={} error={error}",
                                backend.0,
                            );
                        }
                    }
                    return;
                }
                if body.starts_with(b"BTRM")
                    && sender.starts_with("terminal-session")
                    && let Some(pane) = self.wasm_runtime.as_ref().and_then(|runtime| {
                        runtime
                            .pane_actor_ids()
                            .find_map(|(pane, actor)| (actor == recipient).then_some(pane))
                    })
                {
                    let dispatched = Instant::now();
                    let acknowledged = terminal_snapshot_completes_revision(&body)
                        .then(|| terminal_snapshot_input_sequence(&body))
                        .flatten();
                    if sender == "terminal-session"
                        && recipient == "terminal-ui"
                        && let Some(acknowledged) = acknowledged
                    {
                        self.latest_primary_terminal_input_ack =
                            self.latest_primary_terminal_input_ack.max(acknowledged);
                    }
                    if let Some(acknowledged) = acknowledged
                        && let Some(plugin_graphics) = self.plugin_graphics.as_ref()
                        && let Err(error) =
                            plugin_graphics.expect_terminal_snapshot(pane, acknowledged)
                    {
                        eprintln!(
                            "could not correlate terminal snapshot with plugin graphics \
                             pane={pane}: {error:#}"
                        );
                    }
                    for input in &mut self.pending_plugin_inputs {
                        if input.pane == pane
                            && input.backend == Some(backend)
                            && input.trace_sequence.is_some()
                            && input.trace_sequence <= acknowledged
                            && input.transport_received.is_none()
                        {
                            input.transport_received = Some(received_at);
                            input.snapshot_dispatched = Some(dispatched);
                        }
                    }
                }
                if std::env::var_os("BROOD_TRACE_PLUGIN_INPUT").is_some()
                    && !PLUGIN_SCROLL_BENCH_ACTIVE.load(Ordering::Relaxed)
                {
                    if body.starts_with(b"BTRM") {
                        let input_sequence = terminal_snapshot_completes_revision(&body)
                            .then(|| terminal_snapshot_input_sequence(&body))
                            .flatten()
                            .unwrap_or(0);
                        eprintln!(
                            "backend actor message backend={} realm={realm:?} sender={sender} recipient={recipient} terminal_snapshot_bytes={} terminal_input_sequence={input_sequence}",
                            backend.0,
                            body.len()
                        );
                    } else {
                        eprintln!(
                            "backend actor message backend={} realm={realm:?} sender={sender} recipient={recipient} body={}",
                            backend.0,
                            String::from_utf8_lossy(&body)
                        );
                    }
                }
                if let Some(runtime) = self.wasm_runtime.as_ref()
                    && let Err(error) = runtime
                        .send_backend_actor_message(backend, realm, &recipient, &sender, body)
                {
                    eprintln!(
                        "dropped backend actor message for unavailable presentation actor \
                         {recipient:?}: {error:#}"
                    );
                }
            }
            ClientEvent::ManagedResizeStatus {
                backend,
                connection_generation,
                status,
            } => {
                if self.backend_registry.connection_generation(backend)
                    != Some(connection_generation)
                {
                    eprintln!(
                        "dropped managed resize status from stale connection backend={} connection_generation={} pane={} epoch={}",
                        backend.0, connection_generation, status.pane, status.resize_epoch
                    );
                    return;
                }
                eprintln!(
                    "managed resize status backend={} connection_generation={} pane={} epoch={} result={:?}",
                    backend.0,
                    connection_generation,
                    status.pane,
                    status.resize_epoch,
                    status.result
                );
                let mut protocol_violation = None;
                if let Some(renderer) = self.renderer.as_mut() {
                    let disposition = renderer.handle_managed_resize_status(
                        backend,
                        connection_generation,
                        status,
                    );
                    match disposition {
                        ManagedResizeStatusDisposition::None => {}
                        ManagedResizeStatusDisposition::Recovered { pane, wait } => {
                            eprintln!(
                                "managed resize status selected recovery backend={} pane={} epoch={} wait={wait}",
                                backend.0, pane, status.resize_epoch,
                            );
                        }
                        ManagedResizeStatusDisposition::ProtocolViolation { pane, epoch } => {
                            protocol_violation = Some(format!(
                                "contradictory managed resize status after exact frame backend={} connection_generation={} pane={pane} epoch={epoch}",
                                backend.0, connection_generation
                            ));
                        }
                    }
                }
                if let Some(reason) = protocol_violation {
                    let focus_change = match self.disconnect_remote_backend(backend, &reason) {
                        Ok(change) => change,
                        Err(error) => {
                            self.fail(event_loop, anyhow!("{reason}: {error:#}"));
                            return;
                        }
                    };
                    if let Some(change) = focus_change
                        && let Err(error) = dispatch_focus_change(
                            self.wasm_runtime.as_ref(),
                            self.input_sender.as_mut(),
                            change,
                            self.window_focused,
                        )
                    {
                        self.fail(event_loop, error);
                    }
                    return;
                }
                if let Err(error) = self.reconcile_managed_resize_recovery() {
                    self.fail(event_loop, error);
                }
            }
            event => {
                if let Err(error) = self.accept_frame(event) {
                    self.fail(event_loop, error);
                }
            }
        }
    }

    fn about_to_wait(&mut self, event_loop: &ActiveEventLoop) {
        let _callback_guard = WinitCallbackGuard::new(
            Arc::clone(&self.winit_hot_path_metrics),
            self.render_scheduling_warmup_complete,
            "about_to_wait",
            None,
        );
        let callback_now = Instant::now();
        if self
            .next_periodic_actor_poll
            .is_some_and(|deadline| callback_now >= deadline)
        {
            self.next_periodic_actor_poll = None;
            self.periodic_actor_polls = self.periodic_actor_polls.saturating_add(1);
        }
        if !self.drain_wasm_events(event_loop) {
            return;
        }
        self.flush_synchronized_layout_terminal_notifications();
        if self.pending_synchronized_layout_notifications.is_empty()
            && (!self.deferred_actor_host_messages.is_empty()
                || self
                    .wasm_runtime
                    .as_ref()
                    .is_some_and(|runtime| runtime.pending_outbound_host_messages() > 0))
            && let Err(error) = self.apply_actor_host_messages()
        {
            self.fail(event_loop, error);
            return;
        }
        if let Some(wayland_drop) = self.wayland_drop.as_mut()
            && let Err(error) = wayland_drop.dispatch_pending()
        {
            self.fail(event_loop, error);
            return;
        }
        if let Err(error) = self.settle_window_resize() {
            self.fail(event_loop, error);
            return;
        }
        self.settle_native_window_resize_timeout();
        match self.settle_synchronized_resize() {
            Ok(Some(change)) => {
                if let Err(error) = dispatch_focus_change(
                    self.wasm_runtime.as_ref(),
                    self.input_sender.as_mut(),
                    change,
                    self.window_focused,
                ) {
                    self.fail(event_loop, error);
                    return;
                }
            }
            Ok(None) => {}
            Err(error) => {
                self.fail(event_loop, error);
                return;
            }
        }
        self.flush_managed_resource_releases();
        self.sync_default_backend_target();
        if let Err(error) = self.publish_layout_state() {
            self.fail(event_loop, error);
            return;
        }
        self.emit_setup_layout_quiescence_if_ready();
        if let (Some(graphics), Some(renderer)) =
            (self.plugin_graphics.as_ref(), self.renderer.as_ref())
            && let Err(error) = graphics.set_visible_panes(
                renderer.render_relevant_plugin_panes(
                    self.active_synchronized_resize
                        .as_ref()
                        .map(|active| &active.wait_panes),
                ),
                renderer.composition_relevant_plugin_panes(
                    self.active_synchronized_resize
                        .as_ref()
                        .map(|active| &active.wait_panes),
                ),
            )
        {
            self.fail(event_loop, error);
            return;
        }
        if let Err(error) = self.service_plugin_render_scheduler() {
            self.fail(event_loop, error);
            return;
        }
        if let Some(renderer) = self.renderer.as_mut() {
            flush_renderer_plugin_resize_events_best_effort(
                self.wasm_runtime.as_ref(),
                renderer,
                "event-loop flush",
            );
        }
        let graphics_preparation = self
            .renderer
            .as_ref()
            .map(|renderer| Arc::clone(&renderer.graphics_preparation));
        let graphics_preparation_result = graphics_preparation.as_ref().map(|lane| {
            let mut graphics_preparation = lane
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            graphics_preparation
                .flush_deferred()
                .map(|()| graphics_preparation.is_backpressured())
        });
        match graphics_preparation_result {
            Some(Ok(_)) | None => {}
            Some(Err(error)) => {
                self.fail(event_loop, error);
                return;
            }
        }
        let gpu_completion_result = self
            .gpu_submission_completion
            .as_mut()
            .map(GpuSubmissionCompletionLane::flush_deferred);
        if let Some(Err(error)) = gpu_completion_result {
            self.fail(event_loop, error);
            return;
        }
        if self.gpu_submission_redraw_deferred
            && self
                .gpu_submission_completion
                .as_ref()
                .is_some_and(GpuSubmissionCompletionLane::can_accept_submission)
        {
            self.gpu_submission_redraw_deferred = false;
            if let Some(renderer) = self.renderer.as_ref() {
                renderer.window.request_redraw();
            }
        }
        if let Some(lane) = self.input_sender.as_mut() {
            lane.flush_deferred();
        }
        if let Some(lane) = self.actor_message_sender.as_mut() {
            lane.flush_deferred();
        }
        if let Some(lane) = self.backend_commands.as_ref() {
            lane.flush_deferred();
        }
        // A full actor lane keeps the latest position for the next Winit turn.
        // Motion is state, so intermediate samples are disposable.
        let _motion_result = flush_presentation_pointer_motion(
            self.wasm_runtime.as_ref(),
            &mut self.pointer_routing.pending_plugin_motion,
        );
        let auto_scroll_benchmark =
            std::env::var("BROOD_TERMINAL_SCROLL_BENCH_AUTO").as_deref() == Ok("1");
        if auto_scroll_benchmark
            && self
                .plugin_scroll_benchmark
                .as_ref()
                .is_some_and(|benchmark| {
                    benchmark.input_events == 0
                        && benchmark
                            .last_scene
                            .is_some_and(|last| last.elapsed() >= Duration::from_millis(80))
                })
        {
            if let Some(benchmark) = self.plugin_scroll_benchmark.take()
                && benchmark.scene_count() >= 30
            {
                eprintln!(
                    "plugin helix scroll diagnostics {}",
                    benchmark.diagnostics()
                );
            }
            PLUGIN_SCROLL_BENCH_ACTIVE.store(false, Ordering::Relaxed);
        }
        if let Err(error) = self.synchronize_event_loop_deadline(true) {
            self.fail(event_loop, error);
            return;
        }
        // Winit's Wayland backend does not suppress empty calloop wakeups while
        // a `WaitUntil` timeout is installed. A real future render deadline can
        // therefore produce millions of empty `about_to_wait` turns before it
        // becomes due. The application-owned deadline waker above preserves
        // the exact earliest deadline and converts it to one causal user event;
        // Winit itself can remain fully event driven. Retained lane state does
        // not create a synthetic timer.
        event_loop.set_control_flow(ControlFlow::Wait);
    }

    fn exiting(&mut self, _event_loop: &ActiveEventLoop) {
        self.drop_frontend_wayland_state();
    }

    fn window_event(
        &mut self,
        event_loop: &ActiveEventLoop,
        window_id: WindowId,
        event: WindowEvent,
    ) {
        let _profile_span = brood_profiler::Span::new(
            "event_loop",
            "window_event",
            None,
            vec![("kind".into(), window_event_callback_kind(&event).into())],
        );
        let mut callback_guard = WinitCallbackGuard::new(
            Arc::clone(&self.winit_hot_path_metrics),
            self.render_scheduling_warmup_complete,
            "window_event",
            Some(window_event_callback_kind(&event)),
        );
        let Some(renderer) = self.renderer.as_ref() else {
            return;
        };
        if renderer.window.id() != window_id {
            return;
        }

        if matches!(
            &event,
            WindowEvent::Moved(_)
                | WindowEvent::Resized(_)
                | WindowEvent::ScaleFactorChanged { .. }
        ) {
            self.sync_render_predictor_refresh();
        }

        if let WindowEvent::Resized(size) = &event {
            self.handle_window_resized(event_loop, *size);
            return;
        }
        if let WindowEvent::ScaleFactorChanged { scale_factor, .. } = &event {
            self.handle_scale_factor_changed(event_loop, *scale_factor);
            return;
        }
        let resize_element_pane = std::env::var_os("BROOD_TRACE_RESIZE_ELEMENT")
            .is_some()
            .then(|| {
                self.wasm_runtime.as_ref().and_then(|runtime| {
                    runtime
                        .pane_actor_ids()
                        .find_map(|(pane, actor)| (actor == "session-switcher").then_some(pane))
                })
            })
            .flatten();
        let mut composition_revealed_deadline = false;
        let Some(renderer) = self.renderer.as_mut() else {
            return;
        };

        match event {
            WindowEvent::CloseRequested => event_loop.exit(),
            WindowEvent::CursorMoved { position, .. } => {
                self.cursor_position = Some((position.x, position.y));
                let zone_route = match route_layout_zone_pointer(
                    renderer,
                    &mut self.pointer_policy,
                    self.wasm_runtime.as_ref(),
                    &self.layout_holders,
                    &self.layout_leases,
                    self.layout_revision,
                    self.active_synchronized_resize
                        .as_ref()
                        .map_or(self.presented_layout_revision, |active| {
                            active.epoch.target_layout_revision
                        }),
                    &mut self.policy_pointer_capture,
                    &mut self.pointer_interactions,
                    &mut self.next_pointer_interaction,
                    &mut self.pointer_event_sequence,
                    self.cursor_position,
                    brood_wasm::PointerPhase::Motion,
                    PointerEventMask::MOTION,
                    None,
                    modifier_bits(self.modifiers),
                ) {
                    Ok(route) => route,
                    Err(error) => {
                        eprintln!("pointer-policy motion failed: {error:#}");
                        PointerPolicyRoute::Consumed
                    }
                };
                if self.active_synchronized_resize.is_none() {
                    self.resize_presentation_trace = ResizePresentationTrace {
                        interaction: self
                            .policy_pointer_capture
                            .as_ref()
                            .map_or(0, |capture| capture.interaction.0),
                        event_sequence: self.pointer_event_sequence,
                        ..ResizePresentationTrace::default()
                    };
                }
                let PointerPolicyRoute::Forward {
                    position,
                    modifiers: _,
                } = zone_route
                else {
                    self.pointer_routing.pending_plugin_motion = None;
                    send_plugin_pointer_leave(
                        self.wasm_runtime.as_ref(),
                        &mut self.pointer_routing.plugin_target,
                    );
                    send_managed_pointer_leave(
                        self.input_sender.as_mut(),
                        &mut self.pointer_routing.managed_target,
                    );
                    return;
                };
                if pointer_target_for_cursor(renderer, position, self.pointer_grab.as_ref())
                    .is_some_and(|target| {
                        matches!(target, PanePointerTarget::Managed { pane, .. } if renderer.automated_pane_is_locked(pane))
                    })
                {
                    self.pointer_routing.pending_plugin_motion = None;
                    send_managed_pointer_leave(
                        self.input_sender.as_mut(),
                        &mut self.pointer_routing.managed_target,
                    );
                    return;
                }
                route_pointer_motion(
                    renderer,
                    position,
                    &mut self.pointer_grab,
                    self.wasm_runtime.as_ref(),
                    self.input_sender.as_mut(),
                    &mut self.pointer_routing,
                );
            }
            WindowEvent::CursorLeft { .. } => {
                self.cursor_position = None;
                renderer.set_zone_pointer_state(
                    None,
                    self.policy_pointer_capture
                        .as_ref()
                        .map(|capture| capture.zone),
                    if self.policy_pointer_capture.is_some() {
                        renderer
                            .presented_zones
                            .iter()
                            .find(|zone| {
                                Some(zone.id)
                                    == self
                                        .policy_pointer_capture
                                        .as_ref()
                                        .map(|capture| capture.zone)
                            })
                            .map_or(CursorRole::Default, |zone| zone.cursor)
                    } else {
                        CursorRole::Default
                    },
                );
                self.pointer_routing.pending_plugin_motion = None;
                send_plugin_pointer_leave(
                    self.wasm_runtime.as_ref(),
                    &mut self.pointer_routing.plugin_target,
                );
                send_managed_pointer_leave(
                    self.input_sender.as_mut(),
                    &mut self.pointer_routing.managed_target,
                );
            }
            WindowEvent::DroppedFile(path) => {
                deliver_dropped_image(
                    renderer,
                    self.wasm_runtime.as_ref(),
                    self.cursor_position,
                    &path,
                );
            }
            WindowEvent::MouseInput { state, button, .. } => {
                let Some(button_code) = linux_button_code(button) else {
                    return;
                };
                let pressed = state == ElementState::Pressed;
                let zone_route = match route_layout_zone_pointer(
                    renderer,
                    &mut self.pointer_policy,
                    self.wasm_runtime.as_ref(),
                    &self.layout_holders,
                    &self.layout_leases,
                    self.layout_revision,
                    self.active_synchronized_resize
                        .as_ref()
                        .map_or(self.presented_layout_revision, |active| {
                            active.epoch.target_layout_revision
                        }),
                    &mut self.policy_pointer_capture,
                    &mut self.pointer_interactions,
                    &mut self.next_pointer_interaction,
                    &mut self.pointer_event_sequence,
                    self.cursor_position,
                    if pressed {
                        brood_wasm::PointerPhase::ButtonPress
                    } else {
                        brood_wasm::PointerPhase::ButtonRelease
                    },
                    if pressed {
                        PointerEventMask::BUTTON_PRESS
                    } else {
                        PointerEventMask::RELEASE
                    },
                    Some(button_code),
                    modifier_bits(self.modifiers),
                ) {
                    Ok(route) => route,
                    Err(error) => {
                        eprintln!("pointer-policy button failed: {error:#}");
                        PointerPolicyRoute::Consumed
                    }
                };
                if self.active_synchronized_resize.is_none() {
                    self.resize_presentation_trace = ResizePresentationTrace {
                        interaction: self
                            .policy_pointer_capture
                            .as_ref()
                            .map_or(0, |capture| capture.interaction.0),
                        event_sequence: self.pointer_event_sequence,
                        ..ResizePresentationTrace::default()
                    };
                }
                let PointerPolicyRoute::Forward {
                    position,
                    modifiers,
                } = zone_route
                else {
                    self.pointer_routing.pending_plugin_motion = None;
                    return;
                };
                if !pressed
                    && self
                        .pointer_grab
                        .as_ref()
                        .is_none_or(|grab| !grab.buttons.contains(&button_code))
                {
                    return;
                }
                let Some(target) =
                    pointer_target_for_cursor(renderer, position, self.pointer_grab.as_ref())
                else {
                    return;
                };
                if matches!(target, PanePointerTarget::Managed { pane, .. } if renderer.automated_pane_is_locked(pane))
                {
                    return;
                }
                eprintln!(
                    "presentation pointer button target={target:?} pressed={pressed} client_grab_active={}",
                    self.pointer_grab.is_some()
                );
                if let Some(grab) = self.pointer_grab.as_mut() {
                    grab.target = target;
                    if pressed {
                        grab.press(button_code);
                    }
                } else if pressed {
                    self.pointer_grab = Some(PointerGrab::new(target, button_code));
                }

                if pressed && let Some(change) = renderer.focus_pane(target.pane()) {
                    if let Err(error) = dispatch_focus_change(
                        self.wasm_runtime.as_ref(),
                        self.input_sender.as_mut(),
                        change,
                        self.window_focused,
                    ) {
                        eprintln!("dropped pane focus event: {error:#}");
                    }
                    flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
                }

                send_pointer_button_to_target(
                    self.wasm_runtime.as_ref(),
                    self.input_sender.as_mut(),
                    &mut self.pointer_routing,
                    target,
                    PointerButtonState {
                        button: button_code,
                        pressed,
                        modifiers,
                    },
                );

                let grab_ended = !pressed
                    && self
                        .pointer_grab
                        .as_mut()
                        .is_some_and(|grab| grab.release(button_code));
                if grab_ended {
                    eprintln!("presentation pointer grab ended target={target:?}");
                    self.pointer_grab = None;
                    route_pointer_motion(
                        renderer,
                        self.cursor_position,
                        &mut self.pointer_grab,
                        self.wasm_runtime.as_ref(),
                        self.input_sender.as_mut(),
                        &mut self.pointer_routing,
                    );
                }
            }
            WindowEvent::MouseWheel { delta, .. } => {
                let Some(target) = pointer_target_for_cursor(
                    renderer,
                    self.cursor_position,
                    self.pointer_grab.as_ref(),
                ) else {
                    return;
                };
                if matches!(target, PanePointerTarget::Managed { pane, .. } if renderer.automated_pane_is_locked(pane))
                {
                    return;
                }
                eprintln!(
                    "presentation pointer scroll target={target:?} client_grab_active={}",
                    self.pointer_grab.is_some()
                );
                if let Some(grab) = self.pointer_grab.as_mut() {
                    grab.target = target;
                }
                match target {
                    PanePointerTarget::Plugin { pane, x, y } => {
                        let scale = renderer.window.scale_factor() as f32;
                        let (horizontal, vertical) = match delta {
                            MouseScrollDelta::LineDelta(x, y) => (x * 15.0, y * 15.0),
                            MouseScrollDelta::PixelDelta(position) => {
                                (position.x as f32, position.y as f32)
                            }
                        };
                        send_managed_pointer_leave(
                            self.input_sender.as_mut(),
                            &mut self.pointer_routing.managed_target,
                        );
                        set_plugin_pointer_target(
                            self.wasm_runtime.as_ref(),
                            &mut self.pointer_routing.plugin_target,
                            pane,
                        );
                        if let Err(error) = send_presentation_event(
                            self.wasm_runtime.as_ref(),
                            PresentationEvent::PointerScroll {
                                pane,
                                x,
                                y,
                                horizontal: horizontal / scale,
                                vertical: vertical / scale,
                                modifiers: modifier_bits(self.modifiers),
                            },
                        ) {
                            eprintln!("dropped plugin pointer scroll: {error:#}");
                        }
                    }
                    PanePointerTarget::Managed { pane, x, y } => {
                        self.pointer_routing.pending_plugin_motion = None;
                        send_plugin_pointer_leave(
                            self.wasm_runtime.as_ref(),
                            &mut self.pointer_routing.plugin_target,
                        );
                        if let Some(sender) = self.input_sender.as_mut() {
                            let sent = match delta {
                                MouseScrollDelta::LineDelta(horizontal, vertical) => send_input(
                                    sender,
                                    ClientMessage::Input(InputEvent::PointerWheel {
                                        position: PanePosition { pane, x, y },
                                        horizontal_v120: wheel_v120(horizontal),
                                        vertical_v120: wheel_v120(vertical),
                                    }),
                                ),
                                MouseScrollDelta::PixelDelta(position) => {
                                    let scale = renderer.window.scale_factor().max(f64::EPSILON);
                                    send_input(
                                        sender,
                                        ClientMessage::Input(InputEvent::PointerAxis {
                                            position: PanePosition { pane, x, y },
                                            horizontal: -position.x / scale,
                                            vertical: -position.y / scale,
                                        }),
                                    )
                                }
                            };
                            if sent {
                                self.pointer_routing.managed_target = Some(pane);
                            }
                        }
                    }
                }
            }
            WindowEvent::ModifiersChanged(modifiers) => {
                self.modifiers = modifiers.state();
                if std::env::var_os("BROOD_TRACE_PLUGIN_INPUT").is_some() {
                    eprintln!("plugin keyboard modifiers state={:?}", self.modifiers);
                }
            }
            WindowEvent::Focused(focused) => {
                self.window_focused = focused;
                if let Some(sender) = self.input_sender.as_mut() {
                    let _sent = send_input(
                        sender,
                        ClientMessage::Input(InputEvent::PresentationFocus { focused }),
                    );
                }
                if !focused {
                    if let Some(sender) = self.input_sender.as_mut() {
                        send_keyboard_reset(sender);
                    }
                    cancel_pointer_grab(
                        self.wasm_runtime.as_ref(),
                        self.input_sender.as_mut(),
                        &mut self.pointer_routing,
                        &mut self.pointer_grab,
                        modifier_bits(self.modifiers),
                    );
                    if self.policy_pointer_capture.is_some()
                        && let Err(error) = route_layout_zone_pointer(
                            renderer,
                            &mut self.pointer_policy,
                            self.wasm_runtime.as_ref(),
                            &self.layout_holders,
                            &self.layout_leases,
                            self.layout_revision,
                            self.active_synchronized_resize
                                .as_ref()
                                .map_or(self.presented_layout_revision, |active| {
                                    active.epoch.target_layout_revision
                                }),
                            &mut self.policy_pointer_capture,
                            &mut self.pointer_interactions,
                            &mut self.next_pointer_interaction,
                            &mut self.pointer_event_sequence,
                            self.cursor_position,
                            brood_wasm::PointerPhase::Cancel,
                            PointerEventMask::CANCEL,
                            None,
                            modifier_bits(self.modifiers),
                        )
                    {
                        eprintln!("pointer-policy cancel failed: {error:#}");
                        self.policy_pointer_capture = None;
                        renderer.set_zone_pointer_state(None, None, CursorRole::Default);
                    }
                    self.cursor_position = None;
                    self.pointer_routing.pending_plugin_motion = None;
                    send_plugin_pointer_leave(
                        self.wasm_runtime.as_ref(),
                        &mut self.pointer_routing.plugin_target,
                    );
                    send_managed_pointer_leave(
                        self.input_sender.as_mut(),
                        &mut self.pointer_routing.managed_target,
                    );
                }
                if let Some(pane) = renderer.focused_plugin_pane()
                    && let Err(error) = send_presentation_event(
                        self.wasm_runtime.as_ref(),
                        PresentationEvent::PaneFocused { pane, focused },
                    )
                {
                    eprintln!("dropped plugin outer-window focus event: {error:#}");
                }
            }
            WindowEvent::KeyboardInput {
                event,
                is_synthetic,
                ..
            } => {
                let text_input =
                    plugin_text_input(&event.logical_key, event.text.as_deref(), self.modifiers);
                let logical_key = plugin_logical_key(&event.logical_key);
                let render_scheduling_proof =
                    std::env::var_os("BROOD_RENDER_SCHEDULING_PROOF").is_some();
                if render_scheduling_proof
                    && matches!(logical_key.as_str(), "F9" | "F10" | "F11" | "F12")
                {
                    // Proof-control release/repeat edges must not reach plugin input.
                    if event.state != ElementState::Pressed || event.repeat {
                        return;
                    }
                    match logical_key.as_str() {
                        "F9" => {
                            if let Some(proxy) = &self.event_proxy {
                                drop(proxy.send_event(ClientEvent::RendererFailed {
                                    generation: renderer.generation,
                                    message: "render-scheduling F9 proof recovery".to_owned(),
                                }));
                            }
                        }
                        "F10" => {
                            if renderer.toggle_render_scheduling_proof_visibility() {
                                eprintln!("render scheduling proof visibility toggled");
                            }
                        }
                        "F11" => {
                            if let (Some(baseline), Some(graphics)) = (
                                self.render_scheduling_idle_baseline.take(),
                                self.plugin_graphics.as_ref(),
                            ) && let Ok(diagnostics) = graphics.diagnostics()
                            {
                                self.render_scheduling_idle_measurement =
                                    Some(RenderSchedulingIdleMeasurement {
                                        duration_ms: baseline.started.elapsed().as_millis(),
                                        render_hints: diagnostics
                                            .render_scheduler
                                            .dispatched
                                            .saturating_sub(baseline.dispatched),
                                        actor_render_turns: diagnostics
                                            .render_scheduler
                                            .accepted
                                            .saturating_sub(baseline.accepted),
                                        scheduler_deadline_wakeups: diagnostics
                                            .render_scheduler
                                            .deadline_wakeups
                                            .saturating_sub(baseline.deadline_wakeups),
                                        scheduler_redraw_requests: self
                                            .render_scheduling_redraws
                                            .saturating_sub(baseline.redraws),
                                        periodic_actor_polls: self
                                            .periodic_actor_polls
                                            .saturating_sub(baseline.periodic_actor_polls),
                                        periodic_renderer_polls: self
                                            .periodic_renderer_polls
                                            .saturating_sub(baseline.periodic_renderer_polls),
                                        periodic_lifecycle_polls: self
                                            .periodic_lifecycle_polls
                                            .saturating_sub(baseline.periodic_lifecycle_polls),
                                    });
                                eprintln!("render scheduling proof idle interval finalized");
                            }
                        }
                        "F12" => {
                            if let Some(graphics) = self.plugin_graphics.as_ref()
                                && let Ok(diagnostics) = graphics.diagnostics()
                            {
                                self.render_scheduling_active_measurement
                                    .get_or_insert_with(|| RenderSchedulingActiveMeasurement {
                                        frame_intervals_ns: diagnostics
                                            .measured_frame_intervals_ns
                                            .clone(),
                                        opportunities: diagnostics.measured_opportunities,
                                        deadline_misses: diagnostics.measured_deadline_misses,
                                        target_misses: diagnostics.measured_target_misses,
                                        late_finishes: diagnostics.late_finish_diagnostics.clone(),
                                        late_finishes_dropped: diagnostics
                                            .late_finish_diagnostics_dropped,
                                    });
                                self.render_scheduling_idle_measurement = None;
                                self.render_scheduling_idle_baseline =
                                    Some(RenderSchedulingIdleBaseline {
                                        started: Instant::now(),
                                        dispatched: diagnostics.render_scheduler.dispatched,
                                        accepted: diagnostics.render_scheduler.accepted,
                                        deadline_wakeups: diagnostics
                                            .render_scheduler
                                            .deadline_wakeups,
                                        redraws: self.render_scheduling_redraws,
                                        periodic_actor_polls: self.periodic_actor_polls,
                                        periodic_renderer_polls: self.periodic_renderer_polls,
                                        periodic_lifecycle_polls: self.periodic_lifecycle_polls,
                                    });
                                eprintln!("render scheduling proof idle interval started");
                            }
                        }
                        _ => {}
                    }
                    return;
                }
                if render_scheduling_proof && event.state == ElementState::Pressed && !event.repeat
                {
                    self.render_scheduling_key_presses =
                        self.render_scheduling_key_presses.saturating_add(1);
                    if std::env::var("BROOD_RENDER_SCHEDULING_SCENARIO").as_deref()
                        == Ok("saturated_60hz")
                        && self.render_scheduling_warmup_complete
                        && self.render_scheduling_backend_requests_enqueued < 200
                        && let Some(commands) = self.backend_commands.as_ref()
                    {
                        let request = self.render_scheduling_backend_requests_enqueued;
                        match commands.try_send(
                            format!("render-scheduling-proof-status-{request}"),
                            vec!["status-json".to_owned()],
                        ) {
                            Ok(()) => {
                                self.render_scheduling_backend_requests_enqueued = self
                                    .render_scheduling_backend_requests_enqueued
                                    .saturating_add(1);
                            }
                            Err(error) => {
                                self.reliable_transition_drops =
                                    self.reliable_transition_drops.saturating_add(1);
                                eprintln!(
                                    "render scheduling proof backend request rejected: {error:#}"
                                );
                            }
                        }
                    }
                    if std::env::var("BROOD_RENDER_SCHEDULING_SCENARIO").as_deref()
                        == Ok("saturated_60hz")
                        && self.render_scheduling_warmup_complete
                        && self.render_scheduling_backend_actor_messages_enqueued < 200
                    {
                        match send_computer_use_observer_subscriptions(
                            &self.backend_registry,
                            self.actor_message_sender.as_mut(),
                        ) {
                            Ok(admitted) if admitted > 0 => {
                                self.render_scheduling_backend_actor_messages_enqueued = self
                                    .render_scheduling_backend_actor_messages_enqueued
                                    .saturating_add(admitted);
                            }
                            Ok(_) => {
                                self.reliable_transition_drops =
                                    self.reliable_transition_drops.saturating_add(1);
                                eprintln!(
                                    "render scheduling proof backend actor message had no destination"
                                );
                            }
                            Err(error) => {
                                self.reliable_transition_drops =
                                    self.reliable_transition_drops.saturating_add(1);
                                eprintln!(
                                    "render scheduling proof backend actor message rejected: {error:#}"
                                );
                            }
                        }
                    }
                }
                if self.automation_unlock_key_down && logical_key == "Escape" {
                    if event.state == ElementState::Released {
                        self.automation_unlock_key_down = false;
                    }
                    return;
                }
                if let Some(pane) = renderer.focused_managed_window()
                    && renderer.automated_pane_is_locked(pane)
                {
                    if logical_key == "Escape" && event.state == ElementState::Pressed {
                        let Some((backend, task)) = renderer.locked_automation_task() else {
                            return;
                        };
                        let body = match serde_json::to_vec(&ComputerUseObserverCommand::Unlock {
                            task,
                        }) {
                            Ok(body) => body,
                            Err(error) => {
                                eprintln!("could not encode computer-use unlock: {error}");
                                return;
                            }
                        };
                        let Some(sender) = self.actor_message_sender.as_mut() else {
                            eprintln!("computer-use unlock ignored without actor-message lane");
                            return;
                        };
                        if let Err(error) =
                            sender.send(&actor_runtime::BackendActorMessageRequest {
                                backend,
                                sender: COMPUTER_USE_OBSERVER_ACTOR.to_string(),
                                realm: BackendActorRealm::Daemon,
                                actor: COMPUTER_USE_SERVER_ACTOR.to_string(),
                                body,
                            })
                        {
                            eprintln!("computer-use unlock request failed: {error:#}");
                            return;
                        }
                        self.automation_unlock_key_down = true;
                        eprintln!(
                            "computer-use interaction unlock requested backend={}",
                            backend.0
                        );
                    }
                    return;
                }
                if std::env::var_os("BROOD_TERMINAL_SCROLL_BENCH").is_some()
                    && matches!(logical_key.as_str(), "F11" | "F12")
                    && let Some(pane) = renderer.focused_plugin_pane()
                {
                    if event.state == ElementState::Pressed {
                        if logical_key == "F12" {
                            reset_plugin_scroll_presentation_counts();
                            self.plugin_scroll_benchmark = Some(PluginScrollBenchmark::new(pane));
                            PLUGIN_SCROLL_BENCH_ACTIVE.store(true, Ordering::Relaxed);
                        } else {
                            PLUGIN_SCROLL_BENCH_ACTIVE.store(false, Ordering::Relaxed);
                            if let Some(benchmark) = self.plugin_scroll_benchmark.take() {
                                eprintln!(
                                    "plugin helix scroll diagnostics {}",
                                    benchmark.diagnostics()
                                );
                            }
                            if std::env::var_os("BROOD_TRACE_PLUGIN_INPUT").is_some() {
                                eprintln!(
                                    "terminal snapshot drain sender=terminal-session recipient=terminal-ui terminal_input_sequence={}",
                                    self.latest_primary_terminal_input_ack
                                );
                                let inputs = self
                                    .pending_plugin_inputs
                                    .iter()
                                    .filter(|input| input.pane == pane)
                                    .collect::<Vec<_>>();
                                eprintln!(
                                    "terminal input stages {}",
                                    serde_json::json!({
                                        "pane": pane,
                                        "total": inputs.len(),
                                        "backend": inputs.iter().filter(|input| input.backend.is_some()).count(),
                                        "trace_sequence": inputs.iter().filter(|input| input.trace_sequence.is_some()).count(),
                                        "max_trace_sequence": inputs.iter().filter_map(|input| input.trace_sequence).max().unwrap_or(0),
                                        "transport_sent": inputs.iter().filter(|input| input.transport_sent.is_some()).count(),
                                        "transport_received": inputs.iter().filter(|input| input.transport_received.is_some()).count(),
                                        "snapshot_dispatched": inputs.iter().filter(|input| input.snapshot_dispatched.is_some()).count(),
                                        "graphics_ready": inputs.iter().filter(|input| input.graphics_ready.is_some()).count(),
                                        "ready": inputs.iter().filter(|input| input.ready).count(),
                                    })
                                );
                                eprintln!(
                                    "terminal input drain pending_plugin_inputs={}",
                                    self.pending_plugin_inputs.len()
                                );
                            }
                        }
                    }
                    return;
                }
                if std::env::var_os("BROOD_TRACE_PLUGIN_INPUT").is_some()
                    && !PLUGIN_SCROLL_BENCH_ACTIVE.load(Ordering::Relaxed)
                {
                    eprintln!(
                        "plugin keyboard input logical={logical_key:?} physical={:?} \
                         state={:?} synthetic={is_synthetic} modifiers={:?}",
                        event.physical_key, event.state, self.modifiers
                    );
                }
                let policy_evaluation =
                    event.physical_key.to_scancode().and_then(|scancode| {
                        let mut snapshot = renderer.key_policy_snapshot();
                        if let Some(runtime) = self.wasm_runtime.as_ref() {
                            snapshot.app_panes.extend(runtime.pane_actor_ids().map(
                                |(pane, actor)| KeyPolicyAppPane {
                                    pane,
                                    app_id: actor.to_string(),
                                },
                            ));
                        }
                        self.key_policy.as_mut().and_then(|policy| {
                            match policy.evaluate(
                                i32::try_from(scancode.saturating_add(8)).unwrap_or(i32::MAX),
                                match event.state {
                                    ElementState::Pressed => brood_wasm::ABI_KEY_PRESSED,
                                    ElementState::Released => brood_wasm::ABI_KEY_RELEASED,
                                },
                                key_policy_modifier_bits(self.modifiers),
                                event.repeat,
                                &snapshot,
                            ) {
                                Ok(evaluation) => Some(evaluation),
                                Err(error) => {
                                    eprintln!(
                                        "presentation key policy failed; forwarding key: {error:#}"
                                    );
                                    None
                                }
                            }
                        })
                    });

                let mut forward_key = true;
                if let Some(evaluation) = policy_evaluation {
                    forward_key = matches!(
                        evaluation.decision,
                        GlobalKeyDecision::Abstain
                            | GlobalKeyDecision::Forward
                            | GlobalKeyDecision::ForwardWithModifiers
                    );
                    for message in evaluation.actor_messages {
                        if let Some(runtime) = self.wasm_runtime.as_ref() {
                            match runtime.send_key_policy_message(&message.actor, message.payload) {
                                Ok(()) => eprintln!(
                                    "sent key-policy actor message actor={}",
                                    message.actor
                                ),
                                Err(error) => {
                                    eprintln!("dropped key-policy actor message: {error:#}");
                                }
                            }
                        }
                    }
                    for message in evaluation.host_messages {
                        if let Err(error) = apply_key_policy_host_message(
                            renderer,
                            &mut self.input_sender,
                            self.backend_commands.as_ref(),
                            self.wasm_runtime.as_mut(),
                            self.clipboard.as_ref(),
                            message,
                            self.window_focused,
                        ) {
                            eprintln!("rejected key-policy host message: {error:#}");
                        }
                    }
                    flush_renderer_managed_resize_requests(self.input_sender.as_mut(), renderer);
                }

                if !forward_key {
                    return;
                }

                let modifiers = modifier_bits(self.modifiers);
                if let Some(pane) = renderer.focused_plugin_pane() {
                    let physical_key = event.physical_key.to_scancode().unwrap_or_default();
                    let track_terminal_input =
                        should_track_terminal_text_input(modifiers, event.text.as_deref());
                    let sent = send_presentation_event(
                        self.wasm_runtime.as_ref(),
                        PresentationEvent::Key {
                            pane,
                            physical_key,
                            logical_key,
                            pressed: event.state == ElementState::Pressed,
                            repeat: event.repeat,
                            modifiers,
                        },
                    );
                    let delivered = sent.is_ok();
                    let terminal_input = self.wasm_runtime.as_ref().is_some_and(|runtime| {
                        runtime.pane_actor_ids().any(|(actor_pane, actor)| {
                            actor_pane == pane && actor.starts_with("terminal-ui")
                        })
                    });
                    if let Err(error) = sent {
                        eprintln!("dropped plugin key event: {error:#}");
                    } else if event.state == ElementState::Pressed
                        && track_terminal_input
                        && terminal_input
                    {
                        self.pending_plugin_inputs.push_back(PendingPluginInput {
                            pane,
                            backend: renderer
                                .plugin_pane_realms
                                .get(&pane)
                                .copied()
                                .flatten()
                                .map(|(backend, _session)| backend),
                            trace_sequence: None,
                            started: Instant::now(),
                            started_unix_us: SystemTime::now()
                                .duration_since(UNIX_EPOCH)
                                .map_or(0, |elapsed| elapsed.as_micros()),
                            transport_queued: None,
                            transport_sent: None,
                            transport_received: None,
                            snapshot_dispatched: None,
                            graphics_ready: None,
                            ready: false,
                        });
                        if self.pending_plugin_inputs.len() > 4_096 {
                            self.pending_plugin_inputs.pop_front();
                        }
                    }
                    if delivered
                        && event.state == ElementState::Pressed
                        && let Some(benchmark) = self.plugin_scroll_benchmark.as_mut()
                        && benchmark.pane == pane
                    {
                        benchmark.record_input(Instant::now());
                    }
                    if event.state == ElementState::Pressed
                        && let Some(text) = text_input.as_deref()
                    {
                        if std::env::var_os("BROOD_TRACE_PLUGIN_INPUT").is_some()
                            && !PLUGIN_SCROLL_BENCH_ACTIVE.load(Ordering::Relaxed)
                        {
                            eprintln!("plugin text input text={text:?}");
                        }
                        if let Err(error) = send_presentation_event(
                            self.wasm_runtime.as_ref(),
                            PresentationEvent::Text {
                                pane,
                                text: text.to_string(),
                            },
                        ) {
                            eprintln!("dropped plugin text event: {error:#}");
                        } else if let Some(benchmark) = self.plugin_scroll_benchmark.as_mut()
                            && benchmark.pane == pane
                        {
                            benchmark.record_text();
                        }
                    }
                } else if renderer.focused_managed_window().is_some()
                    && let (Some(sender), Some(scancode)) =
                        (self.input_sender.as_mut(), event.physical_key.to_scancode())
                {
                    send_input(
                        sender,
                        ClientMessage::Input(InputEvent::KeyboardKey {
                            keycode: scancode + 8,
                            pressed: event.state == ElementState::Pressed,
                        }),
                    );
                }
            }
            WindowEvent::RedrawRequested => {
                self.render_scheduling_redraws = self.render_scheduling_redraws.saturating_add(1);
                let callback_target_ns = self.plugin_graphics.as_ref().map_or(0, |graphics| {
                    let callback_target_ns = graphics.mark_winit_redraw_started().unwrap_or(0);
                    if let Some((_requested_target_ns, requested_at)) =
                        self.pending_composition_redraw_request.take()
                    {
                        graphics.note_winit_redraw_hop(
                            u64::try_from(requested_at.elapsed().as_nanos()).unwrap_or(u64::MAX),
                        );
                    }
                    callback_target_ns
                });
                if let Some(benchmark) = self.plugin_scroll_benchmark.as_mut() {
                    benchmark.record_redraw();
                }
                let current_frame_sequences = renderer
                    .frame_sequences()
                    .into_iter()
                    .filter_map(|(backend, sequence)| {
                        self.backend_registry.connection_generation(backend).map(
                            |connection_generation| CompletedFrameSequence {
                                backend,
                                connection_generation,
                                sequence,
                            },
                        )
                    })
                    .collect::<Vec<_>>();
                let scene_completion_required = self
                    .gpu_scene_completions
                    .has_unsubmitted(&current_frame_sequences);
                if scene_completion_required
                    && self
                        .gpu_submission_completion
                        .as_ref()
                        .is_none_or(|lane| !lane.can_accept_submission())
                {
                    // Admission happens before queue.submit. The completion
                    // worker's next causal event requests the deferred redraw.
                    self.gpu_submission_redraw_deferred = true;
                    return;
                }
                let promoting_resize_epoch =
                    self.active_synchronized_resize.as_ref().and_then(|active| {
                        matches!(
                            active.presentation,
                            SynchronizedResizePresentation::Ready { .. }
                        )
                        .then_some(active.epoch.id)
                    });
                let promoting_resize_degraded = self
                    .active_synchronized_resize
                    .as_ref()
                    .is_some_and(|active| {
                        matches!(
                            active.presentation,
                            SynchronizedResizePresentation::Ready { degraded: true, .. }
                        )
                    });
                match promote_ready_synchronized_resize(
                    self.active_synchronized_resize.as_mut(),
                    renderer,
                    &mut self.resize_presentation_trace,
                ) {
                    Ok(Some(change)) => {
                        if let Some(epoch) = promoting_resize_epoch {
                            if promoting_resize_degraded {
                                let cancelled = take_resize_render_tokens_for_epoch(
                                    &mut self.pending_render_token_resize_epochs,
                                    epoch,
                                );
                                for token in &cancelled {
                                    self.pending_render_tokens.remove(token);
                                }
                                if let Some(graphics) = self.plugin_graphics.as_ref() {
                                    graphics.cancel_accepted_tokens(cancelled);
                                }
                            } else {
                                release_promoted_resize_render_tokens(
                                    &mut self.pending_render_token_resize_epochs,
                                    &mut self.pending_render_tokens,
                                    epoch,
                                );
                            }
                        }
                        if let Err(error) = dispatch_focus_change(
                            self.wasm_runtime.as_ref(),
                            self.input_sender.as_mut(),
                            change,
                            self.window_focused,
                        ) {
                            self.fail(event_loop, error);
                            return;
                        }
                    }
                    Ok(None) => {
                        if let Some(epoch) = promoting_resize_epoch {
                            if promoting_resize_degraded {
                                let cancelled = take_resize_render_tokens_for_epoch(
                                    &mut self.pending_render_token_resize_epochs,
                                    epoch,
                                );
                                for token in &cancelled {
                                    self.pending_render_tokens.remove(token);
                                }
                                if let Some(graphics) = self.plugin_graphics.as_ref() {
                                    graphics.cancel_accepted_tokens(cancelled);
                                }
                            } else {
                                release_promoted_resize_render_tokens(
                                    &mut self.pending_render_token_resize_epochs,
                                    &mut self.pending_render_tokens,
                                    epoch,
                                );
                            }
                        }
                    }
                    Err(error) => {
                        self.fail(event_loop, error);
                        return;
                    }
                }
                let composition_graphics = self.plugin_graphics.clone();
                let composition_tokens =
                    composition_graphics
                        .as_ref()
                        .map_or_else(Vec::new, |graphics| {
                            graphics.composable_tokens_through(
                                self.pending_render_tokens.iter().copied(),
                                callback_target_ns,
                            )
                        });
                let render_outcome = renderer.render(|composed_at| {
                    if let Some(graphics) = composition_graphics.as_ref() {
                        graphics
                            .mark_frames_composed(composition_tokens.iter().copied(), composed_at);
                    }
                });
                // Composition can reveal a pre-armed next opportunity whose
                // deadline was intentionally hidden while the prior frame was
                // only graphics-ready. Install that deadline in this same
                // causal callback; continuous input must not defer it until
                // `about_to_wait`.
                composition_revealed_deadline = true;
                match render_outcome {
                    RenderOutcome::Presented {
                        sequence,
                        submission,
                        reconfigure,
                        timings,
                        submitted_at,
                        presented_at,
                        geometry_invariant,
                    } => {
                        callback_guard.set_driver_present_ns(timings.driver_present_ns);
                        callback_guard.render_timings = Some(timings);
                        if sequence.is_some() {
                            let frame_sequences = self.gpu_scene_completions.claim_submission(
                                renderer.generation,
                                current_frame_sequences.iter().copied(),
                            );
                            if !frame_sequences.is_empty() {
                                let profile_id = if brood_profiler::enabled() {
                                    let id = brood_profiler::next_id();
                                    brood_profiler::flow(
                                        brood_profiler::Kind::FlowStart,
                                        "gpu",
                                        "queue_submitted",
                                        id,
                                        vec![(
                                            "frame_sequences".into(),
                                            frame_sequences.len().into(),
                                        )],
                                    );
                                    id
                                } else {
                                    0
                                };
                                let request = GpuSubmissionRequest {
                                    renderer_generation: renderer.generation,
                                    device: renderer.device.clone(),
                                    submission,
                                    frame_sequences,
                                    profile_id,
                                };
                                let enqueue_result = self
                                    .gpu_submission_completion
                                    .as_mut()
                                    .context("GPU-submission completion lane is unavailable")
                                    .and_then(|lane| lane.enqueue(request));
                                if let Err(error) = enqueue_result {
                                    self.fail(event_loop, error);
                                    return;
                                }
                            }
                        }
                        self.renderer_recoveries = 0;
                        renderer.note_frame_presented();
                        if let Some(graphics) = self.plugin_graphics.as_ref() {
                            let tail_us = timings
                                .encode_us
                                .saturating_add(timings.submit_us)
                                .saturating_add(timings.present_us);
                            graphics.note_host_tail(
                                u64::try_from(tail_us.saturating_mul(1_000)).unwrap_or(u64::MAX),
                            );
                        }
                        self.render_scheduling_present_count =
                            self.render_scheduling_present_count.saturating_add(1);
                        if let Some(pane) = resize_element_pane
                            && let Some(sample) = renderer.resize_element_geometry(pane)
                        {
                            let present_ns = self
                                .plugin_graphics
                                .as_ref()
                                .map_or(0, PluginGraphicsBridge::render_now_ns);
                            let interval_us = self
                                .resize_element_last_present_ns
                                .map_or(0, |previous| present_ns.saturating_sub(previous) / 1_000);
                            self.resize_element_last_present_ns = Some(present_ns);
                            let position_error_x =
                                sample.geometry.drawn_rect[0] - sample.geometry.expected_rect[0];
                            let position_error_y =
                                sample.geometry.drawn_rect[1] - sample.geometry.expected_rect[1];
                            let size_error_w =
                                sample.geometry.drawn_rect[2] - sample.geometry.expected_rect[2];
                            let size_error_h =
                                sample.geometry.drawn_rect[3] - sample.geometry.expected_rect[3];
                            eprintln!(
                                "resize-element-present name=new-session-button present={} time_ns={} interval_us={} pane={} sequence={} source_extent={}x{} target_rect={}:{}:{}:{} source_rect={:.4}:{:.4}:{:.4}:{:.4} drawn_rect={:.4}:{:.4}:{:.4}:{:.4} expected_rect={:.4}:{:.4}:{:.4}:{:.4} error={:.4}:{:.4}:{:.4}:{:.4}",
                                self.render_scheduling_present_count,
                                present_ns,
                                interval_us,
                                pane,
                                sample.sequence,
                                sample.source_extent.0,
                                sample.source_extent.1,
                                sample.target_rect[0],
                                sample.target_rect[1],
                                sample.target_rect[2],
                                sample.target_rect[3],
                                sample.geometry.source_rect[0],
                                sample.geometry.source_rect[1],
                                sample.geometry.source_rect[2],
                                sample.geometry.source_rect[3],
                                sample.geometry.drawn_rect[0],
                                sample.geometry.drawn_rect[1],
                                sample.geometry.drawn_rect[2],
                                sample.geometry.drawn_rect[3],
                                sample.geometry.expected_rect[0],
                                sample.geometry.expected_rect[1],
                                sample.geometry.expected_rect[2],
                                sample.geometry.expected_rect[3],
                                position_error_x,
                                position_error_y,
                                size_error_w,
                                size_error_h,
                            );
                        }
                        self.winit_driver_present_calls =
                            self.winit_driver_present_calls.saturating_add(1);
                        self.winit_driver_present_samples_ns
                            .push_back(timings.driver_present_ns);
                        if self.winit_driver_present_samples_ns.len() > 4_096 {
                            self.winit_driver_present_samples_ns.pop_front();
                        }
                        if !self.render_scheduling_forced_recovery
                            && std::env::var(
                                "BROOD_RENDER_SCHEDULING_FORCE_RECOVERY_AFTER_PRESENTS",
                            )
                            .ok()
                            .and_then(|value| value.parse::<u64>().ok())
                                == Some(self.render_scheduling_present_count)
                        {
                            self.render_scheduling_forced_recovery = true;
                            if let Some(proxy) = &self.event_proxy {
                                drop(proxy.send_event(ClientEvent::RendererFailed {
                                    generation: renderer.generation,
                                    message: "render-scheduling forced recovery".to_owned(),
                                }));
                            }
                        }
                        if std::env::var_os("BROOD_TRACE_RESIZE").is_some() {
                            let trace = self.resize_presentation_trace;
                            let layout_extent = renderer.layout_extent();
                            eprintln!(
                                "resize-present interaction={} event_sequence={} epoch={} divider_x={} composition_size={}x{} phase={} wait_ready={}/{} staged_count={} managed_expectations={} managed_staged_resources={} degraded={} superseded_epochs={}",
                                trace.interaction,
                                trace.event_sequence,
                                trace.epoch,
                                renderer.primary_divider_x(),
                                layout_extent.w,
                                layout_extent.h,
                                trace.phase,
                                trace.wait_ready,
                                trace.wait_total,
                                renderer.staged_layout_count(),
                                renderer.managed_resize_counts().0,
                                renderer.managed_resize_counts().1,
                                trace.degraded,
                                trace.superseded_epochs,
                            );
                            let paint = renderer.layout_paint_order_trace();
                            eprintln!(
                                "resize-paint-order ordinary_panes={} dividers={} explicit_overlay_panes={} elevated_overlay_panes={} low_z_divider_over_ordinary={}",
                                paint.ordinary_panes,
                                paint.dividers,
                                paint.explicit_overlay_panes,
                                paint.elevated_overlay_panes,
                                paint.low_z_divider_over_ordinary,
                            );
                            eprintln!(
                                "render-geometry-invariant panes={} verified={} missing_surfaces={} missing_painted_extents={} area_mismatches={} geometry_mismatches={} details=[{}]",
                                geometry_invariant.panes,
                                geometry_invariant.verified,
                                geometry_invariant.missing_surfaces,
                                geometry_invariant.missing_painted_extents,
                                geometry_invariant.area_mismatches,
                                geometry_invariant.geometry_mismatches,
                                geometry_invariant.details.join(","),
                            );
                            let projection = renderer.render_content_projection();
                            eprintln!(
                                "render-content-projection panes={} projected_panes={} max_width_delta={} max_height_delta={} max_scale_error_ppm={} details=[{}]",
                                projection.panes,
                                projection.projected_panes,
                                projection.max_width_delta,
                                projection.max_height_delta,
                                projection.max_scale_error_ppm,
                                projection.details.join(","),
                            );
                        }
                        if let Some(benchmark) = self.plugin_scroll_benchmark.as_mut() {
                            benchmark.record_present(Instant::now(), timings);
                        }
                        let now = Instant::now();
                        if let Some(graphics) = self.plugin_graphics.as_ref() {
                            self.render_predictor
                                .observe_presented(graphics.render_now_ns());
                            for token in &composition_tokens {
                                self.pending_render_tokens.remove(token);
                            }
                            let scheduler_warmup_completed = graphics.mark_frame_presented(
                                composition_tokens,
                                submitted_at,
                                presented_at,
                                true,
                            );
                            if scheduler_warmup_completed {
                                self.render_scheduling_warmup_complete = true;
                                if std::env::var_os("BROOD_RENDER_SCHEDULING_PROOF").is_some() {
                                    eprintln!("render scheduling proof warmup complete");
                                }
                            }
                        }
                        let mut completed_inputs = Vec::new();
                        self.pending_plugin_inputs.retain(|input| {
                            if input.ready {
                                completed_inputs.push((
                                    now.duration_since(input.started).as_micros(),
                                    input.backend,
                                    input.pane,
                                    input.trace_sequence,
                                    input.started,
                                    input.started_unix_us,
                                    input.transport_queued,
                                    input.transport_sent,
                                    input.transport_received,
                                    input.snapshot_dispatched,
                                    input.graphics_ready,
                                ));
                                false
                            } else {
                                true
                            }
                        });
                        if std::env::var_os("BROOD_TRACE_PLUGIN_INPUT").is_some()
                            && !PLUGIN_SCROLL_BENCH_ACTIVE.load(Ordering::Relaxed)
                        {
                            eprintln!(
                                "terminal input drain pending_plugin_inputs={}",
                                self.pending_plugin_inputs.len()
                            );
                        }
                        for (
                            elapsed,
                            backend,
                            pane,
                            trace_sequence,
                            started,
                            started_unix_us,
                            transport_queued,
                            transport_sent,
                            transport_received,
                            snapshot_dispatched,
                            graphics_ready,
                        ) in completed_inputs
                        {
                            self.plugin_key_to_present_samples =
                                self.plugin_key_to_present_samples.saturating_add(1);
                            self.plugin_last_key_to_present_us = elapsed;
                            self.plugin_max_key_to_present_us =
                                self.plugin_max_key_to_present_us.max(elapsed);
                            self.plugin_key_to_present_latencies.push_back(elapsed);
                            if self.plugin_key_to_present_latencies.len() > 4_096 {
                                self.plugin_key_to_present_latencies.pop_front();
                            }
                            if let Some(backend) = backend {
                                let samples = self
                                    .plugin_key_to_present_by_backend
                                    .entry(backend)
                                    .or_default();
                                push_bounded(samples, elapsed);
                                if let (
                                    Some(transport_received),
                                    Some(snapshot_dispatched),
                                    Some(graphics_ready),
                                ) = (transport_received, snapshot_dispatched, graphics_ready)
                                {
                                    self.plugin_latency_stages_by_backend
                                        .entry(backend)
                                        .or_default()
                                        .record(
                                            started,
                                            transport_queued,
                                            transport_sent,
                                            transport_received,
                                            snapshot_dispatched,
                                            graphics_ready,
                                            now,
                                        );
                                    if let Some(trace_sequence) = trace_sequence
                                        && let (Some(transport_queued), Some(transport_sent)) =
                                            (transport_queued, transport_sent)
                                    {
                                        let traces = self
                                            .plugin_input_traces_by_backend
                                            .entry(backend)
                                            .or_default();
                                        traces.push_back(serde_json::json!({
                                            "sequence": trace_sequence,
                                            "pane": pane,
                                            "started_unix_us": started_unix_us,
                                            "total_us": elapsed,
                                            "input_to_transport_queue_us": transport_queued
                                                .duration_since(started)
                                                .as_micros(),
                                            "transport_send_queue_us": transport_sent
                                                .duration_since(transport_queued)
                                                .as_micros(),
                                            "remote_round_trip_us": transport_received
                                                .duration_since(transport_sent)
                                                .as_micros(),
                                            "client_dispatch_us": snapshot_dispatched
                                                .duration_since(transport_received)
                                                .as_micros(),
                                            "plugin_render_us": graphics_ready
                                                .duration_since(snapshot_dispatched)
                                                .as_micros(),
                                            "presentation_us": now
                                                .duration_since(graphics_ready)
                                                .as_micros(),
                                        }));
                                        if traces.len() > 4_096 {
                                            traces.pop_front();
                                        }
                                    }
                                }
                            }
                        }
                        if reconfigure {
                            renderer.reconfigure();
                            let refresh_interval_ns =
                                window_refresh_interval_ns(renderer.window.as_ref());
                            self.render_predictor.reset(refresh_interval_ns);
                            self.render_refresh_interval_ns = refresh_interval_ns;
                        }
                        if let Err(error) = self.complete_presented_layout_revision() {
                            self.fail(event_loop, error);
                            return;
                        }
                        match self.complete_presented_synchronized_resize() {
                            Ok(Some(change)) => {
                                if let Err(error) = dispatch_focus_change(
                                    self.wasm_runtime.as_ref(),
                                    self.input_sender.as_mut(),
                                    change,
                                    self.window_focused,
                                ) {
                                    self.fail(event_loop, error);
                                    return;
                                }
                            }
                            Ok(None) => {}
                            Err(error) => {
                                self.fail(event_loop, error);
                                return;
                            }
                        }
                        match self.complete_presented_native_window_resize_fallback() {
                            Ok(Some(change)) => {
                                if let Err(error) = dispatch_focus_change(
                                    self.wasm_runtime.as_ref(),
                                    self.input_sender.as_mut(),
                                    change,
                                    self.window_focused,
                                ) {
                                    self.fail(event_loop, error);
                                    return;
                                }
                            }
                            Ok(None) => {}
                            Err(error) => {
                                self.fail(event_loop, error);
                                return;
                            }
                        }
                        self.emit_native_window_resize_trace();
                    }
                    RenderOutcome::Skipped => {
                        if let Some(benchmark) = self.plugin_scroll_benchmark.as_mut() {
                            benchmark.record_skipped();
                        }
                    }
                    RenderOutcome::Reconfigure => {
                        if let Some(benchmark) = self.plugin_scroll_benchmark.as_mut() {
                            benchmark.record_reconfigure();
                        }
                        renderer.reconfigure();
                        let refresh_interval_ns =
                            window_refresh_interval_ns(renderer.window.as_ref());
                        self.render_predictor.reset(refresh_interval_ns);
                        self.render_refresh_interval_ns = refresh_interval_ns;
                    }
                    RenderOutcome::Failed(message) => {
                        let generation = renderer.generation;
                        if let Err(error) = self.recover_renderer(generation, message) {
                            self.renderer_failures = self.renderer_failures.saturating_add(1);
                            self.fail(event_loop, error);
                        }
                    }
                }
            }
            _ => {}
        }
        if composition_revealed_deadline
            && let Err(error) = self.synchronize_event_loop_deadline(false)
        {
            self.fail(event_loop, error);
        }
    }
}

fn plugin_logical_key(key: &Key) -> String {
    match key {
        Key::Character(character) => character.to_string(),
        Key::Named(named) => match named {
            NamedKey::Enter => "Enter",
            NamedKey::Escape => "Escape",
            NamedKey::Backspace => "Backspace",
            NamedKey::Tab => "Tab",
            NamedKey::Home => "Home",
            NamedKey::End => "End",
            NamedKey::PageUp => "PageUp",
            NamedKey::PageDown => "PageDown",
            NamedKey::Insert => "Insert",
            NamedKey::Delete => "Delete",
            NamedKey::ArrowUp => "ArrowUp",
            NamedKey::ArrowDown => "ArrowDown",
            NamedKey::ArrowLeft => "ArrowLeft",
            NamedKey::ArrowRight => "ArrowRight",
            NamedKey::F1 => "F1",
            NamedKey::F2 => "F2",
            NamedKey::F3 => "F3",
            NamedKey::F4 => "F4",
            NamedKey::F5 => "F5",
            NamedKey::F6 => "F6",
            NamedKey::F7 => "F7",
            NamedKey::F8 => "F8",
            NamedKey::F9 => "F9",
            NamedKey::F10 => "F10",
            NamedKey::F11 => "F11",
            NamedKey::F12 => "F12",
            _ => "",
        }
        .to_string(),
        Key::Dead(character) => {
            character.map_or_else(String::new, |character| character.to_string())
        }
        Key::Unidentified(_) => String::new(),
    }
}

fn plugin_text_input(
    logical_key: &Key,
    event_text: Option<&str>,
    modifiers: ModifiersState,
) -> Option<String> {
    if let Some(text) = event_text.filter(|text| !text.is_empty()) {
        return Some(text.to_string());
    }
    if modifiers.control_key() || modifiers.alt_key() || modifiers.super_key() {
        return None;
    }
    let Key::Character(character) = logical_key else {
        return None;
    };
    (!character.is_empty() && !character.chars().any(char::is_control))
        .then(|| character.to_string())
}

const MAX_MANAGED_RESIZE_EXPECTATIONS: usize = 128;
const MAX_MANAGED_RETIRED_EPOCH_FLOORS: usize = 4096;

#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct ManagedPaneRoute {
    backend: BackendId,
    connection_generation: u64,
    backend_pane: u64,
    view_pane: u64,
}

#[derive(Clone, Debug)]
enum ManagedResizeExpectationState {
    PendingSend,
    Issued,
    Configured,
    Staged(SceneWindow),
    Recovered,
}

#[derive(Clone, Debug)]
struct ManagedResizeExpectation {
    route: ManagedPaneRoute,
    epoch: u64,
    wait: bool,
    pixel_size: (u32, u32),
    logical_size: (u32, u32),
    scale_120: u32,
    state: ManagedResizeExpectationState,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ManagedFrameDisposition {
    Ordinary,
    ProtectedOrdinary,
    ExactTagged,
    DropTagged,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ManagedResizeStatusDisposition {
    None,
    Recovered { pane: u64, wait: bool },
    ProtocolViolation { pane: u64, epoch: u64 },
}

#[derive(Default)]
struct ManagedResizeState {
    expectations: BTreeMap<u64, ManagedResizeExpectation>,
    retired_epoch_floors: BTreeMap<(BackendId, u64, u64), u64>,
}

impl ManagedResizeState {
    fn expected_pixel_size(&self, pane: u64, epoch: u64) -> Option<(u32, u32)> {
        let expectation = self.expectations.get(&pane)?;
        (expectation.epoch == epoch).then_some(expectation.pixel_size)
    }

    fn admit(&mut self, expectation: ManagedResizeExpectation) -> Result<()> {
        anyhow::ensure!(
            managed_resize_epoch_is_valid(expectation.epoch)
                && expectation.route.backend_pane > 0
                && expectation.route.view_pane > 0,
            "managed resize expectation identity is invalid"
        );
        anyhow::ensure!(
            self.expectations.len() < MAX_MANAGED_RESIZE_EXPECTATIONS
                || self.expectations.contains_key(&expectation.route.view_pane),
            "managed resize expectation capacity is exhausted"
        );
        let floor_key = (
            expectation.route.backend,
            expectation.route.connection_generation,
            expectation.route.backend_pane,
        );
        let route_is_known = self.retired_epoch_floors.contains_key(&floor_key)
            || self.expectations.values().any(|current| {
                (
                    current.route.backend,
                    current.route.connection_generation,
                    current.route.backend_pane,
                ) == floor_key
            });
        anyhow::ensure!(
            route_is_known
                || self.retired_epoch_floors.len() + self.expectations.len()
                    < MAX_MANAGED_RETIRED_EPOCH_FLOORS,
            "managed retired epoch floor capacity is exhausted"
        );
        anyhow::ensure!(
            self.retired_epoch_floors
                .get(&floor_key)
                .is_none_or(|floor| expectation.epoch > *floor),
            "managed resize epoch is already retired"
        );
        anyhow::ensure!(
            self.expectations
                .get(&expectation.route.view_pane)
                .is_none_or(|current| current.epoch == expectation.epoch),
            "managed pane already has another active resize epoch"
        );
        self.expectations
            .insert(expectation.route.view_pane, expectation);
        Ok(())
    }

    fn disposition(
        &self,
        backend: BackendId,
        generation: u64,
        backend_pane: u64,
        view_pane: u64,
        epoch: Option<u64>,
    ) -> ManagedFrameDisposition {
        let expectation = self.expectations.get(&view_pane).filter(|expectation| {
            expectation.route.backend == backend
                && expectation.route.connection_generation == generation
                && expectation.route.backend_pane == backend_pane
        });
        match epoch {
            Some(epoch)
                if expectation.is_some_and(|expectation| {
                    expectation.epoch == epoch
                        && matches!(
                            expectation.state,
                            ManagedResizeExpectationState::PendingSend
                                | ManagedResizeExpectationState::Issued
                                | ManagedResizeExpectationState::Configured
                                | ManagedResizeExpectationState::Staged(_)
                        )
                }) =>
            {
                ManagedFrameDisposition::ExactTagged
            }
            Some(_) => ManagedFrameDisposition::DropTagged,
            None if expectation.is_some() => ManagedFrameDisposition::ProtectedOrdinary,
            None => ManagedFrameDisposition::Ordinary,
        }
    }

    fn stage(&mut self, pane: u64, epoch: u64, frame: SceneWindow) -> (bool, Option<SceneWindow>) {
        let Some(expectation) = self.expectations.get_mut(&pane) else {
            return (false, None);
        };
        if expectation.epoch != epoch
            || matches!(expectation.state, ManagedResizeExpectationState::Recovered)
        {
            return (false, None);
        }
        let previous = std::mem::replace(
            &mut expectation.state,
            ManagedResizeExpectationState::Staged(frame),
        );
        let previous = match previous {
            ManagedResizeExpectationState::Staged(frame) => Some(frame),
            ManagedResizeExpectationState::PendingSend
            | ManagedResizeExpectationState::Issued
            | ManagedResizeExpectationState::Configured
            | ManagedResizeExpectationState::Recovered => None,
        };
        (true, previous)
    }

    fn configured(
        &mut self,
        route: ManagedPaneRoute,
        status: brood_protocol::ManagedResizeStatus,
    ) -> ManagedResizeStatusDisposition {
        let Some(expectation) = self.expectations.get_mut(&route.view_pane) else {
            return ManagedResizeStatusDisposition::None;
        };
        if expectation.route != route || expectation.epoch != status.resize_epoch {
            return ManagedResizeStatusDisposition::None;
        }
        match status.result {
            brood_protocol::ManagedResizeStatusResult::Configured {
                logical_size,
                pixel_size,
                scale_120,
            } => {
                if logical_size != [expectation.logical_size.0, expectation.logical_size.1]
                    || pixel_size != [expectation.pixel_size.0, expectation.pixel_size.1]
                    || scale_120 != expectation.scale_120
                {
                    if matches!(expectation.state, ManagedResizeExpectationState::Staged(_)) {
                        return ManagedResizeStatusDisposition::ProtocolViolation {
                            pane: route.view_pane,
                            epoch: expectation.epoch,
                        };
                    }
                    let wait = expectation.wait;
                    let epoch = expectation.epoch;
                    let _ = expectation;
                    self.recover(route.view_pane, epoch);
                    return ManagedResizeStatusDisposition::Recovered {
                        pane: route.view_pane,
                        wait,
                    };
                }
                if matches!(expectation.state, ManagedResizeExpectationState::Issued) {
                    expectation.state = ManagedResizeExpectationState::Configured;
                }
                ManagedResizeStatusDisposition::None
            }
            brood_protocol::ManagedResizeStatusResult::Rejected { .. } => {
                if matches!(expectation.state, ManagedResizeExpectationState::Staged(_)) {
                    return ManagedResizeStatusDisposition::ProtocolViolation {
                        pane: route.view_pane,
                        epoch: expectation.epoch,
                    };
                }
                let wait = expectation.wait;
                let epoch = expectation.epoch;
                let _ = expectation;
                self.recover(route.view_pane, epoch);
                ManagedResizeStatusDisposition::Recovered {
                    pane: route.view_pane,
                    wait,
                }
            }
        }
    }

    fn recover(&mut self, pane: u64, epoch: u64) -> Option<bool> {
        let expectation = self.expectations.get_mut(&pane)?;
        if expectation.epoch != epoch
            || matches!(expectation.state, ManagedResizeExpectationState::Staged(_))
        {
            return None;
        }
        let key = (
            expectation.route.backend,
            expectation.route.connection_generation,
            expectation.route.backend_pane,
        );
        let wait = expectation.wait;
        expectation.state = ManagedResizeExpectationState::Recovered;
        let floor = self.retired_epoch_floors.entry(key).or_default();
        *floor = (*floor).max(epoch);
        Some(wait)
    }

    fn retire_epoch(&mut self, epoch: u64) -> Vec<ManagedResizeExpectation> {
        let panes = self
            .expectations
            .iter()
            .filter_map(|(pane, expectation)| (expectation.epoch == epoch).then_some(*pane))
            .collect::<Vec<_>>();
        let mut retired = Vec::with_capacity(panes.len());
        for pane in panes {
            let Some(expectation) = self.expectations.remove(&pane) else {
                continue;
            };
            let key = (
                expectation.route.backend,
                expectation.route.connection_generation,
                expectation.route.backend_pane,
            );
            let floor = self.retired_epoch_floors.entry(key).or_default();
            *floor = (*floor).max(expectation.epoch);
            retired.push(expectation);
        }
        retired
    }

    #[allow(
        clippy::needless_collect,
        reason = "matching keys must be snapshotted before mutating the same expectation map"
    )]
    fn remove_backend(&mut self, backend: BackendId) -> Vec<ManagedResizeExpectation> {
        let panes = self
            .expectations
            .iter()
            .filter_map(|(pane, expectation)| {
                (expectation.route.backend == backend).then_some(*pane)
            })
            .collect::<Vec<_>>();
        let removed = panes
            .into_iter()
            .filter_map(|pane| self.expectations.remove(&pane))
            .collect::<Vec<_>>();
        self.retired_epoch_floors
            .retain(|(owner, _generation, _pane), _epoch| *owner != backend);
        removed
    }

    fn remove_pane(&mut self, route: ManagedPaneRoute) -> Option<ManagedResizeExpectation> {
        self.retired_epoch_floors.remove(&(
            route.backend,
            route.connection_generation,
            route.backend_pane,
        ));
        self.expectations.remove(&route.view_pane)
    }
}

fn prepare_managed_state_for_gpu_loss(
    current_windows: &mut [SceneWindow],
    managed_resizes: &mut ManagedResizeState,
    frame_keys: &BTreeMap<(BackendId, u64), u64>,
    sent_managed_sizes: &mut HashMap<u64, (u32, u32)>,
    pending_ordinary_recovery: &mut BTreeMap<u64, PendingOrdinaryManagedRecovery>,
    pending_releases: &mut BTreeSet<(BackendId, u64)>,
) -> BTreeSet<u64> {
    // Every imported texture belongs to the failed device. Release its
    // producer resource even when it was superseded between scene snapshots.
    pending_releases.extend(frame_keys.keys().copied());

    let expected_panes = managed_resizes
        .expectations
        .keys()
        .copied()
        .collect::<BTreeSet<_>>();
    for window in current_windows {
        if window.transport_resource_owned {
            pending_releases.insert((window.backend, window.transport_resource_id));
            window.transport_resource_owned = false;
        }
        if !expected_panes.contains(&window.window_id) {
            sent_managed_sizes.remove(&window.window_id);
            pending_ordinary_recovery.insert(
                window.window_id,
                PendingOrdinaryManagedRecovery {
                    recover_through_epoch: None,
                    held_for_successor_epoch: None,
                },
            );
        }
    }

    let mut invalidated_staged_panes = BTreeSet::new();
    for (pane, expectation) in &mut managed_resizes.expectations {
        let ManagedResizeExpectationState::Staged(frame) = &expectation.state else {
            continue;
        };
        pending_releases.insert((frame.backend, frame.transport_resource_id));
        invalidated_staged_panes.insert(*pane);
        // The producer already knows the epoch, but the tagged resource was
        // tied to the failed device. Reissuing the same request is the only
        // state which can produce a fresh exact frame and make the wait ready.
        expectation.state = ManagedResizeExpectationState::PendingSend;
    }
    invalidated_staged_panes
}

fn invalidate_synchronized_ready_panes(
    ready_panes: &mut BTreeSet<u64>,
    invalidated_staged_managed_panes: &BTreeSet<u64>,
) {
    ready_panes.retain(|pane| !invalidated_staged_managed_panes.contains(pane));
}

fn synchronized_plugin_replay_plan(
    mut staged_scenes: Vec<(u64, u64)>,
    epoch: u64,
    ready_panes: &BTreeSet<u64>,
    plugin_panes: &BTreeMap<u64, Option<(BackendId, u64)>>,
) -> Vec<(u64, u64)> {
    staged_scenes
        .retain(|(pane, staged_epoch)| *staged_epoch == epoch && ready_panes.contains(pane));
    staged_scenes.extend(
        ready_panes
            .iter()
            .filter(|pane| plugin_panes.contains_key(pane))
            .map(|pane| (*pane, epoch)),
    );
    staged_scenes.sort_unstable();
    staged_scenes.dedup();
    staged_scenes
}

fn take_for_renderer_recovery<T, S>(
    renderer: &mut Option<T>,
    into_recovery_state: impl FnOnce(T) -> S,
) -> Result<S> {
    let old = renderer.take().context("lost renderer during recovery")?;
    Ok(into_recovery_state(old))
}

