    #[test]
    fn renderer_recovery_drops_old_protocol_resources_before_replacement() {
        struct ProtocolResource(std::rc::Rc<std::cell::RefCell<Vec<&'static str>>>);

        impl Drop for ProtocolResource {
            fn drop(&mut self) {
                self.0.borrow_mut().push("old-protocol-resource-dropped");
            }
        }

        struct RendererFixture {
            _protocol_resource: ProtocolResource,
            durable_state: u64,
        }

        let events = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let mut renderer = Some(RendererFixture {
            _protocol_resource: ProtocolResource(std::rc::Rc::clone(&events)),
            durable_state: 41,
        });
        let durable_state = take_for_renderer_recovery(&mut renderer, |old| {
            let RendererFixture {
                _protocol_resource: _,
                durable_state,
            } = old;
            durable_state
        })
        .unwrap();

        events.borrow_mut().push("replacement-created");
        assert_eq!(durable_state, 41);
        assert!(renderer.is_none());
        assert_eq!(
            *events.borrow(),
            ["old-protocol-resource-dropped", "replacement-created"]
        );
    }

    #[test]
    fn renderer_gpu_loss_retires_each_current_resource_once_and_requests_fresh_frames() {
        let mut current = vec![managed_scene(7, 70), managed_scene(8, 80)];
        let mut managed = ManagedResizeState::default();
        let frame_keys = BTreeMap::from([
            ((BackendId(3), 70), 1070),
            ((BackendId(3), 80), 1080),
            ((BackendId(3), 90), 1090),
        ]);
        let mut sent_sizes = HashMap::from([(7, (200, 100)), (8, (200, 100))]);
        let mut pending_ordinary = BTreeMap::new();
        let mut releases = BTreeSet::from([(BackendId(3), 70)]);

        let invalidated = prepare_managed_state_for_gpu_loss(
            &mut current,
            &mut managed,
            &frame_keys,
            &mut sent_sizes,
            &mut pending_ordinary,
            &mut releases,
        );

        assert!(invalidated.is_empty());
        assert!(
            current
                .iter()
                .all(|window| !window.transport_resource_owned)
        );
        assert_eq!(
            pending_ordinary,
            BTreeMap::from([
                (
                    7,
                    PendingOrdinaryManagedRecovery {
                        recover_through_epoch: None,
                        held_for_successor_epoch: None,
                    },
                ),
                (
                    8,
                    PendingOrdinaryManagedRecovery {
                        recover_through_epoch: None,
                        held_for_successor_epoch: None,
                    },
                ),
            ])
        );
        assert!(sent_sizes.is_empty());
        assert_eq!(
            releases,
            BTreeSet::from([(BackendId(3), 70), (BackendId(3), 80), (BackendId(3), 90),])
        );

        // Re-entering preparation cannot manufacture a second release for a
        // current scene whose ownership was already transferred.
        prepare_managed_state_for_gpu_loss(
            &mut current,
            &mut managed,
            &BTreeMap::new(),
            &mut sent_sizes,
            &mut pending_ordinary,
            &mut releases,
        );
        assert_eq!(releases.len(), 3);
    }

    #[test]
    fn renderer_gpu_loss_rearms_staged_managed_frame_and_unblocks_resize_wait() {
        let mut current = vec![managed_scene(7, 70)];
        let mut expectation = managed_expectation(7, 41, true);
        expectation.state = ManagedResizeExpectationState::Staged(managed_scene(7, 71));
        let mut managed = ManagedResizeState::default();
        managed.expectations.insert(7, expectation);
        let frame_keys = BTreeMap::from([((BackendId(3), 70), 1070), ((BackendId(3), 71), 1071)]);
        let mut sent_sizes = HashMap::from([(7, (200, 100))]);
        let mut pending_ordinary = BTreeMap::new();
        let mut releases = BTreeSet::new();
        let invalidated = prepare_managed_state_for_gpu_loss(
            &mut current,
            &mut managed,
            &frame_keys,
            &mut sent_sizes,
            &mut pending_ordinary,
            &mut releases,
        );

        assert_eq!(invalidated, BTreeSet::from([7]));
        assert!(matches!(
            managed.expectations[&7].state,
            ManagedResizeExpectationState::PendingSend
        ));
        assert!(pending_ordinary.is_empty());
        assert_eq!(
            releases,
            BTreeSet::from([(BackendId(3), 70), (BackendId(3), 71)])
        );

        let mut ready = BTreeSet::from([7, 9]);
        invalidate_synchronized_ready_panes(&mut ready, &invalidated);
        assert_eq!(ready, BTreeSet::from([9]));
        assert_eq!(
            managed
                .expectations
                .values()
                .filter(|expectation| matches!(
                    expectation.state,
                    ManagedResizeExpectationState::PendingSend
                ))
                .count(),
            1,
            "the synchronized transaction can make progress by resending the exact request"
        );
    }

    #[test]
    fn queued_renderer_releases_retry_without_releasing_successes_twice() {
        let mut pending =
            BTreeSet::from([(BackendId(3), 70), (BackendId(3), 71), (BackendId(4), 70)]);
        let attempted = std::mem::take(&mut pending);
        assert_eq!(attempted.len(), 3);
        // Model one failed lane send: only that ownership record is retained.
        pending.insert((BackendId(3), 71));
        let retried = std::mem::take(&mut pending);
        assert_eq!(retried, BTreeSet::from([(BackendId(3), 71)]));
        assert!(pending.is_empty());
    }

    #[test]
    fn promoted_synchronized_resize_rebuilds_ready_plugin_stage_after_gpu_loss() {
        // Promotion consumes the old GPU staged-scene map before presenting.
        // Recovery still has to reconstruct tagged plugin content from the
        // bridge so the re-armed transaction cannot wait or promote forever.
        let ready = BTreeSet::from([7, 8]);
        let plugin_panes = BTreeMap::from([(7, None)]);
        let replay = synchronized_plugin_replay_plan(Vec::new(), 41, &ready, &plugin_panes);
        assert_eq!(replay, vec![(7, 41)]);

        let replay = synchronized_plugin_replay_plan(
            vec![(7, 40), (7, 41), (9, 41)],
            41,
            &ready,
            &plugin_panes,
        );
        assert_eq!(replay, vec![(7, 41)]);
    }

    #[test]
    fn proof_gate_is_exactly_bound_and_releases_only_for_a_newer_epoch() {
        let authority =
            proof_managed_frame_authority(41, &[managed_route(7), managed_route(8)]).unwrap();
        let scene =
            |backend, connection_generation, tagged: &[(u64, u64)]| ClientEvent::SceneFrame {
                backend,
                connection_generation,
                sequence: 9,
                width: 640,
                height: 480,
                windows: tagged
                    .iter()
                    .map(|(backend_pane, epoch)| SceneWindowUpdate {
                        backend,
                        backend_window_id: *backend_pane,
                        window_id: *backend_pane,
                        resource_id: *backend_pane + 1_000,
                        rect: [0, 0, 300, 150],
                        active: false,
                        resize_epoch: Some(*epoch),
                        resource: None,
                    })
                    .collect(),
            };
        assert!(complete_tagged_managed_scene(
            &scene(BackendId(3), 5, &[(107, 41), (108, 41)]),
            &authority,
        ));
        for invalid in [
            scene(BackendId(4), 5, &[(107, 41), (108, 41)]),
            scene(BackendId(3), 6, &[(107, 41), (108, 41)]),
            scene(BackendId(3), 5, &[(107, 41)]),
            scene(BackendId(3), 5, &[(107, 41), (109, 41)]),
            scene(BackendId(3), 5, &[(107, 41), (108, 42)]),
            scene(BackendId(3), 5, &[(107, 41), (107, 41)]),
        ] {
            assert!(!complete_tagged_managed_scene(&invalid, &authority));
        }
        assert!(proof_managed_frame_authority(41, &[managed_route(7)]).is_none());
        let mut wrong_generation = managed_route(8);
        wrong_generation.connection_generation = 6;
        assert!(proof_managed_frame_authority(41, &[managed_route(7), wrong_generation]).is_none());

        let mut held = Some((41, "scene-a"));
        assert_eq!(take_superseded_proof_frame(&mut held, Some(41)), None);
        assert_eq!(held, Some((41, "scene-a")));
        assert_eq!(take_superseded_proof_frame(&mut held, Some(40)), None);
        assert_eq!(take_superseded_proof_frame(&mut held, None), None);
        assert_eq!(
            take_superseded_proof_frame(&mut held, Some(42)),
            Some((41, "scene-a"))
        );
        assert_eq!(held, None);

        let mut armed = Some(authority);
        let mut terminal = Some((41, "scene-b"));
        assert_eq!(
            take_terminal_proof_frame(&mut armed, &mut terminal, 40),
            None
        );
        assert!(armed.is_some());
        assert_eq!(terminal, Some((41, "scene-b")));
        assert_eq!(
            take_terminal_proof_frame(&mut armed, &mut terminal, 41),
            Some((41, "scene-b"))
        );
        assert!(armed.is_none());
        assert!(terminal.is_none());
    }

    #[test]
    fn q4_explicit_stale_panes_preserve_visible_windows_focus_and_dirty_state() {
        let current = vec![managed_scene(7, 70), managed_scene(8, 80)];
        let previous_inventory = current
            .iter()
            .map(|window| (window.backend, window.window_id))
            .collect::<BTreeSet<_>>();
        let previous_focus = Some(FocusedPane::Managed(8));
        let preserve_panes = BTreeSet::from([7, 8]);

        let preserved = preserved_managed_scene_windows(
            &current,
            BackendId(3),
            &preserve_panes,
            &BTreeSet::new(),
        );
        assert_eq!(
            preserved
                .iter()
                .map(|window| (window.window_id, window.transport_resource_id))
                .collect::<Vec<_>>(),
            vec![(7, 70), (8, 80)]
        );
        let managed_panes = preserved
            .iter()
            .map(|window| window.window_id)
            .collect::<Vec<_>>();
        let focus = selected_managed_scene_focus(previous_focus, [], &managed_panes, None, false);
        let inventory = preserved
            .iter()
            .map(|window| (window.backend, window.window_id))
            .collect::<BTreeSet<_>>();
        assert_eq!(focus, previous_focus);
        assert!(!managed_scene_changes_layout_state(
            &previous_inventory,
            &inventory,
            previous_focus,
            focus,
        ));
    }

    #[test]
    fn withdrawn_managed_surface_survives_until_replacement_layout_commits() {
        let mut current = vec![managed_scene(7, 70), managed_scene(8, 80)];
        let old_layout = ResolvedLayout {
            items: vec![test_pane_item(7, -1.0, 1.0), test_pane_item(8, 0.0, 1.0)],
        };
        let live = BTreeSet::from([7]);
        let mut newly_arrived = vec![managed_scene(9, 90)];
        assert!(
            retire_withdrawn_managed_scenes(&mut newly_arrived, &live, &old_layout).is_empty(),
            "a new snapshot arriving before catalog publication is not a withdrawal"
        );
        assert!(retire_withdrawn_managed_scenes(&mut current, &live, &old_layout).is_empty());
        let preserved = preserved_managed_scene_windows(
            &current,
            BackendId(3),
            &BTreeSet::from([7, 8]),
            &BTreeSet::from([7]),
        );
        assert_eq!(preserved.len(), 1);
        assert_eq!(preserved[0].transport_resource_id, 80);
        current.retain(|window| window.window_id == 7);
        current.extend(preserved);
        assert!(retire_withdrawn_managed_scenes(&mut current, &live, &old_layout).is_empty());
        let replacement = ResolvedLayout {
            items: vec![test_pane_item(7, -1.0, 2.0)],
        };
        let retired = retire_withdrawn_managed_scenes(&mut current, &live, &replacement);
        assert_eq!(retired.len(), 1);
        assert_eq!(retired[0].transport_resource_id, 80);
        assert_eq!(current.len(), 1);
        assert!(retire_withdrawn_managed_scenes(&mut current, &live, &replacement).is_empty());
    }

