    fn degraded_projection() -> ProjectedPluginScenes {
        let mut projections = ProjectedPluginScenes::default();
        projections.mark(7, 41, 10, [0, 0, 500, 600]);
        projections
    }

    #[test]
    fn timeout_keeps_the_exact_visible_scene_projected() {
        let projections = degraded_projection();
        assert!(projections.blocks_extent_sync(7, 10));
        assert_eq!(
            projections.panes.get(&7),
            Some(&ProjectedPluginScene {
                resize_epoch: 41,
                visible_sequence: 10,
                target_rect: [0, 0, 500, 600],
            })
        );
    }

    #[test]
    fn accepted_newer_ordinary_scene_ends_degraded_projection() {
        let mut projections = degraded_projection();
        assert!(projections.accept_ordinary(7, 11));
        assert!(!projections.blocks_extent_sync(7, 11));
    }

    #[test]
    fn later_tagged_promotion_ends_degraded_projection() {
        let mut projections = degraded_projection();
        assert!(!projections.promote_tagged(7, 41, 11));
        assert!(!projections.promote_tagged(7, 42, 10));
        assert!(projections.promote_tagged(7, 42, 11));
        assert!(projections.panes.is_empty());
    }

    #[test]
    fn successful_reuse_carries_projected_scene_to_the_new_transaction() {
        let mut projections = degraded_projection();
        assert!(projections.promote_reuse(7, 42, 10, [0, 0, 620, 600]));
        assert_eq!(
            projections.panes.get(&7),
            Some(&ProjectedPluginScene {
                resize_epoch: 42,
                visible_sequence: 10,
                target_rect: [0, 0, 620, 600],
            })
        );
        assert!(projections.blocks_extent_sync(7, 10));
        assert!(!projections.promote_reuse(7, 41, 10, [0, 0, 500, 600]));
    }

    #[test]
    fn stale_draw_cannot_end_or_recompile_degraded_projection() {
        let mut projections = degraded_projection();
        assert!(projections.blocks_extent_sync(7, 9));
        assert!(!projections.accept_ordinary(7, 9));
        assert!(!projections.accept_ordinary(7, 10));
        assert!(projections.blocks_extent_sync(7, 10));
    }

    #[test]
    fn degraded_projection_cleans_up_on_pane_layout_and_authority_reset() {
        let extent = LayoutSize { w: 1000, h: 600 };
        let pane = test_pane_item(8, -1.0, 1.0);
        let rect = pane.pixel_rect(extent);
        let layout = ResolvedLayout { items: vec![pane] };
        let mut projections = degraded_projection();
        projections.mark(8, 42, 12, [rect.x, rect.y, rect.w, rect.h]);
        projections.remove(7);
        projections.retain_layout(&layout, extent);
        assert!(projections.panes.contains_key(&8));

        let changed = ResolvedLayout {
            items: vec![test_pane_item(8, -1.0, 1.2)],
        };
        projections.retain_layout(&changed, extent);
        assert!(projections.panes.is_empty());
        projections.mark(9, 43, 13, [0, 0, 1000, 600]);
        projections.clear();
        assert!(projections.panes.is_empty());
    }

    #[test]
    fn interaction_chain_accepts_only_revisions_from_its_current_lineage() {
        assert!(synchronized_base_is_applicable(8, 8, None));
        assert!(!synchronized_base_is_applicable(7, 8, None));
        assert!(synchronized_base_is_applicable(5, 8, Some(5)));
        assert!(synchronized_base_is_applicable(7, 8, Some(5)));
        assert!(synchronized_base_is_applicable(8, 8, Some(5)));
        assert!(!synchronized_base_is_applicable(4, 8, Some(5)));
        assert!(!synchronized_base_is_applicable(9, 8, Some(5)));
    }

    fn active_resize_with_inventory(
        presentation: SynchronizedResizePresentation,
    ) -> Result<ActiveSynchronizedResize> {
        let mut target_tree = LayoutLeaseTree::default();
        target_tree.update_inventory(1, &[7, 8, 9])?;
        let root = target_tree.root_token();
        target_tree.submit(
            root,
            1,
            brood_layout::LayoutFragment {
                layout: ResolvedLayout {
                    items: vec![
                        test_pane_item(7, -1.0, 1.0),
                        brood_layout::ResolvedLayoutItem {
                            kind: LayoutItemKind::OverlayPane { pane: 8 },
                            ..test_pane_item(8, 0.0, 1.0)
                        },
                    ],
                },
                zones: Vec::new(),
                dividers: Vec::new(),
                rest: None,
            },
            Some(7),
        )?;
        let now = Instant::now();
        let base_tree = target_tree.clone();
        Ok(ActiveSynchronizedResize {
            request_id: 11,
            interaction: None,
            event_sequence: 1,
            interaction_claim: None,
            native_resize_revision: None,
            interaction_preview: false,
            host_owned: false,
            superseded_epochs: 0,
            epoch: brood_wasm::ResizeEpoch {
                id: 41,
                lease: root.id.0,
                lease_generation: root.generation,
                base_layout_revision: 1,
                target_layout_revision: 2,
            },
            requester: ActorIdentity {
                name: "layout".to_string(),
                generation: 7,
            },
            base_tree,
            target_tree,
            target_extent: LayoutSize { w: 1000, h: 600 },
            regions: BTreeMap::new(),
            wait_pane_owners: BTreeMap::from([(7, root), (8, root)]),
            notified_panes: BTreeSet::new(),
            recovered_regions: BTreeSet::new(),
            recovered_managed_panes: BTreeSet::new(),
            recovered_managed_content: BTreeMap::new(),
            focus: None,
            wait_panes: BTreeSet::from([7, 8]),
            ready_panes: BTreeSet::new(),
            affected_panes: BTreeSet::from([7, 8]),
            started: now,
            deadline: now + SYNCHRONIZED_RESIZE_TIMEOUT,
            presentation,
        })
    }

    #[test]
    fn compatible_dirty_inventory_waits_for_exact_synchronized_completion() -> Result<()> {
        assert!(layout_state_publication_is_deferred(true, true));
        assert!(!layout_state_publication_is_deferred(false, true));

        let mut timed_out = active_resize_with_inventory(SynchronizedResizePresentation::Waiting)?;
        assert_eq!(
            prepare_synchronized_resize_presentation(&mut timed_out, true),
            Some((true, vec![7, 8])),
            "the normal bounded deadline remains able to publish a degraded cohort"
        );

        let mut active = active_resize_with_inventory(SynchronizedResizePresentation::Waiting)?;
        active.ready_panes.clone_from(&active.wait_panes);
        assert_eq!(
            prepare_synchronized_resize_presentation(&mut active, false),
            Some((false, Vec::new()))
        );
        assert!(matches!(
            active.presentation,
            SynchronizedResizePresentation::Ready {
                degraded: false,
                ref missing_panes,
            } if missing_panes.is_empty()
        ));
        Ok(())
    }

    fn active_resize_with_region_chain() -> Result<ActiveSynchronizedResize> {
        let mut base_tree = LayoutLeaseTree::default();
        base_tree.update_inventory(1, &[1, 2, 3])?;
        let root = base_tree.root_token();
        let middle = base_tree.grant_rest(root, &[2, 3])?;
        let leaf = base_tree.grant_rest(middle, &[3])?;
        let child_slot = |offset_u, size_u| brood_layout::LayoutChildSlot {
            z: 0.0,
            transform: brood_layout::LocalTransform {
                offset: LocalPoint {
                    u: offset_u,
                    v: -1.0,
                },
                size: LocalPoint { u: size_u, v: 2.0 },
            },
        };
        base_tree.submit(
            root,
            1,
            brood_layout::LayoutFragment {
                layout: ResolvedLayout {
                    items: vec![test_pane_item(1, -1.0, 0.5)],
                },
                zones: Vec::new(),
                dividers: Vec::new(),
                rest: Some(child_slot(-0.5, 1.5)),
            },
            Some(1),
        )?;
        base_tree.submit(
            middle,
            1,
            brood_layout::LayoutFragment {
                layout: ResolvedLayout {
                    items: vec![test_pane_item(2, -1.0, 1.0)],
                },
                zones: Vec::new(),
                dividers: Vec::new(),
                rest: Some(child_slot(0.0, 1.0)),
            },
            Some(2),
        )?;
        base_tree.submit(
            leaf,
            1,
            brood_layout::LayoutFragment {
                layout: ResolvedLayout {
                    items: vec![test_pane_item(3, -1.0, 2.0)],
                },
                zones: Vec::new(),
                dividers: Vec::new(),
                rest: None,
            },
            Some(3),
        )?;
        let mut target_tree = base_tree.clone();
        target_tree.submit(
            root,
            1,
            brood_layout::LayoutFragment {
                layout: ResolvedLayout {
                    items: vec![test_pane_item(1, -1.0, 0.7)],
                },
                zones: Vec::new(),
                dividers: Vec::new(),
                rest: Some(child_slot(-0.3, 1.3)),
            },
            Some(1),
        )?;
        let now = Instant::now();
        Ok(ActiveSynchronizedResize {
            request_id: 11,
            interaction: None,
            event_sequence: 1,
            interaction_claim: None,
            native_resize_revision: None,
            interaction_preview: false,
            host_owned: false,
            superseded_epochs: 0,
            epoch: brood_wasm::ResizeEpoch {
                id: 41,
                lease: root.id.0,
                lease_generation: root.generation,
                base_layout_revision: 1,
                target_layout_revision: 2,
            },
            requester: ActorIdentity {
                name: "root".to_string(),
                generation: 7,
            },
            base_tree,
            target_tree,
            target_extent: LayoutSize { w: 1000, h: 600 },
            regions: BTreeMap::from([
                (
                    middle.id,
                    LayoutRegionDependency {
                        lease: middle,
                        holder: ActorIdentity {
                            name: "middle".to_string(),
                            generation: 8,
                        },
                        source_viewport: LayoutRect {
                            x: 250,
                            y: 0,
                            w: 750,
                            h: 600,
                        },
                        target_viewport: LayoutRect {
                            x: 350,
                            y: 0,
                            w: 650,
                            h: 600,
                        },
                        issued_at: now,
                        delivered: true,
                        state: LayoutRegionResolutionState::Pending,
                    },
                ),
                (
                    leaf.id,
                    LayoutRegionDependency {
                        lease: leaf,
                        holder: ActorIdentity {
                            name: "leaf".to_string(),
                            generation: 9,
                        },
                        source_viewport: LayoutRect {
                            x: 625,
                            y: 0,
                            w: 375,
                            h: 600,
                        },
                        target_viewport: LayoutRect {
                            x: 675,
                            y: 0,
                            w: 325,
                            h: 600,
                        },
                        issued_at: now,
                        delivered: false,
                        state: LayoutRegionResolutionState::Pending,
                    },
                ),
            ]),
            wait_pane_owners: BTreeMap::from([(1, root), (2, middle), (3, leaf)]),
            notified_panes: BTreeSet::new(),
            recovered_regions: BTreeSet::new(),
            recovered_managed_panes: BTreeSet::new(),
            recovered_managed_content: BTreeMap::new(),
            focus: Some(1),
            wait_panes: BTreeSet::from([1, 2, 3]),
            ready_panes: BTreeSet::new(),
            affected_panes: BTreeSet::from([1, 2, 3]),
            started: now,
            deadline: now + SYNCHRONIZED_RESIZE_TIMEOUT,
            presentation: SynchronizedResizePresentation::Waiting,
        })
    }

    fn application_with_region_chain() -> Result<(Application, LayoutRegionDependency)> {
        let active = active_resize_with_region_chain()?;
        let middle = active.regions[&LayoutLeaseId(2)].clone();
        let mut application = Application {
            layout_leases: active.base_tree.clone(),
            active_synchronized_resize: Some(active),
            ..Application::default()
        };
        application
            .layout_holders
            .insert(middle.lease.id, middle.holder.clone());
        let leaf = application
            .active_synchronized_resize
            .as_ref()
            .unwrap()
            .regions[&LayoutLeaseId(3)]
            .clone();
        application
            .layout_holders
            .insert(leaf.lease.id, leaf.holder);
        Ok((application, middle))
    }

