    fn queued_runtime_ordinary_layout_reply_blocks_setup_quiescence() -> Result<()> {
        let mut runtime = PresentationWasmRuntime::start(&[], None, None, None, None)?;
        runtime.retain_test_host_message(
            br#"{"type":"set-resolved-layout","lease":null,"revision":null,"layout":{"items":[],"zones":[],"dividers":[]},"rest":null,"focus":null}"#.to_vec(),
        );
        let mut state = SetupLayoutQuiescence {
            presented_layout_revision: 7,
            inventory_revision: 4,
            runtime_outbound_host_messages: runtime.pending_outbound_host_messages(),
            layout_publications_current: true,
            ..SetupLayoutQuiescence::default()
        };
        assert_eq!(state.runtime_outbound_host_messages, 1);
        assert!(!state.is_ready());

        assert_eq!(runtime.drain_host_messages()?.len(), 1);
        state.runtime_outbound_host_messages = runtime.pending_outbound_host_messages();
        assert_eq!(state.runtime_outbound_host_messages, 0);
        assert!(state.is_ready());
        runtime.shutdown()
    }

    #[test]
    fn bounded_actor_runtime_backlogs_block_setup_quiescence() {
        let ready = SetupLayoutQuiescence {
            presented_layout_revision: 7,
            inventory_revision: 4,
            layout_publications_current: true,
            ..SetupLayoutQuiescence::default()
        };
        assert!(ready.is_ready());
        assert!(
            !SetupLayoutQuiescence {
                runtime_pending_actor_inputs: 1,
                ..ready
            }
            .is_ready()
        );
        assert!(
            !SetupLayoutQuiescence {
                runtime_observer_output_backlog: true,
                ..ready
            }
            .is_ready()
        );
    }

    #[test]
    fn layout_state_publishes_presented_panes_and_root_native_nonce_additively() {
        let mut message = LayoutStateMessage {
            message_type: "layout-state",
            revision: 4,
            inventory_revision: 4,
            layout_revision: 8,
            presented_layout_revision: 8,
            lease: brood_wasm::LayoutLeaseToken {
                id: 1,
                generation: 2,
            },
            waitable_panes: vec![3, 7, 9],
            presented_panes: vec![3, 7],
            visible_panes: vec![3],
            native_resize_revision: Some(11),
            active_session: 5,
            available_windows: Vec::new(),
            pane_realms: Vec::new(),
            focused_pane: Some(3),
            pane_app_ids: Vec::new(),
            size: LayoutStateSize { w: 1440, h: 900 },
            rest: true,
        };
        let encoded = serde_json::to_value(&message).expect("layout state must serialize");
        assert_eq!(encoded["presented_panes"], serde_json::json!([3, 7]));
        assert_eq!(encoded["native_resize_revision"], 11);

        message.native_resize_revision = None;
        let child = serde_json::to_value(&message).expect("child layout state must serialize");
        assert!(child.get("native_resize_revision").is_none());
        let root = LayoutLeaseId(1);
        let child = LayoutLeaseId(2);
        assert!(lease_receives_layout_publication(root, root, Some(11)));
        assert!(!lease_receives_layout_publication(child, root, Some(11)));
        assert!(lease_receives_layout_publication(child, root, None));
    }

    #[test]
    fn size_only_layout_publication_preserves_root_and_child_fragments() -> Result<()> {
        let mut leases = LayoutLeaseTree::default();
        leases.update_inventory(4, &[1, 2])?;
        let root = leases.root_token();
        let child = leases.grant_rest(root, &[2])?;
        leases.submit(
            root,
            4,
            brood_layout::LayoutFragment {
                layout: ResolvedLayout {
                    items: vec![test_pane_item(1, -1.0, 1.0)],
                },
                zones: Vec::new(),
                dividers: Vec::new(),
                rest: Some(brood_layout::LayoutChildSlot {
                    z: 0.0,
                    transform: brood_layout::LocalTransform {
                        offset: LocalPoint { u: 0.0, v: -1.0 },
                        size: LocalPoint { u: 1.0, v: 2.0 },
                    },
                }),
            },
            None,
        )?;
        leases.submit(
            child,
            4,
            brood_layout::LayoutFragment {
                layout: ResolvedLayout {
                    items: vec![test_pane_item(2, -1.0, 2.0)],
                },
                zones: Vec::new(),
                dividers: Vec::new(),
                rest: None,
            },
            None,
        )?;
        let before = leases.compose()?;

        anyhow::ensure!(!layout_inventory_requires_update(&leases, &[1, 2]));
        anyhow::ensure!(layout_inventory_requires_update(&leases, &[1, 2, 3]));
        // A viewport/focus publication clears delivery acknowledgements, but
        // deliberately does not call update_inventory and lose fragments.
        let after = leases.compose()?;
        anyhow::ensure!(leases.inventory_revision() == 4);
        anyhow::ensure!(before == after);
        Ok(())
    }

    #[test]
    fn terminal_trace_sequences_are_carried_by_input_and_snapshot_messages() {
        let mut input = vec![b'I'];
        input.extend_from_slice(&17_u64.to_le_bytes());
        input.push(b'a');
        assert_eq!(terminal_input_sequence(&input), Some(17));

        let mut reliable = vec![0; 35];
        reliable[0] = b'J';
        reliable[1..9].copy_from_slice(&18_u64.to_le_bytes());
        reliable[33] = 1;
        assert_eq!(terminal_input_sequence(&reliable), Some(18));
        reliable[33] = 0;
        assert_eq!(terminal_input_sequence(&reliable), None);
        reliable[33] = 2;
        assert_eq!(terminal_input_sequence(&reliable), None);
        assert_eq!(terminal_input_sequence(&reliable[..33]), None);
        reliable[33] = 3;
        assert_eq!(terminal_input_sequence(&reliable), Some(18));

        let mut snapshot = vec![0_u8; 41];
        snapshot[..4].copy_from_slice(b"BTRM");
        snapshot[4] = 4;
        snapshot[14..22].copy_from_slice(&17_u64.to_le_bytes());
        snapshot[37..39].copy_from_slice(&1_u16.to_le_bytes());
        snapshot[39..41].copy_from_slice(&2_u16.to_le_bytes());
        assert_eq!(terminal_snapshot_input_sequence(&snapshot), Some(17));
        assert!(terminal_snapshot_completes_revision(&snapshot));

        snapshot[37..39].copy_from_slice(&0_u16.to_le_bytes());
        assert!(!terminal_snapshot_completes_revision(&snapshot));
    }

    #[test]
    fn terminal_text_latency_admission_excludes_non_text_shortcuts() {
        assert!(should_track_terminal_text_input(0, Some("a")));
        assert!(should_track_terminal_text_input(0b0100, Some("A")));
        assert!(should_track_terminal_text_input(0b1000, Some("X")));
        assert!(!should_track_terminal_text_input(0, None));
        assert!(!should_track_terminal_text_input(0, Some("")));
        assert!(!should_track_terminal_text_input(0b0001, Some("c")));
        assert!(!should_track_terminal_text_input(0b0010, Some("x")));
        assert!(!should_track_terminal_text_input(0b0101, Some("C")));
        assert!(!should_track_terminal_text_input(0b0101, Some("V")));
        assert!(!should_track_terminal_text_input(0b0111, Some("C")));
        assert_eq!(
            (0..720)
                .filter(|_| should_track_terminal_text_input(0, Some("a")))
                .count(),
            720
        );
    }

    #[test]
    fn latency_stages_partition_one_key_to_present_sample() {
        let started = Instant::now();
        let queued = started + Duration::from_micros(1);
        let sent = queued + Duration::from_micros(2);
        let transport = sent + Duration::from_micros(5);
        let snapshot = transport + Duration::from_micros(2);
        let graphics = snapshot + Duration::from_micros(3);
        let presented = graphics + Duration::from_micros(5);
        let mut stages = PluginLatencyStages::default();
        stages.record(
            started,
            Some(queued),
            Some(sent),
            transport,
            snapshot,
            graphics,
            presented,
        );
        assert_eq!(stages.input_to_transport_queue, VecDeque::from([1]));
        assert_eq!(stages.transport_send_queue, VecDeque::from([2]));
        assert_eq!(stages.remote_round_trip, VecDeque::from([5]));
        assert_eq!(stages.transport_round_trip, VecDeque::from([8]));
        assert_eq!(stages.client_dispatch, VecDeque::from([2]));
        assert_eq!(stages.plugin_render, VecDeque::from([3]));
        assert_eq!(stages.presentation, VecDeque::from([5]));
    }

